function revealComposerActions() {
  const trigger = screen.queryByRole("button", { name: "Attachments and actions" });
  if (trigger?.getAttribute("aria-expanded") === "false") fireEvent.click(trigger);
  const panel = screen.queryByRole("group", { name: "Composer actions" });
  const advanced = panel?.querySelector<HTMLDetailsElement>("details");
  const summary = advanced?.querySelector("summary");
  if (advanced && !advanced.open && summary) fireEvent.click(summary);
}

function getComposerAction(name: string) {
  const direct = screen.queryByRole<HTMLButtonElement>("button", { name });
  if (direct) return direct;
  revealComposerActions();
  return screen.getByRole<HTMLButtonElement>("button", { name });
}

function findComposerAction(name: string) {
  return waitFor(() => getComposerAction(name));
}

test("opens the next unread channel explicitly and at its normal read boundary", async () => {
  const origin = { id: "-42", name: "Fixture source channel", initials: "FS", color: "#246dbd", subtitle: "Channel", messages: [] };
  const destination = { ...origin, id: "-44", name: "Fixture unread channel", unread: 3 };
  const message = (id: string, text: string) => ({ id, author: "Fixture", text, time: "" });
  const loadHistory = vi.fn(async (id: string) => ({ before: null, messages: id === origin.id ? [message("50", "Channel end fixture")] : [] }));
  const loadUnreadHistory = vi.fn(async (id: string) => id === destination.id ? {
    before: null, messages: [message("70", "Read boundary fixture"), message("71", "First unread fixture")],
    openAt: "70", readInbox: 70,
  } : null);
  const markChat = vi.fn();
  render(<TelegramPage live={{
    chats: [origin, { ...origin, id: "-43", name: "Fixture read channel" }, destination],
    folders: [], list: "main", selectList: vi.fn(), refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory, loadUnreadHistory, markChat, sendText: vi.fn(),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture source channel/ }));
  const next = await screen.findByRole("button", { name: "Next unread channel · Fixture unread channel" });
  const history = next.closest("ol")!;
  fireEvent.wheel(history, { deltaY: 400 });
  expect(loadUnreadHistory).not.toHaveBeenCalledWith(destination.id);
  expect(screen.getByText("Channel end fixture")).toBeTruthy();
  fireEvent.click(next);
  expect(await screen.findByText("First unread fixture")).toBeTruthy();
  expect(loadUnreadHistory).toHaveBeenCalledWith(destination.id);
  expect(markChat).not.toHaveBeenCalled();
});

test("searches for unread channels only on request and ignores a late result after navigation", async () => {
  const first = { id: "-42", name: "First channel", initials: "F", color: "#246dbd", subtitle: "Channel", messages: [] };
  const second = { ...first, id: "-43", name: "Second channel" };
  const archived = { ...first, id: "-44", name: "Archived unread", unread: 4 };
  let resolve!: (result: { chat: typeof archived; list: "archive" }) => void;
  const findNextUnreadChannel = vi.fn(() => new Promise<{ chat: typeof archived; list: "archive" }>((done) => { resolve = done; }));
  const selectList = vi.fn();
  render(<TelegramPage live={{
    chats: [first, second], folders: [], list: "main", selectList, refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ before: null, messages: [] }), findNextUnreadChannel, sendText: vi.fn(),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /First channel/ }));
  const start = await screen.findByRole("button", { name: "Find next unread channel" });
  expect(findNextUnreadChannel).not.toHaveBeenCalled();
  fireEvent.click(start);
  fireEvent.click(screen.getByRole("button", { name: /Second channel/ }));
  await act(async () => resolve({ chat: archived, list: "archive" }));
  expect(selectList).not.toHaveBeenCalled();
  fireEvent.click(await screen.findByRole("button", { name: "Find next unread channel" }));
  await act(async () => resolve({ chat: archived, list: "archive" }));
  await screen.findByRole("heading", { name: archived.name });
  expect(selectList).toHaveBeenCalledExactlyOnceWith("archive");
});

test.each(["loaded", "paginated"])("opens the next visible unread forum topic from a %s list", async (mode) => {
  const origin = { id: 17, name: "Fixture source topic", closed: false, unread: 1 };
  const destination = { id: 18, name: "Fixture unread topic", closed: false, unread: 2 };
  const hidden = { id: 19, name: "Fixture hidden topic", closed: false, hidden: true as const, unread: 10 };
  const topics = mode === "loaded" ? [origin, hidden, destination] : [origin, hidden];
  const cursor = { date: 1700000000, message: 20, topic: origin.id };
  const loadForumTopicPage = mode === "paginated" ? vi.fn(async (_id: string, _query: string, offset?: typeof cursor) =>
    offset ? { topics: [destination], next: null } : { topics, next: cursor }) : undefined;
  const markForumTopicRead = vi.fn(async () => true);
  const loadTopicHistory = vi.fn(async (_id: string, topic: number) => ({
    before: null, unreadCount: topic === origin.id ? 0 : 1, messages: [{
      id: String(topic * 100), author: "Fixture", text: topic === origin.id ? "Topic end fixture" : "Next topic fixture", time: "",
    }],
  }));
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Fixture group", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: vi.fn(), refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(),
    loadForumTopics: async () => topics, loadTopicHistory, loadForumTopicPage, markForumTopicRead,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture group/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  const results = await screen.findByRole("list", { name: "Forum topic results" });
  fireEvent.click(results.querySelector<HTMLButtonElement>('[data-topic-row="17"]')!);
  const next = await screen.findByRole("button", { name: mode === "loaded"
    ? "Next unread topic · Fixture unread topic" : "Find next unread topic" });
  expect(next.closest("ol")).toBe(screen.getByRole("list", { name: "Topic messages" }));
  fireEvent.click(next);
  expect(await screen.findByText("Next topic fixture")).toBeTruthy();
  expect(screen.queryByRole("button", { name: /Next unread topic · Fixture source topic/ })).toBeNull();
  if (loadForumTopicPage) expect(loadForumTopicPage).toHaveBeenCalledWith("-42", "", cursor);
  expect(loadTopicHistory).toHaveBeenCalledWith("-42", destination.id, undefined);
  expect(markForumTopicRead).not.toHaveBeenCalled();
});

test("shows unread activity per topic and refreshes counters while the topic list is open", async () => {
  const topic = { id: 17, name: "Fixture topic", closed: false };
  const loadForumTopicPage = vi.fn()
    .mockResolvedValueOnce({ topics: [{ ...topic, unread: 8, unreadMentions: 2, unreadReactions: 1,
      preview: { text: "Fixture preview", time: "12:10", outgoing: false } }], next: null })
    .mockResolvedValueOnce({ topics: [{ ...topic, unread: 3 }], next: null })
    .mockResolvedValueOnce({ topics: [topic, { id: 18, name: "Other topic", closed: false, unread: 4 }], next: null });
  const markForumTopicRead = vi.fn(async () => true);
  const live = {
    chats: [{ id: "-42", name: "Fixture group", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: async () => ({ state: "failed" as const }),
    loadForumTopics: async () => [topic], loadTopicHistory: async () => ({ messages: [], before: null }), loadForumTopicPage, markForumTopicRead,
  };
  const view = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture group/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  await screen.findByLabelText("8 unread messages");
  expect(screen.getByText("Fixture preview")).toBeTruthy();
  expect(screen.getByText("12:10")).toBeTruthy();
  expect(screen.getByLabelText("2 unread mentions")).toBeTruthy();
  expect(screen.getByLabelText("1 unread reactions")).toBeTruthy();
  view.rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  await screen.findByLabelText("3 unread messages");
  expect(screen.queryByText("Fixture preview")).toBeNull();
  expect(screen.queryByLabelText("2 unread mentions")).toBeNull();
  expect(screen.queryByLabelText("1 unread reactions")).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Mark Fixture topic as read" }));
  await screen.findByLabelText("4 unread messages");
  expect(screen.queryByLabelText("3 unread messages")).toBeNull();
  expect(markForumTopicRead).toHaveBeenCalledExactlyOnceWith("-42", 17);
});

test.each([0, 54])("restores a paginated forum list after opening a topic when a row above grows by %s px", async (growth) => {
  const first = { id: 17, name: "First fixture topic", closed: false };
  const second = { id: 18, name: "Second fixture topic", closed: false };
  const cursor = { date: 2, message: 10, topic: 17 };
  const loadForumTopicPage = vi.fn(async (_chatId: string, _query: string, next?: typeof cursor) =>
    next ? { topics: [second], next: null } : { topics: [first], next: cursor });
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Fixture group", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(),
    loadForumTopics: async () => [first], loadTopicHistory: async () => ({ messages: [], before: null }), loadForumTopicPage,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture group/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(await screen.findByRole("button", { name: "Load more topics" }));
  const row = await screen.findByRole("button", { name: second.name });
  const panel = screen.getByRole("region", { name: "Forum topics" });
  let rowTop = 360;
  const originalRect = HTMLButtonElement.prototype.getBoundingClientRect;
  const rect = vi.spyOn(HTMLButtonElement.prototype, "getBoundingClientRect").mockImplementation(function (this: HTMLButtonElement) {
    return this.dataset.topicRow === "18" ? new DOMRect(0, rowTop - panel.scrollTop, 200, 30) : originalRect.call(this);
  });
  try {
    panel.scrollTop = 300;
    fireEvent.click(row);
    await screen.findByRole("heading", { name: second.name });
    panel.scrollTop = 0;
    rowTop += growth;
    fireEvent.click(screen.getByRole("button", { name: "Back to topics" }));
    expect(panel.scrollTop).toBe(300 + growth);
    const returned = screen.getByRole("button", { name: second.name });
    expect(document.activeElement).toBe(returned);
    expect(returned.getBoundingClientRect().top).toBe(60);
    expect(loadForumTopicPage.mock.calls).toEqual([["-42", "", undefined], ["-42", "", cursor]]);
  } finally { rect.mockRestore(); }
});

