test.each([false, true])("shows bot-specific topic actions only when available (create and delete: %s)", async (allowed) => {
  const topic = { id: 17, name: "Bot fixture topic", closed: false };
  const manageForumTopic = vi.fn(async () => ({ ...topic, pinned: true as const }));
  const deleteForumTopic = vi.fn(async () => "deleted" as const);
  const loadForumTopicPage = vi.fn(async () => ({ topics: [topic], next: null,
    ...(allowed && { canCreateBotTopics: true as const }) }));
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture bot", initials: "B", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(),
    loadForumTopics: async () => [], loadForumTopicPage,
    loadTopicHistory: async () => ({ messages: [], before: null }), manageForumTopic, deleteForumTopic,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture bot/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  const row = await screen.findByRole("button", { name: topic.name });
  expect(!!screen.queryByText("New topic")).toBe(allowed);
  fireEvent.click(row);
  screen.getByText("Topic settings").closest("details")!.open = true;
  expect(screen.getByRole("button", { name: "Rename topic" })).toBeTruthy();
  expect(screen.queryByRole("button", { name: "Close topic" })).toBeNull();
  expect(screen.queryByRole("button", { name: "Hide General topic" })).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Pin topic" }));
  await screen.findByRole("button", { name: "Unpin topic" });
  expect(manageForumTopic).toHaveBeenCalledExactlyOnceWith("42", { kind: "pin", topic: 17, pinned: true });
  const remove = screen.queryByRole("button", { name: "Delete topic" });
  expect(!!remove).toBe(allowed);
  if (!remove) return;
  fireEvent.click(remove);
  const confirm = screen.getByRole<HTMLButtonElement>("button", { name: "Delete topic for everyone" });
  expect(confirm.disabled).toBe(true);
  expect(deleteForumTopic).not.toHaveBeenCalled();
  fireEvent.change(screen.getByRole("textbox", { name: "Type the topic name" }), { target: { value: topic.name } });
  fireEvent.click(confirm);
  await waitFor(() => expect(deleteForumTopic).toHaveBeenCalledExactlyOnceWith("42", 17, topic.name));
});

test("refreshes pinned topic order before offering an explicit retry after a conflict", async () => {
  const topic = { id: 18, name: "Pinned fixture topic", closed: false, pinned: true as const };
  const pinnedForumTopicOrder = vi.fn().mockResolvedValueOnce([17, 18, 19])
    .mockResolvedValueOnce([17, 19, 18]).mockResolvedValueOnce([17, 18, 19]);
  const movePinnedForumTopic = vi.fn().mockResolvedValueOnce("changed").mockResolvedValueOnce("updated");
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture bot", initials: "B", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(),
    loadForumTopics: async () => [topic], loadTopicHistory: async () => ({ messages: [], before: null }),
    pinnedForumTopicOrder, movePinnedForumTopic,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture bot/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(screen.getByRole("button", { name: /Pinned fixture topic/ }));
  expect(pinnedForumTopicOrder).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Show pinned topic order" }));
  await screen.findByText("Position 2 of 3");
  fireEvent.click(screen.getByRole("button", { name: "Move topic down" }));
  await screen.findByText("Pinned topics changed. Review their order and try again.");
  expect(screen.getByRole<HTMLButtonElement>("button", { name: "Move topic down" }).disabled).toBe(true);
  expect(movePinnedForumTopic).toHaveBeenCalledExactlyOnceWith("42", 18, "down", [17, 18, 19]);
  fireEvent.click(screen.getByRole("button", { name: "Move topic up" }));
  await screen.findByText("Pinned topic moved.");
  expect(screen.getByText("Position 2 of 3")).toBeTruthy();
  expect(movePinnedForumTopic).toHaveBeenLastCalledWith("42", 18, "up", [17, 19, 18]);
});

