  const enableHistory = vi.fn(async () => "saved" as const);
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Fixture channel", initials: "FC", color: "#246dbd", subtitle: "Channel", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "",
    liveRevision: 0, findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(),
    chatInfoActions: { load: async () => null, save: async () => "unavailable", discussion: { load, candidates, save, enableHistory } },
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture channel/ }));
  const dialog = document.querySelector("dialog")!;
  dialog.showModal = () => { dialog.open = true; };
  fireEvent.click(screen.getByRole("button", { name: "Chat details" }));
  const details = screen.getByText("Discussion group").closest("details")!;
  details.open = true;
