test("opens the earlier conversation at a migration boundary and returns to the supergroup", async () => {
  const chat = { id: "-44", name: "New fixture group", initials: "N", color: "#246dbd", subtitle: "Group", messages: [] };
  const earlier = { ...chat, id: "-43", name: "Earlier fixture group" };
  const loadNotificationChat = vi.fn(async (id: string) => id === earlier.id ? earlier : chat);
  const loadHistory = vi.fn(async (id: string, before?: string) => {
    if (id === earlier.id) return { messages: [{ id: "9", text: "Earlier chronology fixture", author: "", time: "" }],
      before: null, migration: { group: { id: chat.id, title: chat.name } } };
    if (before) return { messages: [], before: null, predecessor: { id: earlier.id, title: earlier.name } };
    return { messages: [{ id: "9", text: "Current chronology fixture", author: "", time: "" }], before: "9" };
  });
  render(<TelegramPage live={{
    chats: [chat], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "",
    liveRevision: 0, findChats: async () => [], loadHistory, loadNotificationChat, sendText: vi.fn(),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /New fixture group/ }));
  await screen.findByText("Current chronology fixture");
  expect(loadNotificationChat).not.toHaveBeenCalled();
  const loadEarlier = screen.getByRole("button", { name: "Load earlier messages" });
  fireEvent.click(loadEarlier);
  const openEarlier = await screen.findByRole("button", { name: "Open earlier group" });
  expect(loadNotificationChat).not.toHaveBeenCalled();
  fireEvent.click(openEarlier);
  await screen.findByText("Earlier chronology fixture");
  expect(screen.queryByText("Current chronology fixture")).toBeNull();
  expect(loadNotificationChat).toHaveBeenCalledExactlyOnceWith("-43");
  expect(loadHistory).toHaveBeenCalledWith("-43");
  expect(screen.queryByRole("textbox", { name: "Write a message" })).toBeNull();
  fireEvent.click(await screen.findByRole("button", { name: "Open supergroup" }));
  await screen.findByText("Current chronology fixture");
  expect(loadNotificationChat.mock.calls).toEqual([["-43"], ["-44"]]);
});

