test("switches a Mini App between modal and split without relaunching the frame", async () => {
  const { MiniAppDialog } = await import("../src/ui/mini-app.tsx");
  const prototype = HTMLDialogElement.prototype;
  const methods = ["showModal", "show", "close"] as const;
  const original = methods.map((method) => Object.getOwnPropertyDescriptor(prototype, method));
  for (const method of methods) {
    Object.defineProperty(prototype, method, { configurable: true, value(this: HTMLDialogElement) {
      this.open = method !== "close";
      if (method === "close") this.dispatchEvent(new Event("close"));
    } });
  }
  const launch = vi.fn(async () => ({ url: "https://fixture.example.com/#fixture" }));
  const close = vi.fn();
  try {
    render(<div className="mtg"><MiniAppDialog target={{ label: "Fixture app" }} launch={launch} close={close} /></div>);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle("Telegram Mini App content");
    const dialog = screen.getByRole("dialog", { name: "Telegram Mini App" });
    expect(dialog.getAttribute("aria-modal")).toBe("true");
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App in split view" }));
    expect(dialog.getAttribute("data-presentation")).toBe("split");
    expect(dialog.getAttribute("aria-modal")).toBe("false");
    expect(screen.getByTitle("Telegram Mini App content")).toBe(frame);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App as a modal" }));
    expect(dialog.getAttribute("data-presentation")).toBe("modal");
    expect(screen.getByTitle("Telegram Mini App content")).toBe(frame);
    expect(launch).toHaveBeenCalledOnce();
    expect(close).not.toHaveBeenCalled();
  } finally {
    methods.forEach((method, index) => {
      const value = original[index];
      if (value) Object.defineProperty(prototype, method, value);
      else Reflect.deleteProperty(prototype, method);
    });
  }
});

test("remembers per-app device preferences, applies edits on reload, and asks again for a new origin", async () => {
  const { MiniAppDialog } = await import("../src/ui/mini-app.tsx");
  const iframePrototype = HTMLIFrameElement.prototype;
  const dialogPrototype = HTMLDialogElement.prototype;
  const credentialless = Object.getOwnPropertyDescriptor(iframePrototype, "credentialless");
  const showModal = Object.getOwnPropertyDescriptor(dialogPrototype, "showModal");
  Object.defineProperty(iframePrototype, "credentialless", { configurable: true, value: false });
  Object.defineProperty(dialogPrototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  vi.stubGlobal("isSecureContext", true);
  const close = vi.fn(async () => true);
  let origin = "https://fixture.example.com";
  const launch = vi.fn(async () => ({ url: origin + "/#fixture", session: "fixture-session" }));
  function mount(preferenceScope = "fixture-account") {
    return render(<MiniAppSessionActions.Provider value={{ preferenceScope, close, writeAccess: async () => "unavailable" }}>
      <MiniAppDialog target={{ label: "Fixture app" }} entryPoint={["bot-profile", "54"]} launch={launch} close={() => {}} />
    </MiniAppSessionActions.Provider>);
  }
  const key = 'makosh.telegram.miniApp.fixture-account.["bot-profile","54"]';
  try {
    const initial = mount();
    expect(launch).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("checkbox", { name: "Allow camera" }));
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    await screen.findByTitle("Telegram Mini App content");
    expect(JSON.parse(localStorage.getItem(key)!)).toEqual({ origin, media: { camera: true, microphone: false } });
    initial.unmount();

    const reopened = mount();
    const oldFrame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(oldFrame.getAttribute("allow")).toContain("camera 'self'");
    fireEvent.click(screen.getByRole("button", { name: "Mini App device settings" }));
    fireEvent.click(screen.getByRole("checkbox", { name: "Allow camera" }));
    fireEvent.click(screen.getByRole("button", { name: "Save and reload Mini App" }));
    const updated = screen.getByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(updated).not.toBe(oldFrame);
    expect(updated.getAttribute("allow")).toContain("camera 'none'; microphone 'none'");
    expect(launch).toHaveBeenCalledTimes(2);
    reopened.unmount();

    const separateAccount = mount("another-account");
    expect(screen.getByRole("button", { name: "Open Mini App" })).toBeTruthy();
    expect(launch).toHaveBeenCalledTimes(2);
    separateAccount.unmount();

    origin = "https://changed.example.com";
    mount();
    const prompt = await screen.findByRole("button", { name: "Open Mini App" });
    expect(screen.queryByTitle("Telegram Mini App content")).toBeNull();
    fireEvent.click(prompt);
    await screen.findByTitle("Telegram Mini App content");
    expect(JSON.parse(localStorage.getItem(key)!).origin).toBe(origin);
  } finally {
    localStorage.removeItem(key);
    if (credentialless) Object.defineProperty(iframePrototype, "credentialless", credentialless);
    else Reflect.deleteProperty(iframePrototype, "credentialless");
    if (showModal) Object.defineProperty(dialogPrototype, "showModal", showModal);
    else Reflect.deleteProperty(dialogPrototype, "showModal");
    vi.unstubAllGlobals();
  }
});

test.each([false, true])("isolates Mini App events and delegates only reviewed devices (origin required: %s)", async (requireSameOrigin) => {
  const { createHash } = await import("node:crypto");
  const { MiniAppDialog } = await import("../src/ui/mini-app.tsx");
  const { miniAppMediaFrame } = await import("../src/core/mini-app-media.ts");
  const iframePrototype = HTMLIFrameElement.prototype;
  const credentialless = Object.getOwnPropertyDescriptor(iframePrototype, "credentialless");
  const dialogPrototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(dialogPrototype, "showModal");
  Object.defineProperty(iframePrototype, "credentialless", { configurable: true, value: false });
  Object.defineProperty(dialogPrototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  vi.stubGlobal("isSecureContext", true);
  const launch = vi.fn(async () => ({ url: 'https://fixture.example.com/media?payload=%22%3Cscript%3E&x=2', ...(requireSameOrigin && { requireSameOrigin: true as const }) }));
  try {
    render(<MiniAppDialog target={{ label: "Fixture app" }} launch={launch} close={() => {}} />);
    if (!requireSameOrigin) fireEvent.click(screen.getByRole("checkbox", { name: "Allow camera" }));
    expect(screen.getByRole<HTMLInputElement>("checkbox", { name: "Allow microphone" }).checked).toBe(false);
    expect(launch).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(frame.getAttribute("src")).toBeNull();
    expect(frame.getAttribute("allow")).toContain(requireSameOrigin ? "camera 'none'; microphone 'none'" : "camera 'self' https://fixture.example.com; microphone 'none'");
    expect(frame.getAttribute("sandbox")).toBe("allow-scripts allow-same-origin");
    const relay = new DOMParser().parseFromString(frame.srcdoc, "text/html");
    const nested = relay.querySelector("iframe")!;
    expect(nested.hasAttribute("credentialless")).toBe(true);
    expect(nested.getAttribute("src")).toBe((await launch.mock.results[0]?.value)?.url);
    expect(nested.getAttribute("allow")).toContain(requireSameOrigin ? "camera 'none'; microphone 'none'" : "camera https://fixture.example.com; microphone 'none'");
    const csp = relay.querySelector('meta[http-equiv="Content-Security-Policy"]')!.getAttribute("content");
    expect(csp).toContain("frame-src https://fixture.example.com;");
    const hash = createHash("sha256").update(relay.querySelector("script")!.textContent!).digest("base64");
    expect(csp).toContain(`script-src 'sha256-${hash}'`);
    expect(miniAppMediaFrame("https://fixture.example.com", "https://fixture.example.com", { camera: true, microphone: true })).toBeUndefined();

    const data = JSON.stringify({ eventType: "web_app_setup_main_button",
      eventData: { text: "Fixture action", is_visible: true, is_active: true } });
    fireEvent(window, new MessageEvent("message", { origin: "https://fixture.example.com", source: frame.contentWindow, data }));
    fireEvent(window, new MessageEvent("message", { origin: window.location.origin, source: window, data }));
    expect(screen.queryByRole("button", { name: "Fixture action" })).toBeNull();
    fireEvent(window, new MessageEvent("message", { origin: window.location.origin, source: frame.contentWindow, data }));
    expect(screen.getByRole("button", { name: "Fixture action" })).toBeTruthy();
  } finally {
    if (credentialless) Object.defineProperty(iframePrototype, "credentialless", credentialless);
    else Reflect.deleteProperty(iframePrototype, "credentialless");
    if (showModal) Object.defineProperty(dialogPrototype, "showModal", showModal);
    else Reflect.deleteProperty(dialogPrototype, "showModal");
    vi.unstubAllGlobals();
  }
});

