    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const post = vi.spyOn(frame.contentWindow!, "postMessage").mockImplementation(() => {});
    fireEvent(window, new MessageEvent("message", { origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_open_tg_link", eventData: { path_full: "/fixture_destination" } }) }));
