test("closes only the minimized Mini App named by a Telegram completion event", async () => {
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const closeDialog = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(prototype, "close", { configurable: true, value(this: HTMLDialogElement) { this.open = false; } });
  const listeners = new Set<(session: string) => void>();
  const closeSession = vi.fn(async () => true);
  const actions = { close: closeSession, writeAccess: async () => "unavailable" as const,
    subscribeToClosures: (listener: (session: string) => void) => {
      listeners.add(listener);
      return () => { listeners.delete(listener); };
    },
  };
  function Fixture() {
    const [showFirst, setShowFirst] = useState(true);
    const [showSecond, setShowSecond] = useState(false);
    return <MiniAppSessionActions.Provider value={actions}>
      <button type="button" onClick={() => setShowSecond(true)}>Add second app</button>
      {showFirst && <MiniAppDialog target={{ label: "First fixture app" }} close={() => setShowFirst(false)}
        launch={async () => ({ url: "https://fixture.example.com/first", session: "first-session" })} />}
      {showSecond && <MiniAppDialog target={{ label: "Second fixture app" }} close={() => setShowSecond(false)}
        launch={async () => ({ url: "https://fixture.example.com/second", session: "second-session" })} />}
    </MiniAppSessionActions.Provider>;
  }
  try {
    render(<Fixture />);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    await screen.findByTitle("Telegram Mini App content");
    fireEvent.click(screen.getByRole("button", { name: "Minimize Mini App" }));
    fireEvent.click(screen.getByRole("button", { name: "Add second app" }));
    const second = screen.getByRole("dialog", { name: "Telegram Mini App" });
    fireEvent.click(within(second).getByRole("button", { name: "Open Mini App" }));
    await within(second).findByTitle("Telegram Mini App content");
    const notify = (id: string) => act(() => { for (const listener of listeners) listener(id); });
    notify("unknown-session");
    expect(screen.getByRole("button", { name: "Resume Mini App First fixture app" })).toBeTruthy();
    notify("first-session");
    expect(screen.queryByRole("button", { name: "Resume Mini App First fixture app" })).toBeNull();
    expect(screen.getByTitle("Telegram Mini App content").getAttribute("src")).toBe("https://fixture.example.com/second");
    expect(listeners.size).toBe(1);
    expect(closeSession).not.toHaveBeenCalled();
    fireEvent.click(within(second).getByRole("button", { name: "Close Mini App" }));
    expect(closeSession).toHaveBeenCalledExactlyOnceWith("second-session");
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (closeDialog) Object.defineProperty(prototype, "close", closeDialog);
    else Reflect.deleteProperty(prototype, "close");
  }
});

