    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const post = vi.spyOn(frame.contentWindow!, "postMessage").mockImplementation(() => {});
    const request = () => fireEvent(window, new MessageEvent("message", { origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_request_phone", eventData: { recipient: "Foreign bot" } }) }));
    request();
    const prompt = await screen.findByRole("region", { name: "Share phone number" });
