test("presents one Mini App popup at a time and returns the selected button ID", async () => {
  const prototype = HTMLDialogElement.prototype;
  const original = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const clock = vi.spyOn(performance, "now").mockReturnValue(1000);
  try {
    render(<MiniAppDialog target={{ label: "Fixture" }} launch={async () => ({ url: "https://fixture.example.com/app" })} close={vi.fn()} />);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const post = vi.spyOn(frame.contentWindow!, "postMessage").mockImplementation(() => {});
    const invoice = (slug: string, source: Window | null = frame.contentWindow) =>
      fireEvent(window, new MessageEvent("message", { origin: "null", source,
        data: JSON.stringify({ eventType: "web_app_open_invoice", eventData: { slug } }) }));
    invoice("foreign", window);
    invoice("https://example.com/invalid");
    expect(post).not.toHaveBeenCalled();
    invoice("fixture-invoice");
    expect(post.mock.calls.map(([data]) => JSON.parse(String(data)))).toEqual([
      { eventType: "invoice_closed", eventData: { slug: "fixture-invoice", status: "failed" } },
    ]);
    expect(frame.isConnected).toBe(true);
    post.mockClear();
    const popup = (message: string, buttons: unknown[], source: Window | null = frame.contentWindow) =>
      fireEvent(window, new MessageEvent("message", { origin: "null", source,
        data: JSON.stringify({ eventType: "web_app_open_popup", eventData: { title: "Fixture popup", message, buttons } }) }));
    popup("Foreign", [{ type: "ok", id: "ok" }], window);
    popup("Invalid", [{ type: "unknown", id: "invalid" }]);
    popup("Ambiguous IDs", [{ type: "ok", id: "duplicate" }, { type: "cancel", id: "duplicate" }]);
    expect(screen.queryByRole("dialog", { name: "Fixture popup" })).toBeNull();
    const popupCancelled = JSON.stringify({ eventType: "popup_closed", eventData: {} });
    expect(post.mock.calls).toEqual([[popupCancelled, "*"], [popupCancelled, "*"]]);
    post.mockClear();
    popup("<b>Fixture prompt</b>", [{ type: "destructive", text: "Remove fixture", id: "remove" }, { type: "cancel", id: "cancel" }]);
    const dialog = screen.getByRole("dialog", { name: "Fixture popup" });
    expect(within(dialog).getByText("<b>Fixture prompt</b>").querySelector("b")).toBeNull();
    popup("Ignore this popup", [{ type: "ok", id: "ok" }]);
    expect(within(dialog).queryByText("Ignore this popup")).toBeNull();
    expect(post).not.toHaveBeenCalled();
    fireEvent.click(within(dialog).getByRole("button", { name: "Remove fixture" }));
    expect(screen.queryByRole("dialog", { name: "Fixture popup" })).toBeNull();
    expect(JSON.parse(String(post.mock.lastCall?.[0]))).toEqual({ eventType: "popup_closed", eventData: { button_id: "remove" } });
    fireEvent(window, new MessageEvent("message", { origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_open_popup", eventData: { message: "Default button fixture" } }) }));
    const defaultPopup = screen.getByRole("dialog", { name: "Mini App dialog" });
    fireEvent.click(within(defaultPopup).getByRole("button", { name: "Close" }));
    expect(JSON.parse(String(post.mock.lastCall?.[0]))).toEqual({ eventType: "popup_closed", eventData: { button_id: "" } });
    popup("Three decisions", [{ type: "ok", id: "yes" }, { type: "cancel", id: "cancel" }, { type: "close", id: "close" }]);
    const buttons = screen.getByRole("button", { name: "OK" }).parentElement;
    expect(buttons?.dataset.stacked).toBe("true");
    fireEvent.click(within(screen.getByRole("dialog", { name: "Fixture popup" })).getByRole("button", { name: "OK" }));
    popup("Rate limited", [{ type: "ok", id: "ok" }]);
    expect(screen.queryByText("Rate limited")).toBeNull();
    expect(post).toHaveBeenLastCalledWith(popupCancelled, "*");
    clock.mockReturnValue(4000);
    popup("After the limit clears", [{ type: "ok", id: "ok" }]);
    expect(screen.getByText("After the limit clears")).toBeTruthy();
  } finally {
    clock.mockRestore();
    if (original) Object.defineProperty(prototype, "showModal", original);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

test("scans Mini App QR codes only after camera consent and stops on close", async () => {
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const mediaDevices = Object.getOwnPropertyDescriptor(navigator, "mediaDevices");
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockResolvedValue(undefined);
  const readyState = vi.spyOn(HTMLMediaElement.prototype, "readyState", "get").mockReturnValue(2);
  const stop = vi.fn();
  const camera = { getTracks: () => [{ stop }] } as unknown as MediaStream;
  const getUserMedia = vi.fn(async () => camera);
  const detect = vi.fn(async () => [{ rawValue: "fixture only" }]);
  class Detector {
    static async getSupportedFormats() { return ["qr_code"]; }
    detect = detect;
  }
  vi.stubGlobal("BarcodeDetector", Detector);
  Object.defineProperty(navigator, "mediaDevices", { configurable: true, value: { getUserMedia } });
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    render(<MiniAppDialog target={{ label: "Fixture" }} launch={async () => ({ url: "https://fixture.example.com/app" })} close={vi.fn()} />);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const post = vi.spyOn(frame.contentWindow!, "postMessage").mockImplementation(() => {});
    const emit = (eventType: string, source = frame.contentWindow) => fireEvent(window, new MessageEvent("message", {
      origin: "null", source, data: JSON.stringify({ eventType, eventData: { text: "Test scanner" } }),
    }));
    emit("web_app_open_scan_qr_popup", window);
    expect(screen.queryByRole("dialog", { name: "Scan QR code" })).toBeNull();
    emit("web_app_open_scan_qr_popup");
    const scanner = screen.getByRole("dialog", { name: "Scan QR code" });
    expect(getUserMedia).not.toHaveBeenCalled();
    expect(frame.getAttribute("allow")).toContain("camera 'none'");
    fireEvent.click(within(scanner).getByRole("button", { name: "Use camera" }));
    await waitFor(() => expect(post).toHaveBeenCalledWith(JSON.stringify({
      eventType: "qr_text_received", eventData: { data: "fixture only" },
    }), "*"));
    expect(getUserMedia).toHaveBeenCalledExactlyOnceWith({ audio: false, video: { facingMode: { ideal: "environment" } } });
    await waitFor(() => expect(detect).toHaveBeenCalledTimes(2));
    expect(post.mock.calls.filter(([data]) => JSON.parse(String(data)).eventType === "qr_text_received")).toHaveLength(1);
    post.mockClear();
    emit("web_app_close_scan_qr_popup");
    expect(stop).toHaveBeenCalledOnce();
    const closedEvent = JSON.stringify({ eventType: "scan_qr_popup_closed", eventData: {} });
    expect(post).not.toHaveBeenCalledWith(closedEvent, "*");
    emit("web_app_open_scan_qr_popup");
    fireEvent.click(screen.getByRole("button", { name: "Close scanner" }));
    expect(post).toHaveBeenCalledWith(closedEvent, "*");
    post.mockClear();
    getUserMedia.mockRejectedValueOnce(new DOMException("Fixture denial", "NotAllowedError"));
    emit("web_app_open_scan_qr_popup");
    fireEvent.click(screen.getByRole("button", { name: "Use camera" }));
    await waitFor(() => expect(post).toHaveBeenCalledWith(closedEvent, "*"));
    expect(screen.queryByRole("dialog", { name: "Scan QR code" })).toBeNull();
  } finally {
    play.mockRestore();
    readyState.mockRestore();
    vi.unstubAllGlobals();
    if (mediaDevices) Object.defineProperty(navigator, "mediaDevices", mediaDevices);
    else Reflect.deleteProperty(navigator, "mediaDevices");
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

test("falls back to bounded local QR frame decoding when the native detector fails", async () => {
  const { MiniAppQrDialog } = await import("../src/ui/mini-app-qr.tsx");
  const showModal = Object.getOwnPropertyDescriptor(HTMLDialogElement.prototype, "showModal");
  const mediaDevices = Object.getOwnPropertyDescriptor(navigator, "mediaDevices");
  const stop = vi.fn();
  const getUserMedia = vi.fn(async () => ({ getTracks: () => [{ stop }] }));
  const detect = vi.fn(async () => { throw new Error("Fixture native detector failure"); });
  vi.stubGlobal("BarcodeDetector", class {
    static async getSupportedFormats() { return ["qr_code"]; }
    detect = detect;
  });
  Object.defineProperty(navigator, "mediaDevices", { configurable: true, value: { getUserMedia } });
  Object.defineProperty(HTMLDialogElement.prototype, "showModal",
    { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockResolvedValue(undefined);
  const readyState = vi.spyOn(HTMLMediaElement.prototype, "readyState", "get").mockReturnValue(2);
  const drawImage = vi.fn();
  const getImageData = vi.fn(() => ({ data: new Uint8ClampedArray(768 * 432 * 4).fill(255) }));
  const getContext = vi.spyOn(HTMLCanvasElement.prototype, "getContext")
    .mockReturnValue({ drawImage, getImageData } as unknown as CanvasRenderingContext2D);
  const scanned = vi.fn();
  try {
    const view = render(<MiniAppQrDialog label="" bot="Fixture" scanned={scanned} close={vi.fn()} />);
    const video = view.container.querySelector("video")!;
    Object.defineProperties(video, { videoWidth: { value: 1920 }, videoHeight: { value: 1080 } });
    expect(getUserMedia).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("button", { name: "Use camera" }));
    await waitFor(() => expect(getImageData).toHaveBeenCalledWith(0, 0, 768, 432));
    expect(detect).toHaveBeenCalledOnce();
    expect(drawImage).toHaveBeenCalledWith(video, 0, 0, 768, 432);
    expect(scanned).not.toHaveBeenCalled();
    view.unmount();
    expect(stop).toHaveBeenCalledOnce();
  } finally {
    play.mockRestore();
    readyState.mockRestore();
    getContext.mockRestore();
    vi.unstubAllGlobals();
    if (mediaDevices) Object.defineProperty(navigator, "mediaDevices", mediaDevices);
    else Reflect.deleteProperty(navigator, "mediaDevices");
    if (showModal) Object.defineProperty(HTMLDialogElement.prototype, "showModal", showModal);
    else Reflect.deleteProperty(HTMLDialogElement.prototype, "showModal");
  }
});

