test.each(["private", "public"] as const)("separates creation and sharing of a %s Mini App requested chat", async (visibility) => {
  const prototype = HTMLDialogElement.prototype;
  const original = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const chat = { id: "-100123", name: "Fixture forum", subtitle: "Group" };
  type CreateRequestedChat = NonNullable<NonNullable<React.ContextType<typeof MiniAppSessionActions>>["createRequestedChat"]>;
  const createRequestedChat = vi.fn<CreateRequestedChat>()
    .mockResolvedValue({ state: "ready", chat });
  if (visibility === "public") createRequestedChat.mockResolvedValueOnce({ state: "usernameUnavailable", chatCreated: true });
  const shareRequestedChats = vi.fn(async () => "sent" as const);
  try {
    render(<MiniAppSessionActions.Provider value={{
      close: vi.fn(async () => true), writeAccess: vi.fn(async () => "unavailable" as const),
      previewChatRequest: async () => ({ confirmation: "review", bot: "@FixtureBot", kind: "group", max: 1, fields: [], creation: "forum",
        ...(visibility === "public" && { requiresUsername: true as const }) }),
      findRequestedChats: async () => [], createRequestedChat, shareRequestedChats,
    }}>
      <MiniAppDialog target={{ label: "Fixture app" }}
        launch={async () => ({ url: "https://fixture.example.com/#request-chat", session: "mini-app" })} close={vi.fn()} />
    </MiniAppSessionActions.Provider>);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const post = vi.spyOn(frame.contentWindow!, "postMessage").mockImplementation(() => {});
    window.dispatchEvent(new MessageEvent("message", { origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_request_chat", eventData: { req_id: "create-forum" } }) }));
    const review = await screen.findByRole("region", { name: "Share Telegram chats with bot" });
    const creation = within(review).getByText(`Create a ${visibility} forum`).closest("details")!;
    creation.open = true;
    fireEvent.change(within(creation).getByRole("textbox", { name: "New forum name" }), { target: { value: "Fixture forum" } });
    const username = within(creation).queryByRole("textbox", { name: "Public username" });
    if (username) fireEvent.change(username, { target: { value: "@FixtureRace" } });
    expect(createRequestedChat).not.toHaveBeenCalled();
    fireEvent.click(within(creation).getByRole("button", { name: "Create forum" }));
    if (username) {
      const retry = await within(creation).findByRole("button", { name: "Set public username" });
      expect(within(creation).getByRole<HTMLInputElement>("textbox", { name: "New forum name" }).readOnly).toBe(true);
      expect(shareRequestedChats).not.toHaveBeenCalled();
      fireEvent.change(username, { target: { value: "FixtureOpen" } });
      fireEvent.click(retry);
    }
    const selected = await within(review).findByRole("list", { name: "Selected Telegram chats" });
    expect(within(selected).getByText("Fixture forum")).toBeTruthy();
    expect(createRequestedChat.mock.calls).toEqual(visibility === "public"
      ? [["mini-app", "review", "Fixture forum", "FixtureRace"], ["mini-app", "review", "Fixture forum", "FixtureOpen"]]
      : [["mini-app", "review", "Fixture forum", undefined]]);
    expect(shareRequestedChats).not.toHaveBeenCalled();
    expect(post.mock.calls.every(([payload]) => !String(payload).includes("requested_chat_sent"))).toBe(true);
    fireEvent.click(within(review).getByRole("button", { name: "Confirm sharing" }));
    await waitFor(() => expect(shareRequestedChats).toHaveBeenCalledExactlyOnceWith("mini-app", "review", [{ id: chat.id, name: chat.name }]));
    expect(JSON.parse(String(post.mock.lastCall?.[0]))).toEqual({ eventType: "requested_chat_sent", eventData: { req_id: "create-forum" } });
  } finally {
    if (original) Object.defineProperty(prototype, "showModal", original);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

