test.each(["sent", "failed", "unknown"] as const)("reviews Mini App reply data and handles delivery result %s", async (result) => {
  const prototype = HTMLDialogElement.prototype;
  const original = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const sendData = vi.fn(async () => result);
  const close = vi.fn();
  try {
    render(<MiniAppDialog target={{ label: "Fixture app" }}
      launch={async () => ({ url: "https://fixture.example.com/#reply", session: "fixture-session" })}
      sendData={sendData} close={close} />);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const frame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const data = JSON.stringify({ eventType: "web_app_data_send", eventData: { data: "<b>Fixture data</b>" } });
    window.dispatchEvent(new MessageEvent("message", { data, origin: "null", source: window }));
    expect(screen.queryByText("<b>Fixture data</b>")).toBeNull();
    window.dispatchEvent(new MessageEvent("message", { data, origin: "null", source: frame.contentWindow }));
    expect((await screen.findByText("<b>Fixture data</b>")).tagName).toBe("PRE");
    expect(sendData).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("button", { name: "Send data to bot" }));
    if (result !== "sent") {
      await screen.findByText(result === "failed" ? "Could not return the data to the bot."
        : "Telegram did not confirm delivery. Check the chat before trying again.");
      expect(close).not.toHaveBeenCalled();
      fireEvent(window, new MessageEvent("message", { data, origin: "null", source: frame.contentWindow }));
      expect(screen.queryByRole("button", { name: "Send data to bot" })).toBeNull();
      fireEvent(window, new MessageEvent("message", { origin: "null", source: frame.contentWindow,
        data: JSON.stringify({ eventType: "web_app_close", eventData: {} }) }));
    }
    await vi.waitFor(() => expect(close).toHaveBeenCalledOnce());
    expect(sendData).toHaveBeenCalledExactlyOnceWith("fixture-session", "<b>Fixture data</b>");
  } finally {
    if (original) Object.defineProperty(prototype, "showModal", original);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

