test("switches between minimized Mini Apps from a compact list without recreating either frame", async () => {
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const closeDialog = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(prototype, "close", { configurable: true, value(this: HTMLDialogElement) { this.open = false; } });
  const launch = vi.fn(async (id: string) => ({ url: `https://fixture.example.com/${id}`, session: id }));
  const closeSession = vi.fn(async () => true);
  function Fixture() {
    const { open, dialog } = useMiniAppWindows();
    return <>
      {["first", "second"].map((id) => <button key={id} type="button" onClick={() => open({
        target: { label: "Fixture app" }, launch: () => launch(id), closeSession,
      })}>Launch {id}</button>)}
      {dialog}
    </>;
  }
  try {
    render(<Fixture />);
    const currentDialog = () => within(screen.getByRole("dialog", { name: "Telegram Mini App" }));
    async function minimize(id: string) {
      fireEvent.click(screen.getByRole("button", { name: `Launch ${id}` }));
      fireEvent.click(currentDialog().getByRole("button", { name: "Open Mini App" }));
      const frame = await currentDialog().findByTitle("Telegram Mini App content");
      fireEvent.click(currentDialog().getByRole("button", { name: "Minimize Mini App" }));
      return frame;
    }
    const first = await minimize("first");
    expect(screen.getByRole("button", { name: "Resume Mini App Fixture app" })).toBeTruthy();
    const second = await minimize("second");
    const trigger = screen.getByRole("button", { name: "Minimized Mini Apps (2)" });
    expect(screen.queryByRole("button", { name: /Resume Mini App/ })).toBeNull();
    fireEvent.click(trigger);
    const list = within(screen.getByRole("list", { name: "Minimized Mini Apps" }));
    const resumeSecond = list.getByRole("button", { name: "Resume Mini App Fixture app · Window 2" });
    resumeSecond.focus();
    fireEvent.keyDown(resumeSecond, { key: "Escape" });
    expect(document.activeElement).toBe(trigger);
    expect(screen.queryByRole("list", { name: "Minimized Mini Apps" })).toBeNull();
    fireEvent.click(trigger);
    fireEvent.click(list.getByRole("button", { name: "Resume Mini App Fixture app · Window 2" }));
    expect(currentDialog().getByTitle("Telegram Mini App content")).toBe(second);
    expect(first.isConnected).toBe(true);
    expect(closeSession).not.toHaveBeenCalled();
    fireEvent.click(currentDialog().getByRole("button", { name: "Close Mini App" }));
    expect(closeSession).toHaveBeenCalledExactlyOnceWith("second");
    fireEvent.click(screen.getByRole("button", { name: "Resume Mini App Fixture app" }));
    expect(currentDialog().getByTitle("Telegram Mini App content")).toBe(first);
    expect(launch.mock.calls).toEqual([["first"], ["second"]]);
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (closeDialog) Object.defineProperty(prototype, "close", closeDialog);
    else Reflect.deleteProperty(prototype, "close");
  }
});

test("restores a minimized Mini App from an equivalent link and opens distinct launch parameters separately", async () => {
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const closeDialog = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(prototype, "close", { configurable: true, value(this: HTMLDialogElement) { this.open = false; } });
  const firstUrl = "https://t.me/FixtureBot/demo?mode=compact&startapp=one";
  const equivalentUrl = "tg://resolve?domain=fixturebot&appname=demo&startapp=one&mode=compact";
  const otherUrl = "https://t.me/fixturebot/demo?startapp=two&mode=compact";
  const launch = vi.fn(async (url: string) => ({
    url: url === firstUrl ? "https://fixture.example.com/first" : "https://fixture.example.com/other",
    session: url === firstUrl ? "first-session" : "other-session",
  }));
  const close = vi.fn(async () => true);
  const message = (id: string, text: string, url: string) => ({
    id, text, time: "", author: "Fixture", links: [{ offset: 0, length: text.length, url }],
  });
  try {
    render(<MiniAppSessionActions.Provider value={{ close, writeAccess: async () => "unavailable" }}>
      <TelegramPage live={{
        chats: [{ id: "42", name: "First fixture chat", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] },
          { id: "43", name: "Second fixture chat", initials: "S", color: "#246dbd", subtitle: "Direct message", messages: [] }],
        folders: [], list: "main", selectList: () => {}, refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
        findChats: async () => [], loadHistory: async (id) => ({ before: null, messages: id === "42"
          ? [message("1", "Open first launch", firstUrl)]
          : [message("2", "Open equivalent launch", equivalentUrl), message("3", "Open distinct launch", otherUrl)] }),
        sendText: async () => ({ state: "failed" }), launchMiniApp: launch,
      }} />
    </MiniAppSessionActions.Provider>);
    fireEvent.click(screen.getByRole("button", { name: /First fixture chat/ }));
    fireEvent.click(await screen.findByRole("link", { name: "Open first launch" }));
    fireEvent.click(await screen.findByRole("button", { name: "Open Mini App" }));
    const initial = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    fireEvent(window, new MessageEvent("message", { origin: "null", source: initial.contentWindow, data: JSON.stringify({
      eventType: "web_app_open_tg_link", eventData: { path_full: "/fixturebot/demo?startapp=one&mode=compact" },
    }) }));
    fireEvent.click(await screen.findByRole("button", { name: "Open in BB" }));
    expect(screen.queryByRole("button", { name: /Resume Mini App/ })).toBeNull();
    expect(screen.getByRole("dialog", { name: "Telegram Mini App" }).querySelector("iframe")).toBe(initial);
    fireEvent.click(screen.getByRole("button", { name: "Minimize Mini App" }));
    fireEvent.click(screen.getByRole("button", { name: /Second fixture chat/ }));
    fireEvent.click(await screen.findByRole("link", { name: "Open equivalent launch" }));
    const resumed = await screen.findByRole("dialog", { name: "Telegram Mini App" });
    expect(resumed.querySelector("iframe")).toBe(initial);
    expect(launch).toHaveBeenCalledExactlyOnceWith(firstUrl);
    expect(close).not.toHaveBeenCalled();
    fireEvent.click(within(resumed).getByRole("button", { name: "Minimize Mini App" }));
    fireEvent.click(await screen.findByRole("link", { name: "Open distinct launch" }));
    fireEvent.click(await screen.findByRole("button", { name: "Open Mini App" }));
    await waitFor(() => expect(screen.getByRole("dialog", { name: "Telegram Mini App" }).querySelector("iframe")?.src)
      .toBe("https://fixture.example.com/other"));
    expect(initial.isConnected).toBe(true);
    expect(launch.mock.calls).toEqual([[firstUrl], [otherUrl]]);
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (closeDialog) Object.defineProperty(prototype, "close", closeDialog);
    else Reflect.deleteProperty(prototype, "close");
  }
});

test("reloads the isolated Mini App frame while preserving its Telegram session", async () => {
  const prototype = HTMLDialogElement.prototype;
  const original = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const launch = vi.fn(async () => ({ url: "https://fixture.example.com/#fixture", session: "fixture-session" }));
  const close = vi.fn();
  const closeSession = vi.fn(async () => true);
  let finish!: (value: { result: string }) => void;
  const invokeCustomMethod = vi.fn(() => new Promise<{ result: string }>((resolve) => { finish = resolve; }));
  const emit = (source: Window, eventType: string, eventData: object = {}) =>
    fireEvent(window, new MessageEvent("message", { origin: "null", source, data: JSON.stringify({ eventType, eventData }) }));
  try {
    render(<MiniAppSessionActions.Provider value={{ close: closeSession, writeAccess: async () => "unavailable", invokeCustomMethod }}>
      <MiniAppDialog target={{ label: "Fixture app" }} launch={launch} close={close} />
    </MiniAppSessionActions.Provider>);
    fireEvent.click(screen.getByRole("button", { name: "Open Mini App" }));
    const oldFrame = await screen.findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    const oldWindow = oldFrame.contentWindow!;
    emit(oldWindow, "web_app_setup_main_button", { is_visible: true, text: "Old page action" });
    emit(oldWindow, "web_app_invoke_custom_method", { req_id: "fixture", method: "ping", params: {} });
    expect(invokeCustomMethod).toHaveBeenCalledExactlyOnceWith("fixture-session", "ping", "{}");
    function reload() {
      screen.getByLabelText("Mini App options").closest("details")!.open = true;
      fireEvent.click(screen.getByRole("button", { name: "Reload Mini App" }));
    }
    reload();
    expect(screen.getByText("Wait for the current Mini App request before reloading.")).toBeTruthy();
    expect(oldFrame.isConnected).toBe(true);
    await act(async () => finish({ result: "{}" }));
    emit(oldWindow, "web_app_setup_closing_behavior", { need_confirmation: true });
    reload();
    fireEvent.click(screen.getByRole("button", { name: "Keep Mini App open" }));
    expect(oldFrame.isConnected).toBe(true);
    reload();
    fireEvent.click(screen.getByRole("button", { name: "Reload anyway" }));
    const newFrame = screen.getByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(newFrame).not.toBe(oldFrame);
    expect(newFrame.src).toBe("https://fixture.example.com/#fixture");
    expect(newFrame.getAttribute("sandbox")).toBe("allow-scripts");
    expect(screen.queryByRole("button", { name: "Old page action" })).toBeNull();
    expect(launch).toHaveBeenCalledOnce();
    expect(closeSession).not.toHaveBeenCalled();
    emit(oldWindow, "web_app_close");
    expect(close).not.toHaveBeenCalled();
    const post = vi.spyOn(newFrame.contentWindow!, "postMessage").mockImplementation(() => {});
    emit(newFrame.contentWindow!, "web_app_ready");
    expect(post.mock.calls.map(([data]) => JSON.parse(String(data)).eventType)).toEqual(
      expect.arrayContaining(["viewport_changed", "theme_changed", "safe_area_changed", "content_safe_area_changed"]));
    emit(newFrame.contentWindow!, "web_app_close");
    expect(closeSession).toHaveBeenCalledExactlyOnceWith("fixture-session");
  } finally {
    if (original) Object.defineProperty(prototype, "showModal", original);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

test("reviews and updates welcome messages from group details", async () => {
  const prototype = HTMLDialogElement.prototype;
  const original = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  const id = "-1000000000010";
  const revision = "a".repeat(64);
  const link = { offset: 8, length: 8, url: "https://example.com/welcome" };
  const load = vi.fn(async () => [{ id: 4, text: "Fixture greeting", kind: "Text", editable: true, revision,
    links: [{ ...link, hidden: true }] }]);
  const change = vi.fn(async (): Promise<"saved" | "changed"> => "saved");
  try {
    render(<TelegramPage live={{
      chats: [{ id, name: "Welcome fixture group", initials: "W", color: "#246dbd", subtitle: "Group", messages: [] }],
      folders: [], list: "main", selectList: () => {}, refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
      findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }),
      sendText: vi.fn(), welcomeMessageActions: { load, change },
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Welcome fixture group/ }));
    fireEvent.click(screen.getByRole("button", { name: "Chat details" }));
    const details = within(screen.getByRole("dialog", { name: "Chat details" }));
    fireEvent.click(details.getByText("Welcome messages", { selector: "summary" }));
    fireEvent.click(details.getByRole("button", { name: "Load welcome messages" }));
    fireEvent.click(await details.findByRole("button", { name: "Edit welcome message 1" }));
    const editor = details.getByRole<HTMLTextAreaElement>("textbox", { name: "Welcome text" });
    const save = details.getByRole<HTMLButtonElement>("button", { name: "Save welcome message" });
    expect(save.disabled).toBe(true);
    editor.setSelectionRange(0, 7);
    fireEvent.keyDown(editor, { key: "b", code: "KeyB", ctrlKey: true });
    expect(save.disabled).toBe(false);
    fireEvent.click(save);
    await details.findByText("Welcome message saved.");
    expect(change).toHaveBeenCalledExactlyOnceWith({ action: "edit", id, messageId: 4, text: "Fixture greeting", revision,
      styles: [{ offset: 0, length: 7, style: "bold" }], links: [link] });
    fireEvent.click(details.getByRole("button", { name: "Delete welcome message 1" }));
    const confirmation = within(details.getByRole("group", { name: "Confirm welcome message deletion" }));
    expect(confirmation.getByText("Fixture greeting")).toBeTruthy();
    expect(change).toHaveBeenCalledTimes(1);
    change.mockResolvedValueOnce("changed");
    fireEvent.click(confirmation.getByRole("button", { name: "Confirm deletion" }));
    await details.findByText(/This welcome message changed/);
    expect(confirmation.getByRole<HTMLButtonElement>("button", { name: "Confirm deletion" }).disabled).toBe(true);
    expect(change).toHaveBeenLastCalledWith({ action: "delete", id, messageId: 4, revision });
  } finally {
    if (original) Object.defineProperty(prototype, "showModal", original);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

