  expect(within(replies).getByRole<HTMLButtonElement>("button", { name: "Save changes" }).disabled).toBe(true);
  expect(loadMessages).toHaveBeenCalledTimes(2);
  fireEvent.click(within(replies).getByRole("button", { name: "Reload shortcut messages" }));
  await within(replies).findByRole("button", { name: "Edit message 1" });
  expect(loadMessages).toHaveBeenCalledTimes(3);
  fireEvent.click(within(replies).getByRole("button", { name: "Rename /greeting" }));
  fireEvent.change(within(replies).getByRole("textbox", { name: "Shortcut name" }), { target: { value: "welcome" } });
  fireEvent.click(within(replies).getByRole("button", { name: "Save name" }));
  await within(replies).findByText("This shortcut changed in Telegram. Refresh quick replies and try again.");
  fireEvent.click(within(settings).getByRole("button", { name: "Refresh quick replies" }));
  fireEvent.click(await within(replies).findByRole("button", { name: "Rename /greeting" }));
  fireEvent.change(within(replies).getByRole("textbox", { name: "Shortcut name" }), { target: { value: "welcome" } });
  fireEvent.click(within(replies).getByRole("button", { name: "Save name" }));
