  fireEvent.click(within(settings).getByRole("button", { name: "Bold" }));
  fireEvent.click(within(settings).getByRole("button", { name: "Save message" }));
  await within(settings).findByRole("button", { name: "New quick reply" });
  expect(addText.mock.calls).toEqual([
    [{ id: 1, name: "welcome", text: "Another fixture" }],
    [{ id: undefined, name: "new_reply", text: "First template fixture", styles: [{ offset: 0, length: 5, style: "bold" }] }],
  ]);
