test.each([false, true])("submits quick reply album items in the edited order (mixed: %s)", async (mixed) => {
  const photos = await import("../src/ui/prepare-photo.ts");
  const prepare = vi.spyOn(photos, "preparePhoto").mockImplementation(async (file) => file.name);
  const addPhoto = vi.fn();
  const addPhotoAlbum = vi.fn(async () => ({ state: "submitted" as const }));
  const addMixedAlbum = vi.fn(async () => ({ state: "submitted" as const }));
  try {
    render(<QuickReplySettings load={async () => []} loadMessages={vi.fn()} rename={vi.fn()} addText={vi.fn()}
      addPhoto={addPhoto} addPhotoAlbum={addPhotoAlbum} addMixedAlbum={mixed ? addMixedAlbum : undefined}
      remove={vi.fn()} reorder={vi.fn()} editText={vi.fn()} removeMessage={vi.fn()} />);
    fireEvent.click(screen.getByRole("button", { name: "Load quick replies" }));
    fireEvent.click(await screen.findByRole("button", { name: "New quick reply" }));
    fireEvent.change(screen.getByRole("textbox", { name: "New shortcut name" }), { target: { value: "welcome" } });
    const files = ["second.png", "first.png"].map((name) => new File(["fixture"], name, { type: "image/png" }));
    const video = new File(["video"], "middle.mov", { type: "video/quicktime" });
    if (mixed) {
      files.splice(1, 0, video);
      files.push(new File(["fixture"], "discard.png", { type: "image/png" }));
    }
    fireEvent.change(screen.getByLabelText(mixed ? "Shortcut photo or album" : "Shortcut photo"), { target: { files } });
    const selection = screen.getByRole("list", { name: "Selected shortcut files" });
    if (mixed) {
      fireEvent.click(within(selection).getByRole("button", { name: "Remove discard.png" }));
      expect(within(selection).queryByText("discard.png")).toBeNull();
      fireEvent.click(within(selection).getByRole("button", { name: "Move middle.mov down" }));
    } else {
      fireEvent.click(within(selection).getByRole("button", { name: "Move first.png up" }));
    }
    fireEvent.change(screen.getByRole("textbox", { name: "Album caption" }), { target: { value: "Fixture album" } });
    fireEvent.click(screen.getByRole("checkbox", { name: "Hide album behind spoilers" }));
    fireEvent.click(screen.getByRole("checkbox", { name: "Show caption above album" }));
    fireEvent.click(screen.getByRole("button", { name: "Save message" }));
    await screen.findByText("Message submitted to the shortcut.");
    expect(addPhoto).not.toHaveBeenCalled();
    const input = { id: undefined, name: "welcome", caption: "Fixture album", media: { spoiler: true, captionAbove: true } };
    if (mixed) {
      expect(prepare.mock.calls.map(([file]) => file.name)).toEqual(["second.png", "first.png"]);
      expect(addMixedAlbum).toHaveBeenCalledExactlyOnceWith(input, [
        { kind: "photo", base64: "second.png" }, { kind: "photo", base64: "first.png" }, { kind: "video", file: video },
      ], expect.any(Function), expect.any(AbortSignal));
      expect(addPhotoAlbum).not.toHaveBeenCalled();
    } else {
      expect(addPhotoAlbum).toHaveBeenCalledExactlyOnceWith({ ...input, photos: ["first.png", "second.png"] });
    }
  } finally { prepare.mockRestore(); }
});

