test.each([false, true])("adds a poll to a new quick reply and opens its read-only preview (file: %s)", async (withFile) => {
  const addPoll = vi.fn(async () => "submitted" as const);
  const load = vi.fn(async () => [{ id: 4, name: "sample", messageCount: 1 }]).mockResolvedValueOnce([]);
  const addText = vi.fn();
  const upload = vi.fn(async () => ({ state: "submitted" as const }));
  render(<PollFileUpload.Provider value={upload}><QuickReplySettings load={load} loadMessages={async () => [{ id: 10, text: "", mediaLabel: "Poll",
    poll: { question: "Fixture question", options: [{ index: 0, text: "First", chosen: false }, { index: 1, text: "Second", chosen: false }],
      closed: false, canVote: true, multiple: false, quiz: false },
  }]} rename={vi.fn()} addText={addText} addPoll={addPoll}
    remove={vi.fn()} reorder={vi.fn()} editText={vi.fn()} removeMessage={vi.fn()} /></PollFileUpload.Provider>);
  fireEvent.click(screen.getByRole("button", { name: "Load quick replies" }));
  fireEvent.click(await screen.findByRole("button", { name: "New quick reply" }));
  fireEvent.change(screen.getByRole("textbox", { name: "New shortcut name" }), { target: { value: "sample" } });
  fireEvent.click(screen.getByRole("button", { name: "Add poll" }));
  const form = within(screen.getByRole("form", { name: "Add poll to quick reply" }));
  fireEvent.change(form.getByRole("textbox", { name: "Question" }), { target: { value: "Fixture question" } });
  fireEvent.change(form.getByRole("textbox", { name: "Option 1" }), { target: { value: "First" } });
  expect(form.getByRole<HTMLButtonElement>("button", { name: "Save poll" }).disabled).toBe(true);
  fireEvent.change(form.getByRole("textbox", { name: "Option 2" }), { target: { value: "Second" } });
  const file = new File(["Fixture"], "Fixture.txt", { type: "text/plain" });
  if (withFile) {
    fireEvent.click(form.getByText("Files for this poll"));
    fireEvent.change(within(form.getByRole("group", { name: "Question file" })).getByLabelText("Choose file"),
      { target: { files: [file] } });
  }
  fireEvent.click(form.getByRole("button", { name: "Save poll" }));
  await screen.findByText("Poll submitted to the shortcut.");
  const draft = { question: "Fixture question", options: ["First", "Second"], multiple: false };
  if (withFile) {
    expect(addPoll).not.toHaveBeenCalled();
    expect(upload).toHaveBeenCalledExactlyOnceWith({ id: undefined, name: "sample" }, draft,
      [{ slot: "question", kind: "document", file }], expect.any(AbortSignal), expect.any(Function));
  } else {
    expect(addPoll).toHaveBeenCalledExactlyOnceWith({ id: undefined, name: "sample", draft });
    expect(upload).not.toHaveBeenCalled();
  }
  expect(addText).not.toHaveBeenCalled();
  fireEvent.click(await screen.findByRole("button", { name: "Show messages /sample" }));
  expect(await screen.findByText("Fixture question")).toBeTruthy();
  expect(screen.getByText("Second")).toBeTruthy();
  expect(screen.queryByRole("button", { name: "Second" })).toBeNull();
});

