  fireEvent.click(await screen.findByRole("button", { name: "Add message /fixture" }));
  const file = new File(["fixture"], kind === "video" || kind === "videoNote" ? "fixture.mp4" : kind === "audio" ? "fixture.mp3" : kind === "animation" ? "fixture.gif" : kind === "voice" ? "fixture.ogg" : "fixture.bin");
  fireEvent.change(screen.getByLabelText("Shortcut document"), { target: { files: [file] } });
  const label = kind === "videoNote" ? "video note" : kind === "animation" ? "GIF" : kind === "voice" ? "voice message" : kind;
  if (kind !== "document") fireEvent.click(screen.getByRole("checkbox", { name: `Upload as ${label}` }));
  expect(screen.queryByRole("textbox", { name: /caption$/i }) !== null).toBe(kind !== "videoNote");
  const visualMedia = kind === "video" || kind === "animation";
