test("loads a static quick reply sticker only when visible and offers a fresh ticket after failure", async () => {
  let intersect: (visible: boolean) => void = () => {};
  class Observer {
    constructor(callback: IntersectionObserverCallback) {
      intersect = (visible) => callback([{ isIntersecting: visible } as IntersectionObserverEntry], this as unknown as IntersectionObserver);
    }
    observe() {}
    disconnect() {}
  }
  vi.stubGlobal("IntersectionObserver", Observer);
  const url = "/api/v1/plugins/makosh-telegram/http/video-stream";
  const loadPlayback = vi.fn().mockRejectedValueOnce(new Error("Fixture error")).mockResolvedValueOnce(url);
  try {
    render(<QuickReplySettings load={async () => [{ id: 4, name: "fixture", messageCount: 1 }]}
      loadMessages={async () => [{ id: 8, text: "", mediaLabel: "Sticker", playback: {
        fileId: 12, mime: "image/webp", spoiler: false, loop: true, voiceNote: false, videoNote: false,
      } }]} loadPlayback={loadPlayback} rename={vi.fn()} addText={vi.fn()} remove={vi.fn()} reorder={vi.fn()}
      editText={vi.fn()} removeMessage={vi.fn()} />);
    fireEvent.click(screen.getByRole("button", { name: "Load quick replies" }));
    fireEvent.click(await screen.findByRole("button", { name: "Show messages /fixture" }));
    await screen.findByText("Loading sticker…");
    await act(async () => intersect(false));
    expect(loadPlayback).not.toHaveBeenCalled();
    await act(async () => intersect(true));
    fireEvent.click(await screen.findByRole("button", { name: "Retry sticker" }));
    expect((await screen.findByRole("img", { name: "Telegram sticker" })).getAttribute("src")).toBe(url);
    expect(loadPlayback.mock.calls).toEqual([[4, 8, 12], [4, 8, 12]]);
  } finally { vi.unstubAllGlobals(); }
});

