test("filters private-chat quick replies by a slash prefix and preserves a newer draft", async () => {
  const load = vi.fn(async (_chatId: string) => [
    { id: 1, name: "hours", messageCount: 2 },
    { id: 2, name: "help", messageCount: 1 },
    { id: 3, name: "Часы", messageCount: 1 },
  ]);
  let finish!: (value: "submitted") => void;
  const send = vi.fn(async () => "submitted" as const)
    .mockReturnValueOnce(new Promise((resolve) => { finish = resolve; }));
  const sendText = vi.fn(async () => ({ state: "failed" as const }));
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Shortcut peer", initials: "S", color: "#246dbd", subtitle: "Direct message", messages: [] },
      { id: "-50", name: "Shortcut group", initials: "G", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }),
    sendText, quickReplies: { load, send },
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Shortcut peer/ }));
  const draft = screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" });
  fireEvent.change(draft, { target: { value: "/" } });
  await screen.findByRole("button", { name: "Send /hours (2 messages)" });
  fireEvent.change(draft, { target: { value: "/ча" } });
  const russian = screen.getByRole("button", { name: "Send /Часы (1 message)" });
  expect(screen.queryByRole("button", { name: "Send /hours (2 messages)" })).toBeNull();
  expect(load).toHaveBeenCalledExactlyOnceWith("42");
  fireEvent.keyDown(draft, { key: "ArrowDown" });
  expect(document.activeElement).toBe(russian);
  fireEvent.keyDown(russian, { key: "Escape" });
  expect(document.activeElement).toBe(draft);
  expect(draft.value).toBe("/ча");
  expect(screen.queryByRole("button", { name: "Send /Часы (1 message)" })).toBeNull();
  fireEvent.change(draft, { target: { value: "/hou" } });
  const hours = await screen.findByRole("button", { name: "Send /hours (2 messages)" });
  fireEvent.keyDown(draft, { key: "Enter" });
  expect(document.activeElement).toBe(hours);
  expect(send).not.toHaveBeenCalled();
  expect(sendText).not.toHaveBeenCalled();
  fireEvent.click(hours);
  fireEvent.change(draft, { target: { value: "New draft" } });
  await act(async () => finish("submitted"));
  await screen.findByText("Quick reply submitted.");
  expect(draft.value).toBe("New draft");
  fireEvent.change(draft, { target: { value: "/help" } });
  fireEvent.click(await screen.findByRole("button", { name: "Send /help (1 message)" }));
  await waitFor(() => expect(draft.value).toBe(""));
  expect(send).toHaveBeenCalledTimes(2);
  fireEvent.click(screen.getByRole("button", { name: /Shortcut group/ }));
  fireEvent.change(screen.getByRole("textbox", { name: "Write a message" }), { target: { value: "/" } });
  expect(load.mock.calls.every(([chatId]) => chatId === "42")).toBe(true);
});

test("sets a media retention period independently of the byte limit", async () => {
  const read = async () => ({ bytes: 200, limitMiB: 512, retentionDays: 0 });
  const setLimit = vi.fn(async (limitMiB: number, retentionDays?: number) => ({ bytes: 150, limitMiB, retentionDays }));
  const { container } = render(<CacheSettings read={read} setLimit={setLimit} clear={vi.fn()} />);
  const dialog = container.querySelector("dialog")!;
  dialog.showModal = () => { dialog.open = true; };
  fireEvent.click(screen.getByRole("button", { name: "Telegram settings" }));
  const input = await screen.findByRole("spinbutton", { name: "Keep unused media (days)" }) as HTMLInputElement;
  const save = screen.getByRole("button", { name: "Save limit" }) as HTMLButtonElement;
  fireEvent.change(input, { target: { value: "366" } });
  expect(save.disabled).toBe(true);
  fireEvent.change(input, { target: { value: "7" } });
  fireEvent.click(save);
  await screen.findByText("Cache limit saved.");
  expect(setLimit).toHaveBeenCalledExactlyOnceWith(512, 7);
  expect(input.value).toBe("7");
  expect(save.disabled).toBe(true);
});

