test("groups chat detail actions in the reference order and searches the collapsed sections", () => {
  const target = render(<aside />).container.firstElementChild as HTMLElement;
  const browse = vi.fn();
  const close = vi.fn(() => true);
  render(<ChatDetails chatId="-42" name="Fixture group" subtitle="Group" browse={browse} sidePanel={{ target, open: () => true, close }}
    load={async () => false} change={async (_, value) => value} members={<button>Member list fixture</button>}
    notifications={<button>Mute chat fixture</button>}><button>Export chat history fixture</button></ChatDetails>);
  const panel = within(target);
  expect(panel.getByText("About this chat")).toBeTruthy();
  const sections = Array.from(target.querySelectorAll<HTMLElement>("[data-detail-section]"));
  expect(sections.map((section) => section.dataset.detailSection)).toEqual(["media", "notifications", "members", "ai", "settings"]);
  expect(sections[0]).toBe(panel.getByRole("button", { name: "Shared media" }));
  expect(sections.some((section) => section.hasAttribute("open"))).toBe(false);
  fireEvent.change(panel.getByRole("searchbox", { name: "Search settings and actions" }), { target: { value: "files" } });
  expect(sections.filter((section) => !section.hidden).map((section) => section.dataset.detailSection)).toEqual(["media"]);
  fireEvent.change(panel.getByRole("searchbox", { name: "Search settings and actions" }), { target: { value: "export history" } });
  expect(sections.filter((section) => !section.hidden).map((section) => section.dataset.detailSection)).toEqual(["settings"]);
  expect(sections[4]?.hasAttribute("open")).toBe(true);
  expect(browse).not.toHaveBeenCalled();
  fireEvent.click(panel.getByRole("button", { name: "Close" }));
  expect(close).toHaveBeenCalledOnce();
});

