test("live refresh preserves earlier pages and a draft while deduplicating overlapping messages", async () => {
  const message = (id: string) => ({ id, text: `Fixture ${id}`, author: "Fixture", time: "" });
  const loadHistory = vi.fn()
    .mockResolvedValueOnce({ messages: [message("20")], before: "20" })
    .mockResolvedValueOnce({ messages: [message("10")], before: "10" })
    .mockResolvedValueOnce({ messages: [message("20"), message("30")], before: "20" });
  const live = {
    chats: [{ id: "42", name: "Fixture", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", loadHistory, findChats: async () => [],
    sendText: async () => ({ state: "failed" as const }),
  };
  const page = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture/ }));
  const history = within(screen.getByRole("list", { name: "Messages" }));
  await history.findByText("Fixture 20");
  fireEvent.click(history.getByRole("button", { name: "Load earlier messages" }));
  await history.findByText("Fixture 10");
  fireEvent.change(screen.getByRole("textbox"), { target: { value: "Draft fixture" } });
  page.rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  await history.findByText("Fixture 30");
  expect(history.getAllByText(/^Fixture (10|20|30)$/).map((node) => node.textContent))
    .toEqual(["Fixture 10", "Fixture 20", "Fixture 30"]);
  expect((screen.getByRole("textbox") as HTMLInputElement).value).toBe("Draft fixture");
});

test("loads older history only after scrolling toward the start", async () => {
  const loadHistory = vi.fn()
    .mockResolvedValueOnce({ messages: [{ id: "20", text: "Recent fixture", author: "Fixture", time: "" }], before: "20" })
    .mockResolvedValueOnce({ messages: [
      { id: "10", text: "Earlier fixture", author: "Fixture", time: "" },
      { id: "20", text: "Recent fixture", author: "Fixture", time: "" },
      { id: "30", text: "New fixture", author: "Fixture", time: "" },
    ], before: "10" })
    .mockResolvedValueOnce({ messages: [{ id: "10", text: "Earlier fixture", author: "Fixture", time: "" }], before: null });
  const live = {
    chats: [{ id: "42", name: "Fixture", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", loadHistory, findChats: async () => [],
    sendText: async () => ({ state: "failed" as const }),
  };
  const view = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture/ }));
  const list = screen.getByRole("list", { name: "Messages" });
  const history = within(list);
  await history.findByText("Recent fixture");
  fireEvent.scroll(list);
  expect(loadHistory).toHaveBeenCalledOnce();
  view.rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  await history.findByText("New fixture");
  expect(history.queryByText("Earlier fixture")).toBeNull();
  expect(loadHistory.mock.calls).toEqual([["42"], ["42"]]);
  list.scrollTop = 300;
  fireEvent.scroll(list);
  expect(loadHistory).toHaveBeenCalledTimes(2);
  list.scrollTop = 40;
  fireEvent.scroll(list);
  await history.findByText("Earlier fixture");
  expect(loadHistory).toHaveBeenLastCalledWith("42", "20");
  expect(history.getAllByText(/^(Earlier|Recent) fixture$/).map((node) => node.textContent))
    .toEqual(["Earlier fixture", "Recent fixture"]);
});

test("opening a second chat does not replay an update that preceded its first page", async () => {
  const fixture = (id: string, text: string) => ({ id, text, author: "Fixture", time: "" });
  const page = (id: string, text: string) => ({ messages: [fixture(id, text)], before: id });
  let finishFirstRefresh!: (result: ReturnType<typeof page>) => void;
  const firstRefresh = new Promise<ReturnType<typeof page>>((resolve) => { finishFirstRefresh = resolve; });
  const loadHistory = vi.fn().mockResolvedValueOnce(page("20", "First page"))
    .mockReturnValueOnce(firstRefresh).mockResolvedValueOnce(page("50", "Second page"))
    .mockResolvedValueOnce(page("50", "Second updated"));
  const chat = (id: string, name: string) => ({ id, name, initials: "F", color: "#246dbd", subtitle: "Group" as const, messages: [] });
  const live = {
    chats: [chat("42", "First fixture"), chat("43", "Second fixture")],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", loadHistory, findChats: async () => [],
    sendText: async () => ({ state: "failed" as const }),
  };
  const { rerender } = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /First fixture/ }));
  await screen.findByText("First page");
  rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  await waitFor(() => expect(loadHistory).toHaveBeenCalledTimes(2));
  fireEvent.click(screen.getByRole("button", { name: /Second fixture/ }));
  await screen.findByText("Second page");
  await act(async () => finishFirstRefresh(page("21", "Stale first refresh")));
  expect(screen.queryByText("Stale first refresh")).toBeNull();
  expect(loadHistory.mock.calls).toEqual([["42"], ["42"], ["43"]]);
  rerender(<TelegramPage live={{ ...live, liveRevision: 2 }} />);
  await screen.findByText("Second updated");
  expect(loadHistory.mock.calls).toEqual([["42"], ["42"], ["43"], ["43"]]);
});

test("keeps the earlier-history control and its focus while awaiting an older page", async () => {
  const recent = { id: "20", text: "Recent fixture", author: "Fixture", time: "" };
  let finish!: (page: { messages: (typeof recent)[]; before: string | null }) => void;
  const older = new Promise<{ messages: (typeof recent)[]; before: string | null }>((resolve) => { finish = resolve; });
  const loadHistory = vi.fn().mockResolvedValueOnce({ messages: [recent], before: "20" }).mockReturnValueOnce(older);
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory, findChats: async () => [], sendText: async () => ({ state: "failed" }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture/ }));
  const list = screen.getByRole("list", { name: "Messages" });
  const control = await within(list).findByRole("button", { name: "Load earlier messages" });
  control.focus();
  fireEvent.click(control);
  expect(within(list).getByRole("button", { name: "Load earlier messages" })).toBe(control);
  expect(document.activeElement).toBe(control);
  expect(control.getAttribute("aria-disabled")).toBe("true");
  fireEvent.click(control);
  fireEvent.wheel(list, { deltaY: -100 });
  expect(loadHistory.mock.calls).toEqual([["42"], ["42", "20"]]);
  await act(async () => finish({ messages: [{ ...recent, id: "10", text: "Earlier fixture" }], before: "10" }));
  expect(within(list).getByText("Earlier fixture")).toBeTruthy();
  expect(document.activeElement).toBe(control);
  expect(control.getAttribute("aria-disabled")).toBe("false");
});

