test("sends a manual document with a custom emoji caption when the group permits documents only", async () => {
  const dispatched = { state: "sent" as const, message: {
    id: "12", author: "You", time: "", outgoing: true, text: "Caption fixture",
    document: { name: "Fixture.txt", downloadable: true, caption: "Caption fixture" },
  } };
  let finish!: (result: typeof dispatched) => void;
  type Progress = Parameters<import("../src/core/contract.ts").DocumentSender>[3];
  let updateProgress!: Progress;
  const sendDocument = vi.fn((_id: string, _file: File, _caption: string, progress: Progress) => {
    updateProgress = progress;
    progress(3);
    return new Promise<typeof dispatched>((resolve) => { finish = resolve; });
  });
  const sendText = vi.fn();
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "File fixture", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "",
    postingPermissions: async () => ({ text: false, photo: false, document: true }),
    loadGroupEmoji: async () => ({ id: "81", title: "Fixture emoji pack", choices: [{ id: "18", emoji: "✨" }], next: null }),
    loadHistory: async () => ({ before: null, messages: [] }), findChats: async () => [], sendText, sendDocument,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /^File fixture/ }));
  await findComposerAction("Attach document");
  const file = new File(["Fixture"], "Fixture.txt", { type: "text/plain" });
  const history = screen.getByRole("list", { name: "Messages" });
  fireEvent.drop(history, { dataTransfer: { files: [file, file] } });
  expect(within(screen.getByRole("group", { name: "ZIP archive" })).getByText("2 selected items")).toBeTruthy();
  expect(sendDocument).not.toHaveBeenCalled();
  fireEvent.click(getComposerAction("Cancel ZIP attachment"));
  expect(fireEvent.drop(history, { dataTransfer: { files: [file] } })).toBe(false);
  expect(sendDocument).not.toHaveBeenCalled();
  const field = await screen.findByRole<HTMLTextAreaElement>("textbox", { name: "Write an attachment caption" });
  fireEvent.change(field, { target: { value: "  Caption fixture " } });
  field.setSelectionRange(field.value.length, field.value.length);
  fireEvent.click(screen.getByRole("button", { name: "Group emoji" }));
  fireEvent.click(await screen.findByRole("button", { name: "Insert ✨" }));
  fireEvent.click(screen.getByRole("button", { name: "Send message" }));
  expect(sendDocument).toHaveBeenCalledExactlyOnceWith("-42", file, "Caption fixture ✨", expect.any(Function), expect.any(AbortSignal), undefined, undefined, undefined,
    { captionFormat: { customEmoji: [{ id: "18", offset: 16, length: 1 }] } });
  expect(sendText).not.toHaveBeenCalled();
  expect(screen.getByRole("progressbar", { name: "Document upload to BB" }).getAttribute("value")).toBe("3");
  act(() => updateProgress(file.size, false, { uploaded: 2, total: 5 }));
  expect(screen.getByRole("progressbar", { name: "Document upload to Telegram" }).getAttribute("value")).toBe("2");
  expect(screen.getByText("40% uploaded to Telegram")).toBeTruthy();
  await act(async () => finish(dispatched));
  expect(screen.queryByRole("progressbar", { name: "Document upload to BB" })).toBeNull();
  await within(screen.getByRole("list", { name: "Messages" })).findByText("Caption fixture");
});

test("manual message deletion requires an explicit choice of scope", async () => {
  const deletionOptions = vi.fn(async () => ["everyone" as const]);
  const deleteMessage = vi.fn(async () => "deleted" as const);
  let onDeletion: ((event: MessagesDeleted) => void) | undefined;
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [{ id: "25", text: "Synthetic message", author: "Fixture", time: "10:45" }], before: null }),
    subscribeToDeletions: (listener) => { onDeletion = listener; return () => { onDeletion = undefined; }; },
    deletionOptions, deleteMessage,
  }} />);

  fireEvent.click(screen.getByRole("button", { name: /Fixture/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Delete message" }));
  const confirm = await screen.findByRole("button", { name: "Delete for everyone" });
  expect(deletionOptions).toHaveBeenCalledWith("42", "25");
  expect(screen.queryByRole("button", { name: "Delete for me" })).toBeNull();
  expect(deleteMessage).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Cancel" }));
  expect(confirm.isConnected).toBe(false);
  expect(deleteMessage).not.toHaveBeenCalled();

  fireEvent.click(screen.getByRole("button", { name: "Delete message" }));
  fireEvent.click(await screen.findByRole("button", { name: "Delete for everyone" }));
  await screen.findByText("Message deleted.");
  expect(deleteMessage).toHaveBeenCalledExactlyOnceWith("42", "25", "everyone");
  act(() => onDeletion?.({ id: "42", messageIds: ["25"] }));
  expect(screen.queryByText("Synthetic message")).toBeNull();
});

function openFixtureChatDetails() {
  const dialog = document.querySelector<HTMLDialogElement>('dialog[aria-label="Chat details"]')!;
  dialog.showModal = () => { dialog.open = true; };
  dialog.close = () => {
    dialog.open = false;
    dialog.dispatchEvent(new Event("close"));
  };
  fireEvent.click(screen.getByRole("button", { name: "Chat details" }));
  return within(screen.getByRole("dialog", { name: "Chat details" }));
}

async function startFixtureChatSelection() {
  fireEvent.click(await openFixtureChatDetails().findByRole("button", { name: "Select messages" }));
}

test("reviews an exact message selection before submitting one shared deletion scope", async () => {
  const options = vi.fn(async () => ["self" as const]);
  const remove = vi.fn(async () => "deleted" as const);
  const send = vi.fn(async () => "sent" as const);
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture selection", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], sendText: vi.fn(), batchDeletion: { options, remove },
    batchForward: { options: async () => true, send }, forwardOptions: async () => true, forwardMessage: async () => "sent",
    loadHistory: async () => ({ before: null, messages: ["8", "9", "10"].map((id) => ({ id, text: `Fixture ${id}`, time: "", author: "Fixture" })) }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture selection/ }));
  const draft = screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" });
  fireEvent.change(draft, { target: { value: "Unsent fixture" } });
  expect(screen.queryByRole("button", { name: "Select messages" })).toBeNull();
  await startFixtureChatSelection();
  expect(screen.queryByRole("textbox", { name: "Write a message" })).toBeNull();
  const history = screen.getByRole("list", { name: "Messages" });
  expect(history.compareDocumentPosition(screen.getByRole("group", { name: "Message selection" })) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  fireEvent.keyDown(screen.getByRole("button", { name: "Cancel selection" }), { key: "Escape" });
  expect(screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" }).value).toBe("Unsent fixture");
  await startFixtureChatSelection();
  const boxes = screen.getAllByRole("checkbox", { name: "Select message" });
  fireEvent.click(boxes[0]!);
  fireEvent.click(boxes[2]!);
  fireEvent.click(screen.getByRole("button", { name: "Forward selected messages" }));
  const forwardDialog = await screen.findByRole("dialog", { name: "Forward 2 messages" });
  expect(screen.getByRole("group", { name: "Message selection" }).contains(forwardDialog)).toBe(false);
  const target = await within(forwardDialog).findByRole("combobox", { name: "Forward to" });
  expect(send).not.toHaveBeenCalled();
  expect((boxes[0] as HTMLInputElement).disabled).toBe(true);
  fireEvent.change(target, { target: { value: "42" } });
  fireEvent.click(screen.getByRole("button", { name: "Forward 2 messages" }));
  await screen.findByText("Selected messages forwarded.");
  expect(send).toHaveBeenCalledExactlyOnceWith("42", ["8", "10"], {
    id: "42", name: "Fixture selection", kind: "Direct message",
  }, undefined, undefined);
  fireEvent.click(within(forwardDialog).getByRole("button", { name: "Close" }));
  fireEvent.click(screen.getByRole("button", { name: "Review selected deletion" }));
  expect(remove).not.toHaveBeenCalled();
  const confirm = await screen.findByRole("button", { name: "Delete selected for me" });
  expect(screen.queryByRole("button", { name: "Delete selected for everyone" })).toBeNull();
  expect(options).toHaveBeenCalledExactlyOnceWith("42", ["8", "10"]);
  fireEvent.click(confirm);
  await waitFor(() => expect(screen.queryByRole("group", { name: "Message selection" })).toBeNull());
  expect(openFixtureChatDetails().getByRole("button", { name: "Select messages" })).toBeTruthy();
  expect(remove).toHaveBeenCalledExactlyOnceWith("42", ["8", "10"], "self");
});

test("focuses the first unread message and keeps keyboard paging available in a chat", async () => {
  const row = (id: string, text: string, outgoing = false) => ({ id, text, author: "Fixture", time: "", outgoing });
  const markChat = vi.fn();
  const loadHistory = vi.fn(async (_id: string, before?: string) => before === "8"
    ? { before: null, messages: [row("7", "Earlier fixture")] }
    : { before: "8", readInbox: 8, messages: [
      row("8", "Read fixture"), row("9", "Outgoing fixture", true), row("10", "Unread fixture"),
    ] });
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Fixture unread chat", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [], unread: 1 }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], sendText: vi.fn(), markChat,
    loadHistory,
  }} />);
  let focusAfterOpening: FrameRequestCallback | undefined;
  const frame = vi.spyOn(window, "requestAnimationFrame").mockImplementationOnce((callback) => {
    focusAfterOpening = callback;
    return -1;
  });
  try {
    fireEvent.click(screen.getByRole("button", { name: /Fixture unread chat/ }));
  } finally {
    frame.mockRestore();
  }
  const divider = await screen.findByText("Unread messages");
  const history = screen.getByRole("list", { name: "Messages" });
  const unread = screen.getByText("Unread fixture").closest("li")!;
  expect(divider.nextElementSibling).toBe(unread);
  expect(unread.getAttribute("aria-describedby")).toBe(divider.id);
  vi.spyOn(divider, "getBoundingClientRect").mockReturnValue(new DOMRect(0, 270, 200, 20));
  vi.spyOn(history, "getBoundingClientRect").mockReturnValue(new DOMRect(0, 40, 200, 160));
  history.scrollTop = 50;
  fireEvent.click(screen.getByRole("button", { name: "Jump to unread" }));
  expect(history.scrollTop).toBe(280);
  expect(document.activeElement).toBe(unread);
  expect(focusAfterOpening).toBeDefined();
  act(() => focusAfterOpening?.(0));
  expect(document.activeElement).toBe(unread);
  history.scrollTop = 0;
  expect(fireEvent.keyDown(unread, { key: "PageUp" })).toBe(false);
  await screen.findByText("Earlier fixture");
  expect(loadHistory).toHaveBeenLastCalledWith("42", "8");
  expect(document.activeElement).toBe(unread);
  expect(markChat).not.toHaveBeenCalled();
});

