test("shows a forum photo caption and loads only its visible photo and sender avatar", async () => {
  const observed = new Map<Element, IntersectionObserverCallback>();
  class Observer {
    constructor(private callback: IntersectionObserverCallback) {}
    observe(element: Element) { observed.set(element, this.callback); }
    disconnect() {}
  }
  vi.stubGlobal("IntersectionObserver", Observer);
  try {
    const loadPhoto = vi.fn(async () => ({ mime: "image/png" as const, base64: "AAAA" }));
    const loadAvatar = vi.fn(async () => ({ mime: "image/webp" as const, base64: "AAAA" }));
    const { container } = render(<TelegramPage live={{
      chats: [{ id: "-42", name: "Fixture forum", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
      folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      findChats: async () => [], sendText: vi.fn(), loadHistory: async () => ({ messages: [], before: null }),
      loadForumTopics: async () => [{ id: 17, name: "Fixture topic", closed: false }],
      loadTopicHistory: async () => ({ before: null, messages: [{
        id: "101", author: "Fixture sender", time: "", text: "Photo", hasPhoto: true,
        photoCaption: "Fixture photo caption", authorAvatar: { id: "77", user: true, fileId: 8, preview: "/9j/AA==" },
      }] }),
      loadPhoto, loadAvatar,
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Fixture forum/ }));
    fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
    fireEvent.click(await screen.findByRole("button", { name: "Fixture topic" }));
    const history = within(await screen.findByRole("list", { name: "Topic messages" }));
    await history.findByText("Fixture photo caption");
    expect(history.getByText("Fixture sender")).toBeTruthy();
    expect(history.queryByText("Photo", { exact: true })).toBeNull();
    expect(loadPhoto).not.toHaveBeenCalled();
    expect(loadAvatar).not.toHaveBeenCalled();
    const row = container.querySelector('[data-message-id="101"]')!;
    const avatar = row.querySelector(".mtg-message-author .mtg-avatar")!;
    const photo = row.querySelector(".mtg-photo-placeholder")!;
    expect(avatar.querySelector("img")?.getAttribute("src")).toBe("data:image/jpeg;base64,/9j/AA==");
    await act(async () => {
      for (const target of [avatar, photo]) {
        expect(observed.has(target)).toBe(true);
        observed.get(target)!([{ target, isIntersecting: true, intersectionRatio: 0.5 } as IntersectionObserverEntry], {} as IntersectionObserver);
      }
    });
    expect(loadPhoto).toHaveBeenCalledExactlyOnceWith("-42", "101");
    expect(loadAvatar).toHaveBeenCalledExactlyOnceWith("77", 8, true);
    expect(history.getByRole("img", { name: "Telegram photo" })).toBeTruthy();
    expect(avatar.querySelector("img")?.getAttribute("src")).toBe("data:image/webp;base64,AAAA");
  } finally { vi.unstubAllGlobals(); }
});

test("uses the selected double-click action without intercepting text selection or controls", async () => {
  const message = { id: "52", text: "Selectable words", author: "Fixture", time: "10:00" };
  const quick = { kind: "emoji" as const, emoji: "👍" };
  const setReaction = vi.fn(async () => true);
  const sendText = vi.fn(async () => ({ state: "failed" as const }));
  const data = {
    chats: [{ id: "42", name: "Double click fixture", initials: "DC", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    loadHistory: async () => ({ messages: [message], before: null }), findChats: async () => [], sendText,
    reactionActions: { quickReaction: quick, setReaction, listReactions: async () => [quick] },
  };
  const { rerender } = render(<TelegramPage live={data} />);
  fireEvent.click(screen.getByRole("button", { name: /Double click fixture/ }));
  const text = await screen.findByText(message.text);
  const row = text.closest("li")!;
  const reply = () => screen.queryByRole("button", { name: "Cancel reply" });
  fireEvent.doubleClick(text);
  fireEvent.doubleClick(within(row).getByRole("button", { name: "Add reaction" }));
  fireEvent.doubleClick(row, { metaKey: true });
  fireEvent.doubleClick(row, { button: 2 });
  expect(reply()).toBeNull();
  const selection = document.getSelection()!;
  selection.removeAllRanges();
  const range = document.createRange();
  range.selectNodeContents(text);
  selection.addRange(range);
  expect(selection.toString()).toBe(message.text);
  try {
    fireEvent.doubleClick(row);
    expect(reply()).toBeNull();
  } finally {
    selection.removeAllRanges();
  }
  fireEvent.doubleClick(row);
  expect(reply()).toBeTruthy();
  expect(document.activeElement).toBe(screen.getByRole("textbox", { name: "Write a message" }));
  fireEvent.click(reply()!);
  rerender(<TelegramPage live={{ ...data, messageDoubleClick: "reaction" }} />);
  fireEvent.doubleClick(row);
  await waitFor(() => expect(setReaction).toHaveBeenCalledExactlyOnceWith("42", "52", quick, true));
  expect(reply()).toBeNull();
  rerender(<TelegramPage live={{ ...data, messageDoubleClick: "off" }} />);
  fireEvent.doubleClick(row);
  expect(setReaction).toHaveBeenCalledTimes(1);
  expect(reply()).toBeNull();
  expect(sendText).not.toHaveBeenCalled();
});

