test("quotes a selection across rich history blocks through the normal reply action", async () => {
  const heading = "🙂 Fixture heading";
  const message = { id: "24", author: "Fixture author", time: "", text: heading, canQuote: true as const,
    richMessage: { complete: true, rtl: false, quoteLayout: true as const, blocks: [
      { kind: "heading" as const, content: { text: heading, styles: [{ offset: 3, length: 15, style: "italic" as const }] } },
      { kind: "math" as const, expression: "x^2" },
      { kind: "paragraph" as const, content: { text: "Hidden", styles: [{ offset: 0, length: 6, style: "spoiler" as const }] } },
      { kind: "paragraph" as const, content: { text: "Before collapsed quote" } },
      { kind: "quote" as const, expandable: true as const, content: { text: "Collapsed fixture" } },
      { kind: "paragraph" as const, content: { text: "After collapsed quote" } },
    ] } };
  const neighbor = { ...message, id: "25", author: "Other fixture author" };
  const sendText = vi.fn(async () => ({ state: "failed" as const }));
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Rich selection fixture", initials: "RS", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], sendText,
    loadHistory: async () => ({ before: null, messages: [message, neighbor] }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Rich selection fixture/ }));
  const articles = await screen.findAllByRole("article", { name: "Rich Telegram message" });
  const [article, other] = articles;
  const source = article!.querySelector(".mtg-text-italic")!.firstChild!;
  const formula = article!.querySelector("math mi")!.firstChild!;
  const spoiler = article!.querySelector(".mtg-spoiler")!.firstChild!;
  const reply = within(article!.closest("li")!).getByRole("button", { name: "Reply to message" });
  const selection = document.getSelection()!;
  function select(end: Node, offset: number, start = source) {
    const range = document.createRange();
    range.setStart(start, 0);
    range.setEnd(end, offset);
    selection.removeAllRanges();
    selection.addRange(range);
  }
  try {
    select(within(article!).getByText("After collapsed quote").firstChild!, 5,
      within(article!).getByText("Before collapsed quote").firstChild!);
    expect(fireEvent.mouseDown(reply, { button: 0 })).toBe(true);
    fireEvent.mouseUp(reply, { button: 0 });
    for (const end of [spoiler, other!.querySelector(".mtg-text-italic")!.firstChild!]) {
      select(end, 1);
      expect(fireEvent.mouseDown(reply, { button: 0 })).toBe(true);
      fireEvent.mouseUp(reply, { button: 0 });
    }
    select(formula, 1);
    expect(fireEvent.mouseDown(reply, { button: 0 })).toBe(false);
    fireEvent.mouseUp(reply, { button: 0 });
    fireEvent.click(reply);
    expect(screen.getByRole("button", { name: "Remove quote" })).toBeTruthy();
    expect(screen.queryByRole("textbox", { name: "Select the passage to quote" })).toBeNull();
    expect(selection.isCollapsed).toBe(true);
    const input = screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" });
    expect(document.activeElement).toBe(input);
    fireEvent.change(input, { target: { value: "Fixture reply" } });
    fireEvent.submit(input.form!);
    await waitFor(() => expect(sendText).toHaveBeenCalledExactlyOnceWith("42", "Fixture reply", "24", {
      quote: { text: "Fixture heading\nx^2", position: 3, rich: true },
    }));
  } finally { selection.removeAllRanges(); }
});

