test.each([false, true])("resumes a topic in its own context unless scrolled back to the latest message (%s)", async (returnedToLatest) => {
  const anchor = { id: "18", text: "Topic reading anchor", author: "Fixture", time: "", forumTopicId: 17 };
  const recent = { ...anchor, id: "30", text: "Recent topic fixture" };
  const topics = [{ id: 17, name: "Reading topic", closed: false }, { id: 19, name: "Another topic", closed: false }];
  let first = true;
  const loadTopicHistory = vi.fn(async (_chatId: string, topicId: number) => {
    if (topicId !== 17) return { before: null, messages: [{ ...recent, forumTopicId: 19, text: "Another topic message" }] };
    if (first) {
      first = false;
      return { before: null, messages: [anchor, recent] };
    }
    return { before: "30", messages: [recent] };
  });
  const loadMessageContext = vi.fn(async () => [anchor]);
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Reading forum", initials: "RF", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: vi.fn(), refresh: vi.fn(), loading: false, liveRevision: 0, error: "",
    findChats: async () => [], sendText: vi.fn(), loadHistory: async () => ({ before: null, messages: [] }),
    loadForumTopics: async () => topics, loadTopicHistory, loadMessageContext,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Reading forum/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(await screen.findByRole("button", { name: "Reading topic" }));
  const row = (await screen.findByText(anchor.text)).closest("li")!;
  const history = screen.getByRole("list", { name: "Topic messages" });
  Object.defineProperties(history, { scrollHeight: { value: 1000 }, clientHeight: { value: 200 } });
  vi.spyOn(history, "getBoundingClientRect").mockReturnValue(new DOMRect(0, 40, 200, 200));
  vi.spyOn(row, "getBoundingClientRect").mockReturnValue(new DOMRect(0, 50, 200, 80));
  history.scrollTop = 300;
  fireEvent.scroll(history);
  expect(screen.getByRole("button", { name: "Jump to latest topic message" })).toBeTruthy();
  if (returnedToLatest) {
    history.scrollTop = 800;
    fireEvent.scroll(history);
    expect(screen.queryByRole("button", { name: "Jump to latest topic message" })).toBeNull();
  }
  fireEvent.click(screen.getByRole("button", { name: "Back to topics" }));
  fireEvent.click(screen.getByRole("button", { name: "Back to conversation" }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(await screen.findByRole("button", { name: "Another topic" }));
  await screen.findByText("Another topic message");
  expect(screen.queryByRole("button", { name: "Resume reading" })).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Back to topics" }));
  fireEvent.click(screen.getByRole("button", { name: "Reading topic" }));
  await screen.findByText(recent.text);
  expect(loadMessageContext).not.toHaveBeenCalled();
  if (returnedToLatest) {
    expect(screen.queryByRole("button", { name: "Resume reading" })).toBeNull();
    return;
  }
  expect(screen.getByText(anchor.text)).toBeTruthy();
  expect(screen.queryByRole("button", { name: "Resume reading" })).toBeNull();
  expect(loadTopicHistory.mock.calls.filter(([, topicId]) => topicId === 17)).toHaveLength(2);
});

test("refreshes a forum topic when an update arrives during the first history request", async () => {
  const message = (id: string) => ({ id, text: `Topic fixture ${id}`, author: "Fixture", time: "" });
  let completeFirst!: (page: { messages: ReturnType<typeof message>[]; before: string | null }) => void;
  const first = new Promise<{ messages: ReturnType<typeof message>[]; before: string | null }>((resolve) => { completeFirst = resolve; });
  const loadTopicHistory = vi.fn().mockReturnValueOnce(first)
    .mockResolvedValueOnce({ messages: [message("30")], before: "30" })
    .mockResolvedValueOnce({ messages: [message("20"), message("25")], before: "20" });
  const live = {
    chats: [{ id: "-42", name: "Fixture group", initials: "FX", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [], before: null }),
    loadForumTopics: async () => [{ id: 17, name: "Fixture topic", closed: false }],
    loadTopicHistory,
  };
  const view = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture group/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(screen.getByRole("button", { name: "Fixture topic" }));
  view.rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  expect(loadTopicHistory).toHaveBeenCalledTimes(1);
  completeFirst({ messages: [message("20")], before: "20" });
  const topic = within(screen.getByRole("list", { name: "Topic messages" }));
  await topic.findByText("Topic fixture 30");
  expect(topic.getAllByText(/^Topic fixture \d+$/).map((node) => node.textContent))
    .toEqual(["Topic fixture 20", "Topic fixture 25", "Topic fixture 30"]);
  expect(loadTopicHistory.mock.calls).toEqual([["-42", 17, undefined], ["-42", 17], ["-42", 17, "30"]]);
});

test("prepends topic history after scrolling upward and fills gaps on a live refresh", async () => {
  const message = (id: string) => ({ id, text: `Topic fixture ${id}`, author: "Fixture", time: "", outgoing: id === "20" });
  const loadTopicHistory = vi.fn()
    .mockResolvedValueOnce({ messages: [message("20"), message("20")], before: "20" })
    .mockResolvedValueOnce({ messages: [message("10")], before: null })
    .mockResolvedValueOnce({ messages: [message("40")], before: "40" })
    .mockResolvedValueOnce({ messages: [message("20"), message("30")], before: "20" });
  const live = {
    chats: [{ id: "-42", name: "Fixture group", initials: "FX", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [], before: null }),
    loadForumTopics: async () => [{ id: 17, name: "Fixture topic", closed: false }],
    loadTopicHistory, messageViewers: vi.fn(async () => []),
  };
  const view = render(<TelegramPage live={live} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture group/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(screen.getByRole("button", { name: "Fixture topic" }));
  const list = screen.getByRole("list", { name: "Topic messages" });
  await within(list).findByText("Topic fixture 20");
  const viewer = within(list).getByRole("button", { name: "Who viewed this message" });
  mockViewerDialog(viewer);
  fireEvent.click(viewer);
  const viewerPanel = await within(list).findByText("No recorded viewers yet.");
  fireEvent.scroll(list);
  expect(loadTopicHistory).toHaveBeenCalledTimes(1);
  list.scrollTop = 300;
  fireEvent.scroll(list);
  expect(loadTopicHistory).toHaveBeenCalledTimes(1);
  list.scrollTop = 40;
  fireEvent.scroll(list);
  await within(list).findByText("Topic fixture 10");

  view.rerender(<TelegramPage live={{ ...live, liveRevision: 1 }} />);
  await within(list).findByText("Topic fixture 40");
  expect(within(list).getAllByText(/Topic fixture \d+/).map((node) => node.textContent))
    .toEqual(["Topic fixture 10", "Topic fixture 20", "Topic fixture 30", "Topic fixture 40"]);
  expect(within(list).getAllByRole("button", { name: "Who viewed this message" })).toEqual([viewer]);
  expect(within(list).getAllByText("No recorded viewers yet.")).toEqual([viewerPanel]);
  expect(loadTopicHistory).toHaveBeenLastCalledWith("-42", 17, "40");
});

test("scopes message selection to the open forum topic", async () => {
  const options = vi.fn(async () => ["self" as const]);
  const remove = vi.fn(async () => "deleted" as const);
  const row = (id: string) => ({ id, text: `Fixture ${id}`, time: "", author: "Fixture" });
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Fixture forum", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], sendText: vi.fn(), batchDeletion: { options, remove },
    loadHistory: async () => ({ before: null, messages: [row("1")] }),
    loadForumTopics: async () => [{ id: 17, name: "First fixture topic", closed: false }, { id: 18, name: "Second fixture topic", closed: false }],
    loadTopicHistory: async (_, id) => ({ before: null, messages: id === 17 ? [row("8"), row("9")] : [row("10"), row("11")] }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture forum/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(screen.getByRole("button", { name: "First fixture topic" }));
  fireEvent.click(await screen.findByRole("button", { name: "Select messages" }));
  for (const box of within(screen.getByRole("list", { name: "Topic messages" })).getAllByRole("checkbox", { name: "Select message" })) {
    fireEvent.click(box);
  }
  fireEvent.click(screen.getByRole("button", { name: "Review selected deletion" }));
  await screen.findByRole("button", { name: "Delete selected for me" });
  expect(options).toHaveBeenCalledExactlyOnceWith("-42", ["8", "9"]);
  expect(remove).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Back to topics" }));
  fireEvent.click(screen.getByRole("button", { name: "Second fixture topic" }));
  await screen.findByRole("button", { name: "Select messages" });
  expect(screen.queryByRole("button", { name: "Delete selected for me" })).toBeNull();
});

