  const source = { id: "15", text: "", time: "", author: "Fixture",
    richMessage: { complete: true, rtl: false, blocks: [{ kind: "paragraph" as const, content: {
      text: label, botCommands: [{ offset: 0, length: label.length, command: "/status@fixture_bot" }],
    } }] } };
  const runRichBotCommand = vi.fn(async () => ({ state: "sent" as const, message: { ...source, id: "16" } }));
  const outer = vi.fn();
