  expect(load).not.toHaveBeenCalled();
  const results = within(screen.getByRole("list", { name: "Matching messages" })).getAllByRole("listitem");
  const received = results.find((item) => item.textContent?.includes("Received fixture"));
  const sent = results.find((item) => item.textContent?.includes("Sent fixture"));
