  const receivedMenu = within(screen.getByRole("group", { name: "Object actions" }));
  expect(receivedMenu.getByRole("button", { name: "Copy message reference" })).toBeTruthy();
  expect(receivedMenu.queryByRole("button", { name: "Who viewed this message" })).toBeNull();
  expect(load).not.toHaveBeenCalled();
  expect(fireEvent.contextMenu(sent!)).toBe(false);
  const sentMenu = within(screen.getByRole("group", { name: "Object actions" }));
