test("retries failed avatar downloads while visible and pauses them offscreen", async () => {
  let update!: IntersectionObserverCallback;
  class Observer {
    constructor(callback: IntersectionObserverCallback) { update = callback; }
    observe() {}
    disconnect() {}
  }
  vi.stubGlobal("IntersectionObserver", Observer);
  vi.useFakeTimers();
  const load = vi.fn()
    .mockRejectedValueOnce(new Error("First transient failure"))
    .mockRejectedValueOnce(new Error("Second transient failure"))
    .mockRejectedValueOnce(new Error("Still reconnecting"))
    .mockResolvedValueOnce({ mime: "image/webp", base64: "AAAA" });
  const chat = { id: "42", initials: "FX", color: "#246dbd", avatarJpeg: "/9j/AA==", avatarFileId: 7 };
  try {
    const { container } = render(<Avatar chat={chat} load={load} />);
    const reveal = (isIntersecting: boolean) => act(async () => update(
      [{ isIntersecting } as IntersectionObserverEntry], {} as IntersectionObserver,
    ));
    const src = () => container.querySelector("img")?.getAttribute("src");
    expect(load).not.toHaveBeenCalled();
    await act(async () => update(
      [{ isIntersecting: true }, { isIntersecting: false }] as IntersectionObserverEntry[],
      {} as IntersectionObserver,
    ));
    expect(load).not.toHaveBeenCalled();
    await reveal(true);
    expect(load).toHaveBeenCalledTimes(1);
    expect(src()).toBe("data:image/jpeg;base64,/9j/AA==");
    await reveal(false);
    await act(async () => {
      window.dispatchEvent(new Event("online"));
      await vi.advanceTimersByTimeAsync(5000);
    });
    expect(load).toHaveBeenCalledTimes(1);
    await reveal(true);
    expect(load).toHaveBeenCalledTimes(2);
    await act(async () => vi.advanceTimersByTimeAsync(350));
    expect(load).toHaveBeenCalledTimes(3);
    expect(src()).toBe("data:image/jpeg;base64,/9j/AA==");
    await act(async () => { window.dispatchEvent(new Event("online")); });
    expect(load).toHaveBeenCalledTimes(4);
    expect(src()).toBe("data:image/webp;base64,AAAA");
    await act(async () => vi.advanceTimersByTimeAsync(60000));
    expect(load).toHaveBeenCalledTimes(4);
  } finally {
    vi.useRealTimers();
    vi.unstubAllGlobals();
  }
});

test("rejects undecodable avatar bytes before accepting a retry", async () => {
  const original = Object.getOwnPropertyDescriptor(HTMLImageElement.prototype, "decode");
  const decode = vi.fn().mockRejectedValueOnce(new Error("Fixture decoding failure")).mockResolvedValue(undefined);
  Object.defineProperty(HTMLImageElement.prototype, "decode", { configurable: true, value: decode });
  const photo = { mime: "image/png" as const, base64: "AAAA" };
  try {
    await expect(decodeAvatar(photo)).rejects.toThrow("Fixture decoding failure");
    await expect(decodeAvatar(photo)).resolves.toBe(photo);
    expect(decode).toHaveBeenCalledTimes(2);
  } finally {
    if (original) Object.defineProperty(HTMLImageElement.prototype, "decode", original);
    else Reflect.deleteProperty(HTMLImageElement.prototype, "decode");
  }
});

