test.each([
  { code: "KeyI", altKey: true, shiftKey: true },
  { key: "\\", code: "Backslash", ctrlKey: true },
])("keeps one chat details trigger across chat changes and scopes its keyboard shortcut %j", async (shortcut) => {
  const chats = ["First", "Second"].map((name, index) => ({
    id: String(index + 42), name: name + " fixture", initials: "FX", color: "#246dbd",
    subtitle: "Group", archived: false, messages: [],
  }));
  const chatAgentAccess = vi.fn(async () => false);
  const loadSharedContentCounts = vi.fn(async () => ({ photoVideo: 17, document: 0 }));
  const { container } = render(<TelegramPage live={{
    chats, folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false,
    liveRevision: 0, error: "", loadHistory: async () => ({ messages: [], before: null }),
    findChats: async () => [], sendText: vi.fn(), chatAgentAccess,
    setChatAgentAccess: vi.fn(async () => true), chatNotificationState: async () => ({ mode: "default" }),
    setChatNotificationMode: async () => "updated", searchMessages: async () => ({ messages: [], before: null }), loadSharedContentCounts,
  }} />);
  for (const name of ["First", "Second", "First", "Second"]) {
    fireEvent.click(screen.getByRole("button", { name: new RegExp(name + " fixture") }));
    expect(screen.getAllByRole("button", { name: "Chat details" })).toHaveLength(1);
    expect(screen.queryByRole("button", { name: "Chat notification settings" })).toBeNull();
  }
  const details = screen.getByRole("button", { name: "Chat details" });
  const dialog = container.querySelector("dialog")!;
  dialog.showModal = () => { dialog.open = true; };
  fireEvent.keyDown(screen.getByRole("searchbox", { name: "Search Telegram chats" }), shortcut);
  expect(dialog.open).toBe(false);
  fireEvent.keyDown(details, shortcut);
  const settings = screen.getByRole("dialog", { name: "Chat details" });
  expect(await within(settings).findByRole("checkbox")).toBeTruthy();
  await waitFor(() => expect(within(settings).getByRole("button", { name: "Shared media" }).getAttribute("aria-description")).toBe("17 messages"));
  expect(loadSharedContentCounts).toHaveBeenCalledExactlyOnceWith("43");
  expect(within(settings).getAllByRole("button", { name: "Chat notification settings" })).toHaveLength(1);
  expect(chatAgentAccess).toHaveBeenCalledExactlyOnceWith("43");
  dialog.close = () => {
    dialog.open = false;
    fireEvent(dialog, new Event("close"));
    details.focus();
  };
  fireEvent.click(within(settings).getByRole("button", { name: "Shared media" }));
  const library = within(screen.getByRole("region", { name: "Shared media" }));
  const search = library.getByRole("searchbox", { name: "Search shared media" });
  expect(document.activeElement).toBe(search);
  expect(library.getByRole("button", { name: /Photos and videos.*17/, pressed: true })).toBeTruthy();
  expect(library.queryByRole("button", { name: /GIFs/ })).toBeNull();
  fireEvent.click(library.getByRole("button", { name: "Files" }));
  expect(library.getByRole("button", { name: "Files 0", pressed: true })).toBeTruthy();
  expect(screen.queryByRole("button", { name: "Chat details" })).toBeNull();
  fireEvent.click(library.getByRole("button", { name: "Back to conversation" }));
  await waitFor(() => expect(document.activeElement).toBe(screen.getByRole("heading", { name: "Second fixture" })));
  fireEvent.click(details);
  fireEvent.click(within(settings).getByRole("button", { name: "Shared media" }));
  const reopenedSearch = within(screen.getByRole("region", { name: "Shared media" })).getByRole("searchbox");
  expect(document.activeElement).toBe(reopenedSearch);
  fireEvent.keyDown(reopenedSearch, { key: "f", metaKey: true });
  const searchConversation = screen.getByRole("button", { name: "Search conversation" });
  expect(screen.queryByRole("group", { name: "Shared content type" })).toBeNull();
  const chatSearch = screen.getByRole("searchbox", { name: "Find in this conversation" });
  expect(document.activeElement).toBe(chatSearch);
  expect(searchConversation.getAttribute("aria-pressed")).toBe("true");
  fireEvent.keyDown(chatSearch, { key: "Escape" });
  expect(screen.queryByRole("region", { name: "Conversation search" })).toBeNull();
  expect(document.activeElement).toBe(screen.getByRole("heading", { name: "Second fixture" }));
});

