test("previews a focused chat without switching the active conversation or marking messages read", async () => {
  const current = { id: "42", name: "Current fixture chat", initials: "C", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const other = { ...current, id: "43", name: "Preview fixture chat", unread: 2 };
  const loadHistory = vi.fn(async (id: string) => id === other.id ? { before: "2", messages: [
    { id: "3", author: "Preview sender", time: "13:45", text: "Public hidden", styles: [{ style: "spoiler" as const, offset: 7, length: 6 }] },
    { id: "4", author: "Preview sender", time: "13:46", text: "View once", oneView: "photo" as const, hasPhoto: true },
    { id: "5", author: "Preview sender", time: "13:47", text: "Photo", hasPhoto: true, photoCaption: "Photo fixture caption" },
  ] } : { before: null, messages: [{ id: "6", author: "Current sender", time: "", text: "Current fixture message" }] });
  const loadPhoto = vi.fn(async () => ({ mime: "image/jpeg" as const, base64: "ZmFrZQ==" }));
  const markChat = vi.fn(async () => other);
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const close = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(prototype, "close", { configurable: true, value(this: HTMLDialogElement) {
    this.open = false;
    fireEvent(this, new Event("close"));
  } });
  try {
    render(<TelegramPage live={{ chats: [current, other], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false,
      liveRevision: 0, error: "", loadHistory, loadPhoto, findChats: async () => [], sendText: vi.fn(), markChat }} />);
    fireEvent.click(screen.getByRole("button", { name: /Current fixture chat/ }));
    await screen.findByText("Current fixture message");
    const shortcut = { key: "]", code: "BracketRight", ctrlKey: true };
    fireEvent.keyDown(screen.getByRole("textbox", { name: "Write a message" }), shortcut);
    expect(screen.queryByRole("dialog", { name: "Chat preview" })).toBeNull();
    const row = screen.getByRole("button", { name: /Preview fixture chat/ });
    row.focus();
    fireEvent.keyDown(row, shortcut);
    const dialog = within(await screen.findByRole("dialog", { name: "Chat preview" }));
    await dialog.findByText("Public [Spoiler]");
    expect(dialog.getByText("One-view photo")).toBeTruthy();
    expect(dialog.getAllByRole("button", { name: "Show photo" })).toHaveLength(1);
    expect(loadPhoto).not.toHaveBeenCalled();
    fireEvent.click(dialog.getByRole("button", { name: "Show photo" }));
    await dialog.findByRole("img", { name: "Telegram photo" });
    expect(loadPhoto).toHaveBeenCalledExactlyOnceWith("43", "5");
    fireEvent.click(dialog.getByRole("button", { name: "Close preview" }));
    expect(screen.getByRole("heading", { name: "Current fixture chat" })).toBeTruthy();
    expect(loadHistory.mock.calls.filter(([id]) => id === "43")).toEqual([["43"]]);
    expect(markChat).not.toHaveBeenCalled();
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (close) Object.defineProperty(prototype, "close", close);
    else Reflect.deleteProperty(prototype, "close");
  }
});

