test("shows progress and cancels an attachment replacement before dispatch", async () => {
  const { MessageEdit } = await import("../src/ui/message-edit.tsx");
  const file = new File(["fixture"], "test.txt", { type: "text/plain" });
  let transfer!: import("../src/ui/message-edit.tsx").ReplacementProgress;
  let signal!: AbortSignal;
  const replaceAttachment = vi.fn((_file: File, progress: typeof transfer, request: AbortSignal) => {
    transfer = progress;
    signal = request;
    return new Promise<void>((resolve) => signal.addEventListener("abort", () => resolve(), { once: true }));
  });
  render(<MessageEdit draft={{
    message: { id: "13", text: "Caption", time: "", author: "You", editableCaption: true,
      document: { name: "old.txt", caption: "Caption", downloadable: true },
      attachmentEdit: { kind: "document", revision: "0".repeat(64) } }, text: "Caption", busy: false,
  }} change={() => {}} cancel={() => {}} save={() => {}} replaceAttachment={replaceAttachment} />);
  fireEvent.change(screen.getByLabelText("Choose replacement file"), { target: { files: [file] } });
  fireEvent.click(screen.getByRole("button", { name: "Replace file and keep caption" }));
  act(() => transfer(3, true));
  expect(screen.getByRole<HTMLProgressElement>("progressbar", { name: "Uploading replacement to BB" }).value).toBe(3);
  act(() => transfer(file.size, false));
  expect(screen.queryByRole("button", { name: "Cancel replacement upload" })).toBeNull();
  act(() => transfer(file.size, true));
  fireEvent.click(screen.getByRole("button", { name: "Cancel replacement upload" }));
  expect(signal.aborted).toBe(true);
  await waitFor(() => expect(screen.queryByRole("progressbar")).toBeNull());
  expect(replaceAttachment).toHaveBeenCalledTimes(1);
});

test("renders rich-message button rows and inline actions with validated URLs and explicit clipboard writes", async () => {
  const { parseRichMessage } = await import("../src/adapters/bb/rich-message.ts");
  const { RichMessage } = await import("../src/ui/rich-message.tsx");
  const plain = (text: string) => ({ "@type": "richTextPlain", text });
  const button = (label: string, type: object) => ({ "@type": "inlineButton", text: plain(label), type });
  const link = (url: string) => ({ "@type": "inlineKeyboardButtonTypeUrl", url });
  const url = "https://example.com/review";
  const clipboard = vi.fn().mockResolvedValue(undefined);
  const confirm = vi.spyOn(window, "confirm").mockReturnValue(false);
  const open = vi.spyOn(window, "open").mockReturnValue(null);
  const previous = Object.getOwnPropertyDescriptor(navigator, "clipboard");
  Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText: clipboard } });
  try {
    const formattedLink = { ...button("Review destination", link(url)),
      text: { "@type": "richTextBold", text: plain("Review destination") } };
    const parsed = parseRichMessage({ "@type": "richMessage", is_full: true, blocks: [
      { "@type": "pageBlockButtonRow", align: { "@type": "pageBlockHorizontalAlignmentRight" },
        buttons: [formattedLink, button("Unsafe action", link("javascript:void(0)"))] },
      { "@type": "pageBlockParagraph", text: { "@type": "richTextUrl", url: "https://example.com/outer",
        text: { "@type": "richTextButton", button: button("Copy reference",
          { "@type": "inlineKeyboardButtonTypeCopyText", text: "Synthetic reference" }) } } },
    ] });
    expect(parsed?.layout).toMatchObject({ complete: false, blocks: [
      { kind: "buttons", align: "right", buttons: [{ kind: "url", label: "Review destination", url }] },
      { kind: "paragraph", content: { text: "Copy reference" } },
    ] });
    expect(parsed?.preview).toBe("Review destination\nCopy reference");
    const { schemas } = await import("../src/core/contract.ts");
    const layout = schemas.history.output.shape.messages.element.parse({
      id: "8", author: "Fixture", time: "", text: "", richMessage: parsed!.layout,
    }).richMessage!;
    render(<RichMessage chatId="42" messageId="8" layout={layout} />);
    expect(screen.queryByText("Unsafe action")).toBeNull();
    const destination = screen.getByRole("button", { name: "Review destination" });
    expect(destination.querySelector(".mtg-text-bold")?.textContent).toBe("Review destination");
    expect(destination.parentElement?.querySelector(".mtg-action-destination")?.textContent).toBe(url);
    fireEvent.click(destination);
    expect(confirm.mock.calls[0]?.[0]).toContain(url);
    expect(open).not.toHaveBeenCalled();
    confirm.mockReturnValue(true);
    fireEvent.click(destination);
    expect(open).toHaveBeenCalledExactlyOnceWith(url, "_blank", "noopener,noreferrer");
    const copy = screen.getByRole("button", { name: "Copy reference" });
    expect(copy.closest("a")).toBeNull();
    expect(clipboard).not.toHaveBeenCalled();
    fireEvent.click(copy);
    await waitFor(() => expect(clipboard).toHaveBeenCalledExactlyOnceWith("Synthetic reference"));
    expect(screen.getByText("Copied.")).toBeTruthy();
  } finally {
    confirm.mockRestore();
    open.mockRestore();
    if (previous) Object.defineProperty(navigator, "clipboard", previous);
    else Reflect.deleteProperty(navigator, "clipboard");
  }
});

