test("round-trips portable Telegram HTML buttons and formulas without placing their actions on the clipboard", async () => {
  const { richMessageHtml } = await import("../src/core/rich-message-text.ts");
  const { readRichHtmlFile } = await import("../src/ui/rich-html-import.ts");
  const button = { kind: "copy" as const, label: "Copy", text: 'Clipboard fixture "<value>"', style: "primary" as const };
  const link = { kind: "url" as const, label: "Open page", url: "https://example.com/path" };
  const secret = { kind: "copy" as const, label: "Hide", text: "Masked fixture payload" };
  const layout: import("../src/core/contract.ts").RichMessageLayout = { rtl: false, complete: true, blocks: [
    { kind: "buttons", align: "center", buttons: [link, button] },
    { kind: "paragraph", content: { text: "Use Copy with x^2.", inlineButtons: [{ offset: 4, length: 4, button }],
      formulas: [{ offset: 14, length: 3 }] } },
    { kind: "math", expression: String.raw`\frac{x}{2}` },
    { kind: "code", language: "js", content: { text: "let x = 2;" } },
    { kind: "paragraph", content: { text: "Hide", styles: [{ offset: 0, length: 4, style: "spoiler" }],
      inlineButtons: [{ offset: 0, length: 4, button: secret }] } },
  ] };
  const portable = richMessageHtml(layout, true);
  expect(richMessageHtml(layout)).not.toContain("data-bb-button");
  expect(richMessageHtml(layout)).not.toContain("Clipboard fixture");
  expect(portable).not.toContain(secret.text);
  expect(readRichHtmlFile(portable, document)).toEqual({ omitted: false, draft: [
    { kind: "buttons", align: "center", buttons: [link, button] },
    { kind: "paragraph", text: "Use Copy with x^2.", inlineButtons: [{ offset: 4, length: 4, button }],
      formulas: [{ offset: 14, length: 3 }] },
    { kind: "math", expression: String.raw`\frac{x}{2}` },
    { kind: "code", language: "js", text: "let x = 2;" },
    { kind: "paragraph", text: "[Spoiler]" },
  ] });
  const forged = '<p><span data-bb-button=\'{"kind":"url","label":"Open","url":"javascript:void(0)"}\'>Open</span></p>';
  expect(readRichHtmlFile(forged, document)).toEqual({ omitted: true, draft: [{ kind: "paragraph", text: "Open" }] });
});

