    fireEvent.click(screen.getByRole("button", { name: "Copy selected text" }));
    const fallback = await screen.findByRole<HTMLTextAreaElement>("textbox", { name: "Selected message text" });
    expect(fallback.value).toBe(text);
    expect(copySelectedText).toHaveBeenCalledExactlyOnceWith("42", ["51"]);
