test("writes rich selection to both clipboard formats from the click", async () => {
  const { CopySelectedText } = await import("../src/ui/copy-selected-text.tsx");
  let resolve!: (value: { text: string; html: string }) => void;
  const promise = new Promise<{ text: string; html: string }>((complete) => { resolve = complete; });
  const write = vi.fn(async (items: { formats: Record<string, Promise<Blob>> }[]) => {
    await Promise.all(Object.values(items[0]!.formats));
  });
  const clipboard = Object.getOwnPropertyDescriptor(navigator, "clipboard");
  Object.defineProperty(navigator, "clipboard", { configurable: true, value: { write } });
  vi.stubGlobal("ClipboardItem", class {
    constructor(readonly formats: Record<string, Promise<Blob>>) {}
  });
  try {
    render(<CopySelectedText load={() => promise} />);
    fireEvent.click(screen.getByRole("button", { name: "Copy selected text" }));
    expect(write).toHaveBeenCalledTimes(1);
    const formats = write.mock.calls[0]![0][0]!.formats;
    expect(Object.keys(formats)).toEqual(["text/plain", "text/html"]);
    resolve({ text: "Fixture", html: "<strong>Fixture</strong>" });
    await screen.findByText("Selected text copied.");
    expect((await formats["text/plain"]!).type).toBe("text/plain");
    expect((await formats["text/html"]!).type).toBe("text/html");
  } finally {
    vi.unstubAllGlobals();
    if (clipboard) Object.defineProperty(navigator, "clipboard", clipboard);
    else Reflect.deleteProperty(navigator, "clipboard");
  }
});

