test.each(["profile", "community"])("previews a video avatar for a %s and uploads the reviewed range and cover on save", async (target) => {
  const createObjectURL = vi.fn(() => "blob:fixture");
  const revokeObjectURL = vi.fn();
  vi.stubGlobal("URL", Object.assign(class extends URL {}, { createObjectURL, revokeObjectURL }));
  const save = vi.fn(async () => "saved" as const);
  const saveVideo = vi.fn(async () => "saved" as const);
  const version = "a".repeat(64);
  try {
    if (target === "community") {
      const { CommunityBrowser } = await import("../src/ui/community-browser.tsx");
      const { container } = render(<CommunityBrowser actions={{
        list: async () => [{ id: "7", name: "Fixture community", photoVersion: version, canRename: true }],
        chats: async () => [], photos: { save, saveVideo, remove: vi.fn(),
          read: async () => ({ version: "b".repeat(64) }) },
      }} loadChat={vi.fn()} openChat={vi.fn()} />);
      const dialog = container.querySelector("dialog")!;
      dialog.showModal = () => { dialog.open = true; };
      fireEvent.click(screen.getByRole("button", { name: "Communities" }));
      fireEvent.click(await screen.findByRole("button", { name: "Fixture community" }));
    } else {
      render(<AvatarEditor label="profile photo" version={version} save={save} saveVideo={saveVideo}
        reload={async () => ({ version: "b".repeat(64), canRemove: false })} />);
    }
    fireEvent.change(screen.getByLabelText("Choose video avatar"), {
      target: { files: [new File(["fixture"], "avatar.mp4", { type: "video/mp4" })] },
    });
    const preview = screen.getByLabelText("Video avatar preview");
    const submit = screen.getByRole<HTMLButtonElement>("button", { name: "Save video avatar" });
    expect(submit.disabled).toBe(true);
    Object.defineProperties(preview, { duration: { value: 15 }, videoWidth: { value: 320 }, videoHeight: { value: 160 },
      currentTime: { value: 1.5, writable: true } });
    fireEvent.loadedMetadata(preview);
    fireEvent.change(screen.getByLabelText("End (seconds)"), { target: { value: "15" } });
    expect(submit.disabled).toBe(true);
    fireEvent.change(screen.getByLabelText("Start (seconds)"), { target: { value: "1" } });
    fireEvent.change(screen.getByLabelText("End (seconds)"), { target: { value: "4" } });
    fireEvent.seeked(preview);
    expect(submit.disabled).toBe(false);
    expect(saveVideo).not.toHaveBeenCalled();
    fireEvent.click(submit);
    expect(await screen.findByText("Video avatar saved.")).toBeTruthy();
    const expected = target === "community" ? ["7", version, "Zml4dHVyZQ=="] : ["Zml4dHVyZQ==", version];
    expect(saveVideo).toHaveBeenCalledExactlyOnceWith(...expected, 1.5, { start: 1, end: 4 });
    expect(save).not.toHaveBeenCalled();
    await waitFor(() => expect(revokeObjectURL).toHaveBeenCalledExactlyOnceWith("blob:fixture"));
  } finally { vi.unstubAllGlobals(); }
});

