test("opens a validated TON recipient from a revealed rich address without passing payment parameters", async () => {
  const { parseRichMessage } = await import("../src/adapters/bb/rich-message.ts");
  const address = "0:" + "fa".repeat(32);
  const source = (address: string) => ({
    "@type": "richMessage", is_full: true, blocks: [{ "@type": "pageBlockParagraph",
      text: { "@type": "richTextSpoiler", text: { "@type": "richTextTonAddress", address,
        text: { "@type": "richTextBold", text: { "@type": "richTextPlain", text: "Fixture recipient" } } } } }],
  });
  const parsed = parseRichMessage(source(address))!;
  expect(parsed.layout).toMatchObject({ complete: true, blocks: [{ content: {
    text: "Fixture recipient", tonAddresses: [{ offset: 0, length: 17, address }],
  } }] });
  expect(parseRichMessage(source(address + "&amount=5"))?.layout).toMatchObject({ complete: false,
    blocks: [{ content: { text: "Fixture recipient" } }] });
  const message = { id: "91", text: parsed.preview, time: "", author: "Fixture", richMessage: parsed.layout };
  const { rerender } = render(<MessageContent chatId="42" message={message} />);
  expect(screen.queryByRole("link", { name: /Open in Telegram Wallet/ })).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Show spoiler" }));
  const link = screen.getByRole("link", { name: "Open in Telegram Wallet: " + address });
  expect(link.querySelector(".mtg-text-bold")?.textContent).toBe("Fixture recipient");
  expect(link.getAttribute("href")).toBe("tg://sendgrams?to=" + encodeURIComponent(address));
  const target = new URL((link as HTMLAnchorElement).href);
  expect([...target.searchParams.entries()]).toEqual([["to", address]]);
  rerender(<MessageContent chatId="42" message={{ ...message, retained: "deleted" }} />);
  expect(screen.queryByRole("link", { name: /Open in Telegram Wallet/ })).toBeNull();
});

test("opens rich bank card actions on demand and copies while issuer information is loading", async () => {
  const { LoadRichBankCard } = await import("../src/ui/rich-bank-card.tsx");
  const reference = "a".repeat(64);
  const label = "Fixture card";
  const message = { id: "91", text: "", time: "", author: "Fixture",
    richMessage: { complete: true, rtl: false, blocks: [{ kind: "paragraph" as const, content: {
      text: label, styles: [{ offset: 0, length: label.length, style: "spoiler" as const }],
      bankCards: [{ offset: 0, length: label.length, reference }],
    } }] } };
  let finish!: (result: import("../src/core/contract.ts").RichBankCardResult) => void;
  const pending = new Promise<import("../src/core/contract.ts").RichBankCardResult>((resolve) => { finish = resolve; });
  const load = vi.fn((_chat: string, _message: string, _reference: string, mode: "copy" | "info") =>
    mode === "info" ? pending : Promise.resolve({ kind: "copy" as const, number: "0000000000000000" }));
  const saved = Object.getOwnPropertyDescriptor(navigator, "clipboard");
  const writeText = vi.fn(async () => {});
  Object.defineProperty(navigator, "clipboard", { configurable: true, value: { writeText } });
  try {
    render(<LoadRichBankCard.Provider value={load}><MessageContent chatId="42" message={message} /></LoadRichBankCard.Provider>);
    expect(screen.queryByRole("button", { name: label })).toBeNull();
    fireEvent.click(screen.getByRole("button", { name: "Show spoiler" }));
    const button = screen.getByRole("button", { name: label });
    expect(load).not.toHaveBeenCalled();
    fireEvent.click(button);
    expect(load).toHaveBeenCalledExactlyOnceWith("42", "91", reference, "info");
    fireEvent.click(screen.getByRole("button", { name: "Copy card number" }));
    await screen.findByText("Card number copied.");
    expect(writeText).toHaveBeenCalledExactlyOnceWith("0000000000000000");
    await act(async () => finish({ kind: "info", title: "Fixture issuer", links: [{ text: "Issuer help", url: "https://example.com/help" }] }));
    const link = await screen.findByRole("link", { name: "Issuer help" });
    expect(link.getAttribute("rel")).toBe("noopener noreferrer");
    fireEvent.keyDown(link, { key: "Escape" });
    expect(screen.queryByRole("group", { name: "Bank card actions" })).toBeNull();
    expect(document.activeElement).toBe(button);
  } finally {
    if (saved) Object.defineProperty(navigator, "clipboard", saved);
    else Reflect.deleteProperty(navigator, "clipboard");
  }
});

