test("removes deleted public results without another search or restoring them from a pending page", async () => {
  const { GlobalSearchResults } = await import("../src/ui/global-search.tsx");
  const { HistoryMessageUpdates } = await import("../src/ui/history-message-updates.ts");
  const hit = (chatId: string, id: string, text: string) => ({
    chat: { id: chatId, name: "Fixture channel", initials: "F", color: "#246dbd", subtitle: "Channel", messages: [] },
    message: { id, text, time: "", author: "Fixture" },
  });
  const removed = hit("-42", "9", "Deleted fixture");
  const other = hit("-43", "9", "Other chat fixture");
  const late = hit("-42", "10", "Late deleted fixture");
  const valid = hit("-42", "11", "Valid older fixture");
  let finishPage!: (page: { hits: ReturnType<typeof hit>[]; next: null }) => void;
  const search = vi.fn()
    .mockResolvedValueOnce({ hits: [removed, other], next: "older" })
    .mockImplementationOnce(() => new Promise((resolve) => { finishPage = resolve; }));
  let notify!: (event: MessagesDeleted) => void;
  render(<HistoryMessageUpdates.Provider value={{ load: vi.fn(), subscribe: () => () => {}, subscribeToDeletions(listener) {
    notify = listener;
    return () => {};
  } }}>
    <GlobalSearchResults mode="public" query="fixture" search={search} open={vi.fn()} />
  </HistoryMessageUpdates.Provider>);
  fireEvent.click(screen.getByRole("button", { name: "Search public posts" }));
  const otherButton = await screen.findByRole("button", { name: /Other chat fixture/ });
  expect(screen.getByRole("button", { name: /Deleted fixture/ })).toBeTruthy();
  fireEvent.click(screen.getByRole("button", { name: "Load more results" }));
  act(() => notify({ id: "-42", messageIds: ["10"], retained: [{ ...removed.message, retained: "deleted" }] }));
  expect(screen.queryByRole("button", { name: /Deleted fixture/i })).toBeNull();
  await act(async () => finishPage({ hits: [removed, late, valid], next: null }));
  await screen.findByRole("button", { name: /Valid older fixture/ });
  expect(screen.queryByRole("button", { name: /Deleted fixture/i })).toBeNull();
  expect(screen.getByRole("button", { name: /Other chat fixture/ })).toBe(otherButton);
  expect(search).toHaveBeenCalledTimes(2);
});

test("marks a retained deletion in nearby history and removes it from conversation search", async () => {
  const { HistoryMessageUpdates } = await import("../src/ui/history-message-updates.ts");
  const target = { id: "10", text: "Fixture report", time: "", author: "Fixture" };
  const search = vi.fn(async () => ({ messages: [target], before: null }));
  const load = vi.fn();
  const listeners = new Set<(event: MessagesDeleted) => void>();
  render(<HistoryMessageUpdates.Provider value={{ load, subscribe: () => () => {}, subscribeToDeletions(listener) {
    listeners.add(listener);
    return () => { listeners.delete(listener); };
  } }}>
    <ConversationSearch chatId="42" search={search} loadContext={async () => [target]} close={vi.fn()} />
  </HistoryMessageUpdates.Provider>);
  fireEvent.change(screen.getByRole("searchbox", { name: "Find in this conversation" }), { target: { value: "report" } });
  fireEvent.click(screen.getByRole("button", { name: "Find" }));
  fireEvent.click(await screen.findByRole("button", { name: "Show nearby messages" }));
  const nearby = await screen.findByRole("list", { name: "Nearby messages" });
  await waitFor(() => expect(nearby.querySelector('[data-context-id="10"]')?.textContent).toContain("Fixture report"));
  const row = nearby.querySelector('[data-context-id="10"]');
  act(() => {
    for (const notify of listeners) notify({ id: "42", messageIds: [], retained: [{ ...target, retained: "deleted" }] });
  });
  expect(within(nearby).getByText("Deleted in Telegram · kept locally").closest("li")).toBe(row);
  fireEvent.click(screen.getByRole("button", { name: "Back to results" }));
  expect(screen.queryByRole("button", { name: "Show nearby messages" })).toBeNull();
  expect(search).toHaveBeenCalledOnce();
  expect(load).not.toHaveBeenCalled();
});

