test("submits public post search and opens a result from the keyboard", async () => {
  const chat = { id: "-42", name: "Synthetic channel", initials: "SC", color: "#246dbd", subtitle: "Channel", messages: [] };
  const message = { id: "19", text: "Public result fixture", time: "10:00", author: "Fixture" };
  const globalSearch = vi.fn(async () => ({ hits: [{ chat, message }], next: "fixture-cursor" }));
  const loadMessageContext = vi.fn(async () => [message]);
  render(<TelegramPage live={{
    chats: [chat], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory: async () => ({ before: null, messages: [] }), globalSearch, findChats: async () => [], loadMessageContext, sendText: vi.fn(),
  }} />);
  selectChatSearchScope("Public posts");
  const search = screen.getByRole("searchbox", { name: "Search Telegram messages" });
  fireEvent.change(search, { target: { value: "fixture" } });
  search.focus();
  fireEvent.keyDown(search, { key: "Enter", ctrlKey: true });
  expect(globalSearch).not.toHaveBeenCalled();
  fireEvent.keyDown(search, { key: "ArrowDown" });
  const submit = screen.getByRole("button", { name: "Search public posts" });
  expect(document.activeElement).toBe(submit);
  fireEvent.keyDown(submit, { key: "Escape" });
  expect(document.activeElement).toBe(search);
  expect(fireEvent.keyDown(search, { key: "Enter" })).toBe(false);
  const hit = await screen.findByRole("button", { name: /Public result fixture/ });
  expect(globalSearch).toHaveBeenCalledExactlyOnceWith({ query: "fixture", mode: "public" });
  fireEvent.keyDown(search, { key: "ArrowDown" });
  expect(document.activeElement).toBe(hit);
  fireEvent.keyDown(hit, { key: "ArrowDown" });
  const more = screen.getByRole("button", { name: "Load more results" });
  expect(document.activeElement).toBe(more);
  fireEvent.keyDown(more, { key: "Escape" });
  expect(document.activeElement).toBe(search);
  fireEvent.keyDown(search, { key: "Enter" });
  await screen.findByRole("region", { name: "Message context" });
  expect(loadMessageContext).toHaveBeenCalledWith("-42", "19");
});

