test.each(["Messages", "Media", "Public posts"] as const)(
  "returns from a global %s result to the exact row and existing pages", async (tab) => {
    const chat = { id: "-42", name: "Fixture forum", initials: "FF", color: "#246dbd", subtitle: "Group", messages: [] };
    const topic = { id: 15, name: "Fixture topic", closed: false };
    const first = { id: "24", text: "Fixture first match", author: "Fixture", time: "", forumTopicId: 15 };
    const second = { ...first, id: "23", text: "Fixture older match" };
    const loadMessageContext = vi.fn(async () => [second, first]);
    const loadForumTopics = vi.fn(async () => [topic]);
    const globalSearch = vi.fn(async (input: Parameters<import("../src/ui/global-search.tsx").GlobalSearchLoader>[0]) => ({
      hits: [{ chat, message: input.cursor ? second : first }], next: input.cursor ? null : "fixture-next",
    }));
    render(<TelegramPage live={{
      chats: [chat], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      findChats: async () => [], sendText: async () => ({ state: "failed" }),
      loadHistory: async () => ({ messages: [], before: null }),
      loadTopicHistory: async () => ({ messages: [], before: null }), loadForumTopics, loadMessageContext, globalSearch,
    }} />);
    if (tab === "Messages") fireEvent.change(screen.getByRole("searchbox"), { target: { value: "Fixture" } });
    selectChatSearchScope(tab);
    const input = screen.getByRole("searchbox");
    fireEvent.change(input, { target: { value: "Fixture" } });
    if (tab === "Public posts") fireEvent.click(screen.getByRole("button", { name: "Search public posts" }));
    fireEvent.click(await screen.findByRole("button", { name: "Load more results" }));
    const hit = await screen.findByRole("button", { name: /Fixture older match/ });
    const list = hit.closest("ul")!;
    list.scrollTop = 84;
    hit.focus();
    fireEvent.click(hit);
    const context = await screen.findByRole("region", { name: "Message context" });
    await within(context).findByRole("list", { name: "Nearby messages" });
    expect(loadMessageContext).toHaveBeenCalledExactlyOnceWith("-42", "23", 15);
    expect(await within(context).findByRole("button", { name: "Open containing topic" })).toBeTruthy();
    list.scrollTop = 0;
    const back = within(context).getByRole("button", { name: "Back to search results" });
    back.focus();
    if (tab === "Messages") fireEvent.click(back);
    else if (tab === "Media") fireEvent.keyDown(back, { key: "Escape" });
    else fireEvent.click(screen.getByRole("button", { name: "Back to chats" }));
    await waitFor(() => expect(document.activeElement).toBe(hit));
    expect(list.scrollTop).toBe(84);
    expect(input).toHaveProperty("value", "Fixture");
    expect(globalSearch).toHaveBeenCalledTimes(2);

    fireEvent.click(hit);
    const reopened = await screen.findByRole("region", { name: "Message context" });
    fireEvent.click(await within(reopened).findByRole("button", { name: "Open containing topic" }));
    await screen.findByRole("heading", { name: "Fixture topic" });
    expect(screen.queryByRole("region", { name: "Message context" })).toBeNull();
  },
);

