test("shows the account's 18+ setting and applies only a user change while Telegram allows editing", async () => {
  const { TelegramPrivacy } = await import("../src/ui/telegram-privacy.tsx");
  const load = vi.fn().mockResolvedValueOnce({ show: false, editable: true })
    .mockResolvedValueOnce({ show: true, editable: false, ageVerificationRequired: true, verificationBot: "FixtureVerifyBot" })
    .mockResolvedValueOnce({ show: true, editable: false });
  const save = vi.fn().mockResolvedValueOnce("saved").mockResolvedValueOnce("changed");
  render(<TelegramPrivacy actions={{ load: async () => ({ version: "fixture", audience: "everyone", exceptions: 0 }),
    save: async () => "saved", loadReadDate: async () => true, saveReadDate: async () => "saved",
    sensitiveContent: { load, save } }} />);
  expect(load).not.toHaveBeenCalled();
  const privacy = screen.getByText("Privacy", { selector: "summary" }).closest("details")!;
  privacy.open = true;
  fireEvent(privacy, new Event("toggle"));
  const setting = await screen.findByRole<HTMLInputElement>("switch", { name: "Show 18+ Content" });
  await waitFor(() => expect(setting.disabled).toBe(false));
  expect(setting.checked).toBe(false);
  expect(save).not.toHaveBeenCalled();
  fireEvent.click(setting);
  await waitFor(() => expect(setting.checked).toBe(true));
  expect(save).toHaveBeenCalledExactlyOnceWith(true, false);
  fireEvent.click(setting);
  await screen.findByText("This setting changed in Telegram.");
  fireEvent.click(screen.getByRole("button", { name: "Reload sensitive content setting" }));
  const verify = await screen.findByRole("link", { name: "Verify age in Telegram" });
  expect(verify.getAttribute("href")).toBe("https://t.me/FixtureVerifyBot?startapp");
  expect(verify.getAttribute("rel")).toContain("noreferrer");
  expect(setting.disabled).toBe(true);
  fireEvent.click(screen.getByRole("button", { name: "Check verification status" }));
  await screen.findByText("Telegram does not allow this account to change this setting.");
  expect(screen.queryByRole("link", { name: "Verify age in Telegram" })).toBeNull();
  expect(setting.disabled && setting.checked).toBe(true);
  expect(save.mock.calls).toEqual([[true, false], [false, true]]);
});

test.each(["manual close", "reported result"])("refreshes Telegram's age check after %s", async (mode) => {
  const { TelegramPrivacy } = await import("../src/ui/telegram-privacy.tsx");
  let confirmed = false;
  const load = vi.fn(async () => confirmed ? { show: false, editable: true } : {
    show: false, editable: false, ageVerificationRequired: true as const, verificationBot: "FixtureVerifyBot",
  });
  const save = vi.fn();
  const launchVerification = vi.fn(async () => ({ url: "https://example.com/fixture-check" }));
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    render(<TelegramPrivacy actions={{ load: async () => ({ version: "fixture", audience: "everyone", exceptions: 0 }),
      save: async () => "saved", loadReadDate: async () => true, saveReadDate: async () => "saved",
      sensitiveContent: { load, save, launchVerification } }} />);
    const privacy = screen.getByText("Privacy", { selector: "summary" }).closest("details")!;
    privacy.open = true;
    fireEvent(privacy, new Event("toggle"));
    const start = await screen.findByRole("button", { name: "Verify age in BB" });
    const setting = screen.getByRole<HTMLInputElement>("switch", { name: "Show 18+ Content" });
    expect(setting.disabled).toBe(true);
    expect(screen.getByRole("link", { name: "Verify age in Telegram" })).toBeTruthy();
    fireEvent.click(start);
    const dialog = await screen.findByRole("dialog", { name: "Telegram Mini App" });
    expect(within(dialog).getByText("Age verification · @FixtureVerifyBot")).toBeTruthy();
    expect(launchVerification).not.toHaveBeenCalled();
    fireEvent.click(within(dialog).getByRole("button", { name: "Open Mini App" }));
    const frame = await within(dialog).findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(frame.getAttribute("src")).toBe("https://example.com/fixture-check");
    expect(frame.getAttribute("sandbox")).toBe("allow-scripts");
    expect(setting.disabled).toBe(true);
    if (mode === "reported result") {
      const report = (source: MessageEventSource | null, passed: unknown) => fireEvent(window, new MessageEvent("message", {
        origin: "null", source, data: JSON.stringify({ eventType: "web_app_verify_age", eventData: { passed, age: 21 } }),
      }));
      report(window, true);
      report(frame.contentWindow, "true");
      report(frame.contentWindow, false);
      expect(load).toHaveBeenCalledTimes(1);
      report(frame.contentWindow, true);
      await within(dialog).findByText("Telegram has not confirmed age verification yet.");
      expect(setting.disabled).toBe(true);
      report(frame.contentWindow, true);
      expect(load).toHaveBeenCalledTimes(2);
      confirmed = true;
      fireEvent.click(within(dialog).getByRole("button", { name: "Check verification status" }));
      await waitFor(() => expect(screen.queryByRole("dialog", { name: "Telegram Mini App" })).toBeNull());
    } else {
      confirmed = true;
      fireEvent.click(within(dialog).getByRole("button", { name: "Close Mini App" }));
    }
    await waitFor(() => expect(setting.disabled).toBe(false));
    expect(launchVerification).toHaveBeenCalledExactlyOnceWith("FixtureVerifyBot");
    expect(load).toHaveBeenCalledTimes(mode === "reported result" ? 4 : 2);
    expect(save).not.toHaveBeenCalled();
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

