function selectChatSearchScope(name: string) {
  const trigger = screen.queryByRole("button", { name: "Search scope" });
  if (trigger) {
    fireEvent.click(trigger);
    const scope = within(screen.getByRole("group", { name: "Search scope" }));
    if (!["Chats", "Messages", "Media"].includes(name)) {
      const extra = scope.getByText("More…", { selector: "summary" });
      if (!extra.closest("details")?.open) fireEvent.click(extra);
    }
    fireEvent.click(scope.getByRole("button", { name }));
  } else {
    fireEvent.click(screen.getByRole("button", { name: "Chat list actions" }));
    const options = within(screen.getByRole("group", { name: "Chat list actions" }));
    const extra = options.getByText("More search options", { selector: "summary" });
    if (!extra.closest("details")?.open) fireEvent.click(extra);
    fireEvent.click(options.getByRole("button", { name }));
  }
}

