test("celebrates a visible birthday only on its local calendar day and refreshes at midnight", async () => {
  vi.useFakeTimers();
  try {
    vi.setSystemTime(new Date(2028, 1, 28, 23, 59, 59));
    const birthday = { day: 29, month: 2, year: 0 };
    const load = vi.fn(async () => ({ usernames: ["fixture_contact"], bio: null, birthdate: birthday }));
    render(<ContactProfile id="54" load={load} />);
    await act(async () => fireEvent.click(screen.getByRole("button", { name: "Contact profile" })));
    expect(screen.getByText("Birthday")).toBeTruthy();
    expect(screen.queryByText("Birthday today")).toBeNull();
    act(() => vi.advanceTimersByTime(1000));
    expect(screen.getByText("Birthday today")).toBeTruthy();
    act(() => vi.advanceTimersByTime(24 * 60 * 60 * 1000));
    expect(screen.queryByText("Birthday today")).toBeNull();
    expect(load).toHaveBeenCalledExactlyOnceWith("54");
  } finally { vi.useRealTimers(); }
});

