test("clears media cache for the chat whose details are open", async () => {
  const clearChatCache = vi.fn().mockRejectedValueOnce(new Error("fixture failure")).mockResolvedValueOnce({ cleanupDeferred: true }).mockResolvedValueOnce({});
  const chat = { id: "-42", name: "Fixture cache chat", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] };
  const { container } = render(<TelegramPage live={{
    chats: [chat], folders: [], list: "main", loading: false, error: "", liveRevision: 0, selectList: () => {}, refresh: () => {},
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(), clearChatCache,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture cache chat/ }));
  const detailsDialog = container.querySelector<HTMLDialogElement>('dialog[aria-label="Chat details"]')!;
  detailsDialog.showModal = () => { detailsDialog.open = true; };
  fireEvent.click(screen.getByRole("button", { name: "Chat details" }));
  expect(clearChatCache).not.toHaveBeenCalled();
  const section = within(detailsDialog).getByText("Media cache").closest("details")!;
  section.open = true;
  const clear = within(detailsDialog).getByRole("button", { name: "Clear media cache for this chat" });
  fireEvent.click(clear);
  await within(detailsDialog).findByRole("alert");
  fireEvent.click(clear);
  await within(detailsDialog).findByText("Retry cache cleanup after the active media transfer finishes.");
  fireEvent.click(clear);
  await within(detailsDialog).findByText("Media cache cleanup finished for this chat.");
  expect(clearChatCache.mock.calls).toEqual([["-42"], ["-42"], ["-42"]]);
});

