test("moves focus between search results with plain arrow keys without opening a chat", async () => {
  const chats = ["First result", "Second result"].map((name, index) => ({
    id: String(42 + index), name, initials: "FX", color: "#246dbd", subtitle: "Group", messages: [],
  }));
  const loadHistory = vi.fn(async () => ({ messages: [], before: null }));
  render(<TelegramPage live={{
    chats, folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false,
    liveRevision: 0, error: "", findChats: async () => chats, sendText: vi.fn(), loadHistory,
  }} />);
  const search = screen.getByRole("searchbox", { name: "Search Telegram chats" });
  search.focus();
  fireEvent.change(search, { target: { value: "result" } });
  fireEvent.keyDown(search, { key: "ArrowDown", shiftKey: true });
  expect(document.activeElement).toBe(search);
  const first = await screen.findByRole("button", { name: /First result/ });
  const second = screen.getByRole("button", { name: /Second result/ });
  fireEvent.keyDown(search, { key: "ArrowDown" });
  expect(document.activeElement).toBe(first);
  fireEvent.keyDown(first, { key: "ArrowDown" });
  expect(document.activeElement).toBe(second);
  fireEvent.keyDown(second, { key: "Escape" });
  expect(document.activeElement).toBe(search);
  fireEvent.keyDown(search, { key: "ArrowDown" });
  fireEvent.keyDown(first, { key: "ArrowUp" });
  expect(document.activeElement).toBe(search);
  fireEvent.keyDown(search, { key: "ArrowDown" });
  fireEvent.keyDown(first, { key: "End" });
  expect(document.activeElement).toBe(second);
  fireEvent.keyDown(second, { key: "Home" });
  expect(document.activeElement).toBe(first);
  expect(loadHistory).not.toHaveBeenCalled();
  expect((search as HTMLInputElement).value).toBe("result");
});

