test("adds a dragged chat to the exact nested folder and ignores a drag from outside the plugin", async () => {
  const setMembership = vi.fn(async () => true);
  const selectList = vi.fn();
  const refresh = vi.fn();
  render(<TelegramPage live={{
    chats: [{ id: "-42", name: "Drag fixture", initials: "DF", color: "#246dbd", subtitle: "Group", messages: [] }],
    folders: [{ id: 7, title: "Work" }, { id: 8, title: "Work.Deep" }], list: 7, selectList, refresh,
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [], before: null }),
    folderActions: { limit: async () => 10, load: vi.fn(), save: vi.fn(), remove: vi.fn(), memberships: vi.fn(), setMembership },
  }} />);
  const types: string[] = ["application/x-makosh-telegram-chat"];
  const dataTransfer = { types, setData: vi.fn(), effectAllowed: "none", dropEffect: "none" };
  const nested = screen.getByRole("button", { name: "Work.Deep" });
  fireEvent.drop(nested, { dataTransfer });
  expect(setMembership).not.toHaveBeenCalled();
  const row = screen.getByRole("button", { name: /Drag fixture/ });
  fireEvent.dragStart(row, { dataTransfer });
  expect(dataTransfer.setData).toHaveBeenCalledExactlyOnceWith(types[0], "chat");
  expect(fireEvent.dragOver(screen.getByRole("button", { name: "Work" }), { dataTransfer })).toBe(true);
  expect(fireEvent.dragOver(nested, { dataTransfer })).toBe(false);
  expect(nested.getAttribute("data-drop-target")).toBe("true");
  fireEvent.drop(nested, { dataTransfer });
  await screen.findByText("Chat added to Work.Deep.");
  expect(setMembership).toHaveBeenCalledExactlyOnceWith(8, "-42", "include");
  expect(selectList).not.toHaveBeenCalled();
  expect(refresh).toHaveBeenCalledTimes(1);
  expect(nested.hasAttribute("data-drop-target")).toBe(false);
});

test("opens an existing folder directly from its chat list", async () => {
  const revision = "1".repeat(64);
  const changedRevision = "2".repeat(64);
  const load = vi.fn()
    .mockResolvedValueOnce({ title: "Work.Deep", rules: [], shareable: false, revision })
    .mockResolvedValueOnce({ title: "Work.Remote", rules: ["include_groups"], shareable: false, revision: changedRevision })
    .mockResolvedValueOnce({ title: "Work.Next", rules: ["include_groups"], shareable: false, revision: "3".repeat(64) });
  const save = vi.fn().mockResolvedValueOnce(null).mockResolvedValueOnce({ id: 7, title: "Work.Next" });
  const { container } = render(<TelegramPage live={{
    chats: [], folders: [{ id: 7, title: "Work.Deep" }], list: 7, selectList: vi.fn(), refresh: vi.fn(),
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [], before: null }),
    folderActions: { limit: async () => 10, load, save, remove: vi.fn(), memberships: vi.fn(), setMembership: vi.fn() },
  }} />);
  const dialog = container.querySelector<HTMLDialogElement>('dialog[aria-label="Manage folders"]')!;
  dialog.showModal = () => { dialog.open = true; };
  dialog.close = () => { dialog.open = false; };
  expect(load).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Chat list actions" }));
  fireEvent.click(screen.getByRole("button", { name: "Edit this folder" }));
  const editor = within(screen.getByRole("dialog", { name: "Manage folders" }));
  const title = editor.getByRole<HTMLInputElement>("textbox", { name: "Name" });
  await waitFor(() => expect(title.value).toBe("Work.Deep"));
  expect(editor.getByRole("option", { name: "Work / Deep" })).toBeTruthy();
  expect(title.getAttribute("aria-describedby")).toBe(editor.getByText("Work / Deep", { selector: "bdi" }).parentElement?.id);
  expect(load).toHaveBeenCalledExactlyOnceWith(7);
  fireEvent.change(title, { target: { value: "Ops.Next" } });
  expect(editor.getByText("Ops / Next", { selector: "bdi" })).toBeTruthy();
  fireEvent.click(editor.getByRole("button", { name: "Save folder" }));
  await editor.findByText("Folder settings changed in Telegram. Reload the folder before saving.");
  expect(title.value).toBe("Ops.Next");
  expect(editor.getByRole<HTMLButtonElement>("button", { name: "Save folder" }).disabled).toBe(true);
  expect(save).toHaveBeenCalledExactlyOnceWith({ title: "Ops.Next", rules: [] }, 7, revision);
  fireEvent.click(editor.getByRole("button", { name: "Reload folder" }));
  await waitFor(() => expect(title.value).toBe("Work.Remote"));
  fireEvent.change(title, { target: { value: "Work.Next" } });
  fireEvent.click(editor.getByRole("button", { name: "Save folder" }));
  await editor.findByText("Folder saved.");
  expect(save).toHaveBeenLastCalledWith({ title: "Work.Next", rules: ["include_groups"] }, 7, changedRevision);
  fireEvent.click(editor.getByRole("button", { name: "Done" }));
  fireEvent.click(screen.getByRole("button", { name: "Manage folders" }));
  expect(editor.getByRole<HTMLSelectElement>("combobox", { name: "Folder" }).value).toBe("");
  expect(load).toHaveBeenCalledTimes(3);
  await waitFor(() => expect(editor.getByRole("textbox", { name: "Name" })).toBeTruthy());
});

test("restores each chat list's scroll position once the selected folder loads", async () => {
  const live = {
    chats: [{ id: "41", name: "Fixture chat", initials: "FC", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [{ id: 7, title: "Work" }], list: "main" as const,
    selectList: vi.fn(), refresh: () => {}, loading: false, liveRevision: 0, error: "",
    findChats: async () => [], sendText: vi.fn(),
    loadHistory: async () => ({ messages: [], before: null }),
  };
  const view = render(<TelegramPage live={live} />);
  const rows = screen.getByRole("list", { name: "Telegram chats" });
  Object.defineProperties(rows, {
    clientHeight: { value: 300 },
    scrollHeight: { value: 900, configurable: true },
  });
  rows.scrollTop = 480;
  fireEvent.scroll(rows);
  view.rerender(<TelegramPage live={{ ...live, list: 7 }} />);
  expect(rows.scrollTop).toBe(0);
  rows.scrollTop = 160;
  fireEvent.scroll(rows);

  const loadMore = vi.fn(async () => {});
  view.rerender(<TelegramPage live={{ ...live, loading: true, loadMore }} />);
  rows.scrollTop = 0;
  fireEvent.scroll(rows);
  Object.defineProperty(rows, "scrollHeight", { value: 500 });
  view.rerender(<TelegramPage live={{ ...live, loadMore }} />);
  expect(loadMore).toHaveBeenCalledOnce();
  expect(rows.scrollTop).toBe(0);
  Object.defineProperty(rows, "scrollHeight", { value: 900 });
  view.rerender(<TelegramPage live={{ ...live, loadMore, loadingMore: true }} />);
  expect(rows.scrollTop).toBe(480);

  view.rerender(<TelegramPage live={{ ...live, list: 7 }} />);
  expect(rows.scrollTop).toBe(160);

  const chat = within(rows).getByRole("button", { name: /Fixture chat/ });
  fireEvent.click(chat);
  await waitFor(() => expect(document.activeElement).toBe(screen.getByRole("heading", { name: "Fixture chat" })));
  rows.scrollTop = 0;
  const back = screen.getByRole("button", { name: "Back to chats" });
  back.focus();
  fireEvent.click(back);
  expect(rows.scrollTop).toBe(160);
  await waitFor(() => expect(document.activeElement).toBe(chat));
});

