  const share = entry === "message" ? `tg://msg_url?${parameters}` : `https://telegram.me/share/url/?${parameters}`;
  const source = { id: "41", name: "Source share fixture", initials: "S", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const target = { ...source, id: "42", name: "Target share fixture" };
  const draft = { text: "Original draft", styles: [{ offset: 0, length: 8, style: "bold" as const }] };
  const sendText = vi.fn();
  const saveChatDraft = vi.fn();
  render(<TelegramPage live={{
    chats: [source, target], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory: async (id) => id === source.id ? { before: null, messages: [{
      id: "7", text: "Share fixture", links: [{ offset: 0, length: 13, url: share }], author: "Fixture", time: "",
    }] } : { before: null, messages: [], draft },
    findChats: async () => [], sendText, saveChatDraft,
  }} />);
  if (entry === "message") {
    fireEvent.click(screen.getByRole("button", { name: /Source share fixture/ }));
    fireEvent.click(await screen.findByRole("link", { name: "Share fixture" }));
  } else {
    fireEvent.paste(screen.getByRole("searchbox", { name: "Search Telegram chats" }),
      { clipboardData: { getData: () => share } });
  }
