test.each([
  { entry: "message", rhash: "9b0f9464359e82" },
  { entry: "paste", rhash: "" },
])("opens a direct Instant View link from $entry and links to its original", async ({ entry, rhash }) => {
  const url = "https://example.com/fixture?q=one";
  const params = new URLSearchParams({ url });
  if (rhash) params.set("rhash", rhash);
  const link = `https://t.me/iv?${params}`;
  const chat = { id: "41", name: "Instant View fixture", initials: "I", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const loadInstantView = vi.fn().mockResolvedValue(rhash ? null : {
    partial: false, rtl: false, blocks: [{ kind: "title", text: "Fixture article" }],
  });
  const showModal = Object.getOwnPropertyDescriptor(HTMLDialogElement.prototype, "showModal");
  Object.defineProperty(HTMLDialogElement.prototype, "showModal",
    { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    render(<TelegramPage live={{
      chats: [chat], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      loadHistory: async () => ({ before: null, messages: [{
        id: "7", text: "Article", links: [{ offset: 0, length: 7, url: link }], author: "Fixture", time: "",
      }] }),
      loadInstantView, findChats: async () => [], sendText: vi.fn(),
    }} />);
    expect(loadInstantView).not.toHaveBeenCalled();
    if (entry === "message") {
      fireEvent.click(screen.getByRole("button", { name: /Instant View fixture/ }));
      fireEvent.click(await screen.findByRole("link", { name: "Article" }));
    } else {
      fireEvent.paste(screen.getByRole("searchbox", { name: "Search Telegram chats" }),
        { clipboardData: { getData: () => link } });
    }
    expect(await screen.findByRole("dialog", { name: "Instant View" })).toBeTruthy();
    expect(await screen.findByText(rhash ? /Instant View is unavailable/i : "Fixture article")).toBeTruthy();
    expect(loadInstantView).toHaveBeenCalledExactlyOnceWith(rhash ? link : url);
    expect(screen.getByRole<HTMLAnchorElement>("link", { name: "Open original" }).href).toBe(url);
  } finally {
    if (showModal) Object.defineProperty(HTMLDialogElement.prototype, "showModal", showModal);
    else Reflect.deleteProperty(HTMLDialogElement.prototype, "showModal");
  }
});

test("validates direct Instant View URLs before opening their original page", async () => {
  const { telegramInstantViewLink } = await import("../src/core/telegram-content-link.ts");
  const original = "https://example.org/section?q=1";
  const address = encodeURIComponent(original);
  expect(telegramInstantViewLink(`http://telegram.me/iv/?url=${address}&rhash=face#details`)).toEqual({
    link: `https://t.me/iv?url=${address}&rhash=face#details`,
    lookup: `https://t.me/iv?url=${address}&rhash=face#details`,
    source: original + "#details",
  });
  expect(telegramInstantViewLink(`https://t.me.evil.example/iv?url=${address}`)).toBeUndefined();
  expect(telegramInstantViewLink(`https://t.me/iv?url=${address}&url=${address}`)).toBeUndefined();
  expect(telegramInstantViewLink("https://t.me/iv?url=javascript%3Aalert%281%29")).toBeUndefined();
  expect(telegramInstantViewLink("https://t.me/iv?url=https%3A%2F%2Fexample.org%40example.net")).toBeUndefined();
});

test("keeps an Instant View article after its message leaves and the panel remounts on resize", async () => {
  const url = "https://example.com/source";
  const next = "https://example.com/next";
  const source = { id: "41", name: "Article source fixture", initials: "AS", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const loadHistory = vi.fn(async () => ({ before: null, messages: [{
    id: "7", text: "", author: "Fixture", time: "", linkPreview: {
      url, site: "Fixture", title: "First article", description: "", above: false, instantView: true as const,
    },
  }] }));
  const loadInstantView = vi.fn(async (address: string): Promise<InstantViewArticle> => ({
    rtl: false, partial: false, blocks: address === url
      ? [{ kind: "paragraph", text: "Next article", links: [{ offset: 0, length: 12, url: next, instantView: true }] }]
      : [{ kind: "heading", text: "Second article" }],
  }));
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const close = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(prototype, "close", { configurable: true, value(this: HTMLDialogElement) {
    this.open = false;
    fireEvent(this, new Event("close"));
  } });
  vi.stubGlobal("innerWidth", 480);
  try {
    const panel = (key: string, scope: string) => <TelegramPage key={key} connectionScope={scope} live={{
      chats: [source], folders: [], list: "main", selectList: () => {}, refresh: () => {},
      loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(), loadHistory, loadInstantView,
    }} />;
    const { rerender } = render(panel("compact", "fixture-account"));
    fireEvent.click(screen.getByRole("button", { name: /Article source fixture/ }));
    const opener = await screen.findByRole("button", { name: "Instant View" });
    fireEvent.click(opener);
    fireEvent.click(await screen.findByRole("link", { name: "Next article" }));
    await screen.findByRole("heading", { name: "Second article" });
    const article = screen.getByRole("dialog", { name: "Instant View" });
    fireEvent.change(within(article).getByRole("combobox", { name: "Zoom" }), { target: { value: "150" } });
    const back = screen.getByRole("button", { name: "Back to chats" });
    fireEvent.click(back);
    expect(opener.isConnected).toBe(false);
    expect(screen.getByRole("dialog", { name: "Instant View" })).toBe(article);
    article.scrollTop = 44;
    fireEvent.scroll(article);
    vi.stubGlobal("innerWidth", 1360);
    rerender(panel("wide", "fixture-account"));
    const resumed = await screen.findByRole("dialog", { name: "Instant View" });
    expect(resumed.scrollTop).toBe(44);
    expect(within(resumed).getByRole<HTMLSelectElement>("combobox", { name: "Zoom" }).value).toBe("150");
    expect(within(resumed).getByRole("heading", { name: "Second article" })).toBeTruthy();
    fireEvent.click(within(resumed).getByRole("button", { name: "Back to article" }));
    expect(within(resumed).getByRole("link", { name: "Next article" })).toBeTruthy();
    expect(loadInstantView.mock.calls).toEqual([[url], [next]]);
    vi.stubGlobal("innerWidth", 480);
    rerender(panel("other-account", "another-account"));
    expect(screen.queryByRole("dialog", { name: "Instant View" })).toBeNull();
    rerender(panel("original-account", "fixture-account"));
    const original = await screen.findByRole("dialog", { name: "Instant View" });
    fireEvent.click(within(original).getByRole("button", { name: "Close Instant View" }));
    rerender(panel("closed", "fixture-account"));
    expect(screen.queryByRole("dialog", { name: "Instant View" })).toBeNull();
  } finally {
    vi.unstubAllGlobals();
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (close) Object.defineProperty(prototype, "close", close);
    else Reflect.deleteProperty(prototype, "close");
  }
});

