test("reviews a conflicting forum draft within its exact topic before adopting it", async () => {
  const { TopicDraftSync } = await import("../src/ui/topic-draft-sync.tsx");
  const original = { text: "Original forum fixture" };
  const latest = { text: "New forum fixture" };
  const local = { text: "Local forum fixture" };
  const load = vi.fn().mockResolvedValueOnce({ draft: original, writable: true }).mockResolvedValueOnce({ draft: latest, writable: true });
  const save = vi.fn(async () => "changed" as const);
  const useDraft = vi.fn();
  render(<TopicDraftSync chatId="-42" topicId={17} draft={local} edited busy={false}
    load={load} save={save} useDraft={useDraft} />);
  fireEvent.click(await findComposerAction("Save draft to Telegram"));
  const review = await findComposerAction("Review newer Telegram draft");
  expect(save).toHaveBeenCalledExactlyOnceWith("-42", local, original, 17);
  expect(screen.queryByRole("button", { name: "Save draft to Telegram" })).toBeNull();
  expect(useDraft).not.toHaveBeenCalled();
  fireEvent.click(review);
  expect(await screen.findByText(latest.text)).toBeTruthy();
  expect(load.mock.calls).toEqual([["-42", 17], ["-42", 17]]);
  fireEvent.click(screen.getByRole("button", { name: "Use latest Telegram draft" }));
  expect(useDraft).toHaveBeenCalledExactlyOnceWith(latest);
  expect(save).toHaveBeenCalledTimes(1);
});

test("requires reviewing a changed Telegram draft before retrying a local save", async () => {
  const oldDraft = { text: "Earlier Telegram fixture" };
  const latestDraft = { text: "Newer Telegram fixture" };
  const saveChatDraft = vi.fn().mockResolvedValueOnce("changed").mockResolvedValueOnce("saved");
  const loadChatDraft = vi.fn(async () => ({ draft: latestDraft, writable: true }));
  const sendText = vi.fn();
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Draft fixture chat", initials: "DF", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory: async () => ({ messages: [], before: null, draft: oldDraft }), findChats: async () => [],
    sendText, saveChatDraft, loadChatDraft,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Draft fixture chat/ }));
  await findComposerAction("Use Telegram draft");
  const composer = screen.getByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement;
  fireEvent.change(composer, { target: { value: "Unsynced local fixture" } });
  fireEvent.click(getComposerAction("Save draft to Telegram"));
  const review = await findComposerAction("Review newer Telegram draft");
  expect((getComposerAction("Save draft to Telegram") as HTMLButtonElement).disabled).toBe(true);
  expect(loadChatDraft).not.toHaveBeenCalled();
  fireEvent.click(review);
  await screen.findByText(latestDraft.text);
  expect(composer.value).toBe("Unsynced local fixture");
  expect(saveChatDraft).toHaveBeenCalledTimes(1);
  fireEvent.click(getComposerAction("Save draft to Telegram"));
  await screen.findByText("Draft saved to Telegram.");
  expect(saveChatDraft).toHaveBeenNthCalledWith(1, "42", expect.objectContaining({ text: "Unsynced local fixture" }), oldDraft);
  expect(saveChatDraft).toHaveBeenNthCalledWith(2, "42", expect.objectContaining({ text: "Unsynced local fixture" }), latestDraft);
  expect(sendText).not.toHaveBeenCalled();
});

