  const devices = screen.getByText("Active devices").parentElement as HTMLDetailsElement;
  devices.open = true;
  fireEvent(devices, new Event("toggle"));
  const inactivity = screen.getByText("Inactive sessions").parentElement as HTMLDetailsElement;
