async function selectDownloadFixtures(queue: (chatId: string, messageId: string) => Promise<boolean>) {
  const chats = ["42", "43"].map((id) => ({
    id, name: `Chat ${id}`, subtitle: "Direct message", initials: "FX", color: "#246dbd", messages: [],
  }));
  const messages = ["11", "12", "13"].map((id) => ({
    id, text: "", author: "Fixture", time: "", document: { name: `${id}.bin`, downloadable: id !== "13" },
  }));
  render(<QueueDownloadAction.Provider value={queue}><TelegramPage live={{
    chats, folders: [], list: "main", selectList: () => {}, refresh: () => {},
    loading: false, liveRevision: 0, error: "", findChats: async () => [], sendText: vi.fn(),
    loadHistory: async (id) => ({ messages: id === "42" ? messages : [], before: null }),
  }} /></QueueDownloadAction.Provider>);
  fireEvent.click(screen.getByRole("button", { name: /Chat 42/ }));
  await startFixtureChatSelection();
  const boxes = within(screen.getByRole("list", { name: "Messages" })).getAllByRole("checkbox", { name: "Select message" });
  expect(boxes).toHaveLength(3);
  for (const box of boxes) fireEvent.click(box);
}

test("queues selected attachments, excludes restricted files, and retries only a failed item", async () => {
  const queue = vi.fn(async (_chatId: string, _messageId: string) => true)
    .mockResolvedValueOnce(true).mockRejectedValueOnce(new Error("Fixture failure"));
  await selectDownloadFixtures(queue);
  expect(queue).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Queue 2 attachments" }));
  await screen.findByText("1 added to downloads. 1 could not be added.");
  expect(queue.mock.calls).toEqual([["42", "11"], ["42", "12"]]);
  fireEvent.click(screen.getByRole("button", { name: "Queue 1 attachment" }));
  await screen.findByText("1 added to downloads.");
  expect(queue.mock.calls).toEqual([["42", "11"], ["42", "12"], ["42", "12"]]);
  expect(screen.queryByRole("button", { name: "Queue 1 attachment" })).toBeNull();
});

test("stops queueing selected attachments when the user changes chats", async () => {
  let finish!: (result: boolean) => void;
  const pending = new Promise<boolean>((resolve) => { finish = resolve; });
  const queue = vi.fn(() => pending);
  await selectDownloadFixtures(queue);
  fireEvent.click(screen.getByRole("button", { name: "Queue 2 attachments" }));
  expect(queue).toHaveBeenCalledExactlyOnceWith("42", "11");
  fireEvent.click(screen.getByRole("button", { name: /Chat 43/ }));
  await act(async () => { finish(true); await pending; });
  expect(queue).toHaveBeenCalledExactlyOnceWith("42", "11");
  expect(screen.queryByText("1 added to downloads.")).toBeNull();
});

