  render(<StickerPackLibrary actions={{ installed: async () => [], archived: async () => ({ packs: [], next: null }),
    change: async () => "unavailable", owned: { list: async () => ({ packs: [pack], next: null }),
      load, move, preview: async () => null } }} onChanged={() => {}} />);
