test.each(["Grid", "List"] as const)("continues shared photos and restores the %s opener after message context", async (layout) => {
  const { ConversationSearch } = await import("../src/ui/conversation-search.tsx");
  const photo = (id: string, photoCaption: string) => ({ id, text: "", author: "Fixture", time: "",
    hasPhoto: true, canSavePhoto: true as const, photoCaption, photoDimensions: { width: 320, height: 240 } });
  const first = photo("24", "First shared photo");
  const older = photo("23", "Older shared photo");
  const search = vi.fn()
    .mockResolvedValueOnce({ before: "24", messages: [first] })
    .mockRejectedValueOnce(new Error("Fixture connection error"))
    .mockResolvedValueOnce({ before: null, messages: [first, older] });
  const loadContext = vi.fn(async () => [older, first]);
  const loadPhoto = vi.fn(async () => ({ mime: "image/png" as const, base64: "AA==" }));
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const close = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperties(prototype, {
    showModal: { configurable: true, value(this: HTMLDialogElement) { this.open = true; } },
    close: { configurable: true, value(this: HTMLDialogElement) { this.open = false; this.dispatchEvent(new Event("close")); } },
  });
  try {
    render(<ConversationSearch chatId="-42" topicId={15} initialFilter="photoVideo" search={search}
      loadContext={loadContext} loadPhoto={loadPhoto} close={() => {}} />);
    await screen.findByRole("group", { name: "Media layout" });
    fireEvent.click(screen.getByRole("button", { name: layout }));
    const region = screen.getByRole("region", { name: "Topic search" });
    fireEvent.click(await screen.findByRole("button", { name: "Show photo" }));
    fireEvent.click(await screen.findByRole("button", { name: "Enlarge Telegram photo" }));
    const viewer = within(screen.getByRole("dialog", { name: "Telegram photo viewer" }));
    expect(search).toHaveBeenCalledExactlyOnceWith("-42", "", "photoVideo", 15);
    fireEvent.click(viewer.getByRole("button", { name: "Load more photos" }));
    await viewer.findByText("Could not load more photos.");
    fireEvent.click(viewer.getByRole("button", { name: "Retry loading more photos" }));
    await viewer.findByText("1 / 2");
    expect(viewer.getByText(first.photoCaption)).toBeTruthy();
    fireEvent.click(viewer.getByRole("button", { name: "Next photo" }));
    await viewer.findByText("2 / 2");
    expect(viewer.getByText(older.photoCaption)).toBeTruthy();
    region.scrollTop = 138;
    fireEvent.click(viewer.getByRole("button", { name: "Go to photo message" }));

    const context = await screen.findByRole("list", { name: "Nearby messages" });
    expect(loadContext).toHaveBeenCalledExactlyOnceWith("-42", "23", 15);
    expect(document.activeElement).toBe(context.querySelector('[aria-current="true"]'));
    fireEvent.click(screen.getByRole("button", { name: "Back to results" }));
    const results = screen.getByRole("list", { name: layout === "Grid" ? "Media gallery" : "Matching messages" });
    expect(within(results).getByText(older.photoCaption)).toBeTruthy();
    const originalRow = within(results).getByText(first.photoCaption).closest("li")!;
    expect(document.activeElement).toBe(within(originalRow).getByRole("button", { name: "Show photo" }));
    expect(region.scrollTop).toBe(138);
    expect(search.mock.calls.slice(1)).toEqual([["-42", "", "photoVideo", 15, "24"], ["-42", "", "photoVideo", 15, "24"]]);
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (close) Object.defineProperty(prototype, "close", close);
    else Reflect.deleteProperty(prototype, "close");
  }
});

