test("continues shared audio after leaving the gallery and requests older pages only at the queue edge", async () => {
  const { PlaybackHistoryProvider } = await import("../src/ui/media-player.tsx");
  const { MusicPlaybackProvider, MusicPlayerPanel } = await import("../src/ui/music-playback.tsx");
  const message = (id: string, downloadable = true) => ({
    id, author: "Fixture", time: "", text: "", forumTopicId: 7,
    document: { name: `${id}.mp3`, downloadable, playbackMime: "audio/mpeg" as const },
  });
  let attempts = 0;
  type AudioPage = { before: string | null; messages: ReturnType<typeof message>[] };
  const pendingPages = new Map<string, (page: AudioPage) => void>();
  const search = vi.fn(async (_chat: string, _query: string, _filter?: string, _topic?: number, before?: string) => {
    if (before === "18" && !attempts++) throw new Error("Temporary search failure");
    if (before === "18") return { before: "17", messages: [message("20"), message("18", false)] };
    if (before === "17") return { before: "16", messages: [message("17")] };
    if (before === "16" || before === "15") return new Promise<AudioPage>((resolve) => { pendingPages.set(before, resolve); });
    return { before: "18", messages: [message("20"), message("19")] };
  });
  const load = vi.fn(async () => new Blob());
  const stream = vi.fn(async (_chat: string, messageId: string) => `/fixture/${messageId}`);
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockImplementation(function (this: HTMLMediaElement) {
    fireEvent.play(this);
    return Promise.resolve();
  });
  const pause = vi.spyOn(HTMLMediaElement.prototype, "pause").mockImplementation(function (this: HTMLMediaElement) { fireEvent.pause(this); });
  try {
    const page = (open: boolean) => <PlaybackHistoryProvider><MusicPlaybackProvider>
      <MusicPlayerPanel />
      {open && <ConversationSearch chatId="-42" topicId={7} initialFilter="audio" search={search} loadMedia={load}
        loadVideoStream={stream} close={() => {}} />}
    </MusicPlaybackProvider></PlaybackHistoryProvider>;
    const view = render(page(true));
    const [first] = await screen.findAllByRole("button", { name: "Play audio" });
    expect(stream).not.toHaveBeenCalled();
    fireEvent.click(first!);
    const player = within(screen.getByRole("region", { name: "Telegram music player" }));
    async function playing(id: string) {
      await waitFor(() => expect(player.getByLabelText("Telegram audio").getAttribute("src")).toBe(`/fixture/${id}`));
      const audio = player.getByLabelText<HTMLAudioElement>("Telegram audio");
      await waitFor(() => expect(play.mock.instances).toContain(audio));
      return audio;
    }
    function finish(audio: HTMLAudioElement) {
      Object.defineProperty(audio, "ended", { value: true });
      fireEvent.ended(audio);
    }
    const firstTrack = await playing("20");
    view.rerender(page(false));
    finish(firstTrack);
    const edgeTrack = await playing("19");
    expect(search.mock.calls).toEqual([["-42", "", "audio", 7]]);
    finish(edgeTrack);
    await player.findByText("Could not find the next track. Use Next track to retry.");
    fireEvent.click(player.getByRole("button", { name: "Next track" }));
    const nextTrack = await playing("17");
    expect(search.mock.calls).toEqual([
      ["-42", "", "audio", 7], ["-42", "", "audio", 7, "18", undefined, undefined],
      ["-42", "", "audio", 7, "18", undefined, undefined], ["-42", "", "audio", 7, "17", undefined, undefined],
    ]);
    expect(stream.mock.calls).toEqual([["-42", "20"], ["-42", "19"], ["-42", "17"]]);
    const summary = player.getByText("Queue", { selector: "summary" });
    const details = summary.closest("details")!;
    details.open = true;
    fireEvent(details, new Event("toggle"));
    const openQueue = within(await player.findByRole("list", { name: "Music queue" }));
    expect(openQueue.getByRole("button", { name: "17.mp3", current: true })).toBeTruthy();
    fireEvent.click(player.getByRole("button", { name: "Load older tracks" }));
    await player.findByText("Loading older tracks…");
    expect(player.getByLabelText("Telegram audio")).toBe(nextTrack);
    expect(stream).toHaveBeenCalledTimes(3);
    finish(nextTrack);
    expect(search.mock.calls.filter(([, , , , cursor]) => cursor === "16")).toHaveLength(1);
    expect(pendingPages.has("16")).toBe(true);
    await act(async () => { pendingPages.get("16")?.({ before: "15", messages: [message("16")] }); });
    const fourthTrack = await playing("16");
    expect(openQueue.getByRole("button", { name: "16.mp3", current: true })).toBeTruthy();
    finish(fourthTrack);
    await player.findByText("Finding the next track…");
    fireEvent.click(player.getByRole("button", { name: "Close player" }));
    expect(pendingPages.has("15")).toBe(true);
    await act(async () => { pendingPages.get("15")?.({ before: null, messages: [message("15")] }); });
    expect(screen.queryByRole("region", { name: "Telegram music player" })).toBeNull();
    expect(stream).toHaveBeenCalledTimes(4);
    view.unmount();
  } finally {
    play.mockRestore();
    pause.mockRestore();
  }
});

