test("centers the exact message when opening context without scrolling the BB page", async () => {
  const { ConversationSearch } = await import("../src/ui/conversation-search.tsx");
  const message = { id: "20", text: "Context fixture", author: "Fixture", time: "" };
  let finish!: (messages: typeof message[]) => void;
  const context = new Promise<typeof message[]>((resolve) => { finish = resolve; });
  render(<ConversationSearch chatId="-42" initialMessage="20" loadContext={() => context} close={() => {}} />);
  const panel = screen.getByRole("region", { name: "Message context" });
  Object.defineProperty(panel, "clientHeight", { value: 200 });
  const getRect = vi.spyOn(HTMLElement.prototype, "getBoundingClientRect").mockImplementation(function (this: HTMLElement) {
    if (this === panel) return new DOMRect(0, 70, 200, 200);
    if (this.dataset.contextId === "20") return new DOMRect(0, 470 - panel.scrollTop, 200, 40);
    return new DOMRect();
  });
  try {
    finish([message]);
    await screen.findByText("Context fixture");
    expect(panel.scrollTop).toBe(320);
    expect(panel.querySelector('[aria-current="true"]')?.getAttribute("data-context-id")).toBe("20");
    expect(document.documentElement.scrollTop).toBe(0);
  } finally {
    getRect.mockRestore();
  }
});

