test("refreshes edited context rows without reloading either page or shifting the selected message", async () => {
  const { HistoryMessageUpdates } = await import("../src/ui/history-message-updates.ts");
  const row = (id: string, text: string) => ({ id, text, time: "", author: "Fixture", forumTopicId: 17 });
  const loadContext = vi.fn(async () => [row("20", "Context target")]);
  const loadContextPage = vi.fn(async () => [row("19", "Earlier context")]);
  const load = vi.fn(async (_id: string, id: string) => row(id, id === "19" ? "Edited earlier context" : "Edited context target"));
  const signals = new Set<(event: { id: string; messageId: string }) => void>();
  render(<HistoryMessageUpdates.Provider value={{ load, subscribe(listener) {
    signals.add(listener);
    return () => { signals.delete(listener); };
  } }}>
    <ConversationSearch chatId="-42" topicId={17} initialMessage="20" loadContext={loadContext}
      loadContextPage={loadContextPage} close={vi.fn()} />
  </HistoryMessageUpdates.Provider>);
  const target = (await screen.findByText("Context target")).closest("[data-context-id]");
  fireEvent.click(screen.getByRole("button", { name: "Load earlier messages" }));
  await screen.findByText("Earlier context");
  act(() => {
    for (const notify of signals) {
      notify({ id: "-42", messageId: "18" });
      notify({ id: "-43", messageId: "20" });
      notify({ id: "-42", messageId: "19" });
      notify({ id: "-42", messageId: "20" });
    }
  });
  expect((await screen.findByText("Edited context target")).closest("[data-context-id]")).toBe(target);
  expect(target?.getAttribute("aria-current")).toBe("true");
  await screen.findByText("Edited earlier context");
  expect(load.mock.calls).toEqual([["-42", "19", 17], ["-42", "20", 17]]);
  expect(loadContext).toHaveBeenCalledOnce();
  expect(loadContextPage).toHaveBeenCalledExactlyOnceWith("-42", "20", "older", 17);
});

test("checks edited search results against Telegram and keeps other loaded pages", async () => {
  const { HistoryMessageUpdates } = await import("../src/ui/history-message-updates.ts");
  const row = (id: string, text: string) => ({ id, text, time: "", author: "Fixture", forumTopicId: 17 });
  const search = vi.fn().mockResolvedValueOnce({ messages: [row("50", "First match"), row("30", "Second match")], before: "30" })
    .mockResolvedValueOnce({ messages: [row("20", "Older match")], before: null })
    .mockResolvedValueOnce({ messages: [row("30", "Second match"), row("20", "Older match")], before: "20" });
  const load = vi.fn();
  const signals = new Set<(event: { id: string; messageId: string }) => void>();
  render(<HistoryMessageUpdates.Provider value={{ load, subscribe(listener) {
    signals.add(listener);
    return () => { signals.delete(listener); };
  } }}>
    <ConversationSearch chatId="-42" topicId={17} search={search} close={vi.fn()} />
  </HistoryMessageUpdates.Provider>);
  fireEvent.change(screen.getByRole("searchbox"), { target: { value: "match" } });
  fireEvent.click(screen.getByRole("button", { name: "Find" }));
  const result = await screen.findByRole("list", { name: "Matching messages" });
  expect(result.querySelector('[data-message-id="50"]')).toBeTruthy();
  fireEvent.click(screen.getByRole("button", { name: "Load more matches" }));
  await waitFor(() => expect(result.querySelector('[data-message-id="20"]')).toBeTruthy());
  const older = result.querySelector('[data-message-id="20"]');
  act(() => {
    for (const notify of signals) {
      notify({ id: "-43", messageId: "50" });
      notify({ id: "-42", messageId: "49" });
      notify({ id: "-42", messageId: "50" });
    }
  });
  await waitFor(() => expect(result.querySelector('[data-message-id="50"]')).toBeNull());
  expect(result.querySelectorAll('[data-message-id="20"]')).toHaveLength(1);
  expect(result.querySelector('[data-message-id="20"]')).toBe(older);
  expect(search.mock.calls).toEqual([["-42", "match", undefined, 17],
    ["-42", "match", undefined, 17, "30"], ["-42", "match", undefined, 17]]);
  expect(load).not.toHaveBeenCalled();
});

