test("pastes safe clipboard formatting and links at the selected UTF-16 offsets", async () => {
  const sendText = vi.fn(async () => ({ state: "sent" as const, message: { id: "12", author: "You", text: "Pasted fixture", time: "" } }));
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Clipboard fixture", initials: "CF", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: vi.fn(), refresh: vi.fn(), loading: false, liveRevision: 0, error: "",
    findChats: async () => [], sendText, loadHistory: async () => ({ before: null, messages: [] }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Clipboard fixture/ }));
  const editor = screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" });
  fireEvent.change(editor, { target: { value: "🙂 old" } });
  editor.setSelectionRange(3, 6);
  const clipboard = (plain: string, html: string) => ({ files: [], getData: (type: string) => type === "text/html" ? html : plain });
  expect(fireEvent.paste(editor, { clipboardData: clipboard("safe", "<strong>another word</strong>") })).toBe(true);
  expect(editor.value).toBe("🙂 old");
  const html = '<strong>Bold</strong> <a href="https://example.com/reference">link</a> <a href="javascript:alert(1)">unsafe</a><script>bad</script>';
  expect(fireEvent.paste(editor, { clipboardData: clipboard("Bold link unsafe", html) })).toBe(false);
  expect(editor.value).toBe("🙂 Bold link unsafe");
  const preview = screen.getByLabelText("Formatted message preview");
  expect(preview.querySelector(".mtg-text-bold")?.textContent).toBe("Bold");
  expect(within(preview).getAllByRole("button").map((item) => item.textContent)).toEqual(["link"]);
  expect(preview.textContent).not.toContain("bad");
  fireEvent.click(screen.getByRole("button", { name: "Send message" }));
  await waitFor(() => expect(sendText).toHaveBeenCalledExactlyOnceWith("42", "🙂 Bold link unsafe", undefined, {
    styles: [{ offset: 3, length: 4, style: "bold" }],
    links: [{ offset: 8, length: 4, url: "https://example.com/reference" }],
  }));
});

