test("sends inline results and polls with the source of a restored reply", async () => {
  const source = { id: "42", name: "Fixture inline source", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const destination = { ...source, id: "43", name: "Fixture inline destination", subtitle: "Group" };
  const message = { id: "24", author: "Fixture sender", text: "Original fixture", time: "" };
  const search = vi.fn(async () => ({ next: null, results: [{ token: "fixture-token", title: "Fixture result", kind: "Article", description: "" }] }));
  const sendInline = vi.fn(async () => ({ state: "failed" as const }));
  const sendPoll = vi.fn(async () => ({ state: "sent" as const, message: { ...message, id: "25" } }));
  const sendText = vi.fn();
  render(<TelegramPage live={{
    chats: [source, destination], folders: [], list: "main", selectList: () => {}, refresh: () => {},
    loading: false, error: "", liveRevision: 0, findChats: async () => [], sendText, sendPoll,
    postingPermissions: async () => ({ text: true, photo: true, document: true, poll: true, otherMedia: true }),
    inlineBotActions: { search, send: sendInline }, externalReplyAllowed: async () => true,
    loadHistory: async (id) => ({ before: null, messages: id === source.id ? [message] : [] }),
  }} />);
  const shortcut = { key: "s", code: "KeyS", ctrlKey: true };
  fireEvent.click(screen.getByRole("button", { name: /Fixture inline source/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Reply to message" }));
  const composer = await screen.findByRole("textbox", { name: "Write a message" });
  fireEvent.change(composer, { target: { value: "@FixtureBot fixture" } });
  fireEvent.keyDown(composer, shortcut);
  fireEvent.click(screen.getByRole("button", { name: /Fixture inline destination/ }));
  fireEvent.keyDown(await screen.findByRole("textbox", { name: "Write a message" }), shortcut);
  await screen.findByText("Replying to Fixture sender in another conversation");
  fireEvent.click(screen.getByRole("button", { name: "Search @FixtureBot" }));
  const result = await screen.findByRole("button", { name: /Fixture result/ });
  expect(sendInline).not.toHaveBeenCalled();
  fireEvent.click(result);
  const reply = { messageId: "24", externalReplyChatId: "42" };
  await waitFor(() => expect(sendInline).toHaveBeenCalledExactlyOnceWith("43", "fixture-token", undefined, reply));
  await screen.findByText(/Could not send that bot result/);

  fireEvent.click(getComposerAction("Create poll"));
  const poll = { question: "Fixture question", options: ["First", "Second"], multiple: false };
  for (const [label, value] of [["Question", poll.question], ["Option 1", "First"], ["Option 2", "Second"]]) {
    fireEvent.change(screen.getByRole("textbox", { name: label }), { target: { value } });
  }
  expect(sendPoll).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Publish poll" }));
  await waitFor(() => expect(sendPoll).toHaveBeenCalledExactlyOnceWith("43", poll, undefined, reply));
  await waitFor(() => expect(screen.queryByRole("button", { name: "Cancel reply" })).toBeNull());
  expect(sendText).not.toHaveBeenCalled();
});

test("changes the selected scheduled row without using the current draft", async () => {
  const { ScheduledMessages } = await import("../src/ui/scheduled-messages.tsx");
  const date = new Date(2037, 0, 2, 12, 30);
  const row = { id: "22", text: "Scheduled fixture", at: Math.floor(date.getTime() / 1000) - 3600 };
  let rows = [row];
  const load = vi.fn(async () => rows);
  const change = vi.fn(async (_id: string, expected: Omit<typeof row, "at"> & { at?: number }, at: number | null) => {
    rows = at === null ? [] : [{ ...expected, at }];
    return "updated" as const;
  });
  const send = vi.fn();
  render(<ScheduledMessages chatId="42" liveRevision={0} draft="" canSend={false} load={load} change={change}
    send={send} cancel={vi.fn()} accepted={vi.fn()} />);
  fireEvent.click(getComposerAction("Send options"));
  const list = await screen.findByRole("list", { name: "Scheduled messages" });
  fireEvent.click(within(list).getByRole("button", { name: "Reschedule" }));
  fireEvent.input(within(list).getByLabelText("New send time"), { target: { value: "2037-01-02T12:30" } });
  fireEvent.click(within(list).getByRole("button", { name: "Save new send time" }));
  await screen.findByText("Schedule updated.");
  const next = Math.floor(date.getTime() / 1000);
  fireEvent.click(within(list).getByRole("button", { name: "Send now" }));
  await screen.findByText("No scheduled messages.");
  expect(change.mock.calls).toEqual([["42", row, next], ["42", { ...row, at: next }, null]]);
  expect(send).not.toHaveBeenCalled();
});

