test("pages and searches within the chosen nested folder before explicitly forwarding", async () => {
  const { MessageForward } = await import("../src/ui/message-forward.tsx");
  const first = { id: "41", name: "First folder recipient", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const second = { ...first, id: "42", name: "Second folder recipient" };
  const outside = { ...first, id: "43", name: "Outside folder recipient" };
  const page = vi.fn(async (_id: number, offset: number) => offset === 0
    ? { chats: [first], nextOffset: 40 } : { chats: [first, second], nextOffset: null });
  const search = vi.fn(async () => [second]);
  const searchRecipients = vi.fn(async () => [outside]);
  const forwardMessage = vi.fn(async () => "sent" as const);
  render(<MessageForward chatId="9" messageId="22" actions={{
    recipients: [outside], searchRecipients,
    folders: { items: [{ id: 8, title: "Team" }, { id: 9, title: "Team.Project" }], page, search },
    forwardOptions: async () => true, forwardMessage,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: "Forward message" }));
  const folder = await screen.findByRole("combobox", { name: "Recipient folder" });
  const target = screen.getByRole<HTMLSelectElement>("combobox", { name: "Forward to" });
  fireEvent.change(target, { target: { value: "43" } });
  expect(page).not.toHaveBeenCalled();
  expect(within(folder).getByRole("option", { name: "Team / Project" })).toBeTruthy();
  fireEvent.change(folder, { target: { value: "9" } });
  await within(target).findByRole("option", { name: /First folder recipient/ });
  expect(target.value).toBe("");
  expect(within(target).queryByRole("option", { name: /Outside folder recipient/ })).toBeNull();
  fireEvent.change(target, { target: { value: "41" } });
  fireEvent.click(screen.getByRole("button", { name: "Load more chats in folder" }));
  await within(target).findByRole("option", { name: /Second folder recipient/ });
  expect(target.value).toBe("41");
  expect(within(target).getAllByRole("option", { name: /First folder recipient/ })).toHaveLength(1);
  expect(page.mock.calls).toEqual([[9, 0], [9, 40]]);
  fireEvent.change(screen.getByRole("searchbox", { name: "Find recipient" }), { target: { value: "Second" } });
  fireEvent.click(screen.getByRole("button", { name: "Find chats" }));
  await waitFor(() => expect(within(target).queryByRole("option", { name: /First folder recipient/ })).toBeNull());
  expect(search).toHaveBeenCalledExactlyOnceWith(9, "Second");
  expect(searchRecipients).not.toHaveBeenCalled();
  fireEvent.change(target, { target: { value: "42" } });
  expect(forwardMessage).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Forward" }));
  await screen.findByText("Message forwarded.");
  expect(forwardMessage).toHaveBeenCalledExactlyOnceWith("9", "22", {
    id: "42", name: "Second folder recipient", kind: "Direct message",
  });
});

