  const reactFromCatalog = vi.fn(async () => true);
  const interactions = vi.fn()
    .mockResolvedValueOnce({ rows: [{ key: "before", name: "Original viewer", date: 1700000000, kind: "view" }], next: "before" })
    .mockResolvedValueOnce({ rows: [{ key: "filtered", name: "Filtered viewer", date: 1700000001, kind: "reaction", customEmoji: choice.id }], next: "filtered" })
    .mockResolvedValueOnce({ rows: [{ key: "next", name: "Next viewer", date: 1700000002, kind: "forward" }], next: null });
  const { container } = render(<Stories actions={{
    feed: async () => ({ groups: [{ id, title: "Fixture author", stories: [{ id: 8, unread: true }] }], more: false }),
    view, viewing: async () => true, reactionCatalog, reactFromCatalog, interactions,
  }} />);
