test("opens the exact shared story or reply reference from the conversation", async () => {
  const view = vi.fn(async () => ({ kind: "photo" as const, caption: "", url: "/api/v1/plugins/fixture" }));
  const resolveLink = vi.fn(async () => ({ id: "42", story: 9, title: "Fixture author" }));
  const viewing = vi.fn(async () => true);
  const dialog = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(dialog, "showModal");
  const close = Object.getOwnPropertyDescriptor(dialog, "close");
  Object.defineProperty(dialog, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  Object.defineProperty(dialog, "close", { configurable: true, value(this: HTMLDialogElement) { this.open = false; } });
  try {
    render(<TelegramPage live={{
      chats: [{ id: "42", name: "Fixture chat", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] }],
      folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
      sendText: vi.fn(), findChats: async () => [], storyActions: { resolveLink, view, viewing, feed: async () => ({ groups: [], more: false }) },
      loadHistory: async () => ({ before: null, messages: [
        { id: "1", text: "Story", time: "", author: "Fixture", sharedStory: { id: "-57", story: 6 } },
        { id: "2", text: "Fixture reply", time: "", author: "Fixture", replyToStory: { id: "42", story: 8 } },
        { id: "3", text: "Fixture story link", time: "", author: "Fixture",
          links: [{ offset: 0, length: 18, url: "tg://resolve?story=9&domain=Fixture" }] },
      ] }),
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Fixture chat/ }));
    const shared = await screen.findByRole("button", { name: "Shared story" });
    expect(view).not.toHaveBeenCalled();
    fireEvent.click(shared);
    fireEvent.load(await screen.findByRole("img", { name: "Telegram story photo" }));
    await waitFor(() => expect(viewing).toHaveBeenCalledExactlyOnceWith("-57", 6, true));
    fireEvent.click(screen.getByRole("button", { name: "Close story" }));
    fireEvent.click(screen.getByRole("button", { name: "Reply to a story" }));
    await screen.findByRole("img", { name: "Telegram story photo" });
    expect(view.mock.calls).toEqual([["-57", 6], ["42", 8]]);
    expect(screen.getByText("Fixture reply")).toBeTruthy();
    fireEvent.click(screen.getByRole("button", { name: "Close story" }));
    expect(resolveLink).not.toHaveBeenCalled();
    expect(fireEvent.click(screen.getByRole("link", { name: "Fixture story link" }))).toBe(false);
    await screen.findByRole("img", { name: "Telegram story photo" });
    expect(resolveLink).toHaveBeenCalledExactlyOnceWith("https://t.me/fixture/s/9");
    expect(view).toHaveBeenLastCalledWith("42", 9);
  } finally {
    if (showModal) Object.defineProperty(dialog, "showModal", showModal);
    else Reflect.deleteProperty(dialog, "showModal");
    if (close) Object.defineProperty(dialog, "close", close);
    else Reflect.deleteProperty(dialog, "close");
  }
});

