  fireEvent.click(album.getAllByRole("button", { name: /^Move story from .* up$/ })[1]!);
  await waitFor(() => {
    const stories = album.getAllByRole("button", { name: /^Story ·/ });
    expect(stories[0]?.textContent).toContain(new Date(row(11).date * 1000).toLocaleString());
  });
