test("opens published profile stories only on request and reuses the story viewer", async () => {
  const { ProfileStories } = await import("../src/ui/stories.tsx");
  const profile = vi.fn()
    .mockResolvedValueOnce({ stories: [{ id: 2, date: 1700000000, pinned: true }], before: 19 })
    .mockResolvedValueOnce({ stories: [{ id: 1, date: 1690000000, pinned: false }], before: null });
  const view = vi.fn(async () => ({ kind: "photo" as const, caption: "", url: "/api/v1/plugins/fixture" }));
  const viewing = vi.fn(async () => true);
  render(<ProfileStories id="42" actions={{ profile, view, viewing, feed: async () => ({ groups: [], more: false }) }} />);
  expect(profile).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Show profile stories" }));
  const pinned = await screen.findByRole("button", { name: /^Pinned story/ });
  fireEvent.click(pinned);
  const photo = await screen.findByRole("img", { name: "Telegram story photo" });
  expect(view).toHaveBeenCalledExactlyOnceWith("42", 2);
  expect(viewing).not.toHaveBeenCalled();
  fireEvent.load(photo);
  await waitFor(() => expect(viewing).toHaveBeenCalledExactlyOnceWith("42", 2, true));
  const next = screen.getByRole<HTMLButtonElement>("button", { name: "Next story" });
  expect(next.disabled).toBe(true);
  fireEvent.click(screen.getByRole("button", { name: "Load earlier profile stories" }));
  await waitFor(() => expect(next.disabled).toBe(false));
  expect(profile.mock.calls).toEqual([["42", undefined], ["42", 19]]);
  const viewer = screen.getByRole("region", { name: "Profile stories" });
  expect(document.activeElement).toBe(viewer);
  fireEvent.keyDown(viewer, { key: "ArrowRight" });
  await waitFor(() => expect(view).toHaveBeenLastCalledWith("42", 1));
  await waitFor(() => expect(viewing).toHaveBeenLastCalledWith("42", 2, false));
  fireEvent.click(screen.getByRole("button", { name: "Previous story" }));
  await waitFor(() => expect(view).toHaveBeenLastCalledWith("42", 2));
  fireEvent.click(screen.getByRole("button", { name: "Back to profile stories" }));
  expect(screen.getAllByRole("listitem")).toHaveLength(2);
});

