test("updates an open community and ignores superseded updates", async () => {
  const { CommunityBrowser } = await import("../src/ui/community-browser.tsx");
  const previous = { id: "7", name: "Original community" };
  const latest = { id: "7", name: "Updated community" };
  let finishStale!: (rows: typeof previous[]) => void;
  const pending = new Promise<typeof previous[]>((resolve) => { finishStale = resolve; });
  const list = vi.fn().mockResolvedValueOnce([previous]).mockReturnValueOnce(pending)
    .mockResolvedValueOnce([latest]).mockResolvedValueOnce([]);
  const member = (id: string, title: string) => ({ id, title, canView: true, hidden: false });
  const chats = vi.fn().mockResolvedValue([]).mockResolvedValueOnce([member("-42", "Original group")])
    .mockResolvedValueOnce([member("-43", "Superseded group")]).mockResolvedValueOnce([member("-44", "Updated group")]);
  const actions = { list, chats };
  const loadChat = async () => null;
  const openChat = vi.fn();
  const view = (changeRevision: number) => <CommunityBrowser actions={actions} loadChat={loadChat}
    openChat={openChat} changeRevision={changeRevision} />;
  const { container, rerender } = render(view(0));
  const dialog = container.querySelector("dialog")!;
  dialog.showModal = () => { dialog.open = true; };
  fireEvent.click(screen.getByRole("button", { name: "Communities" }));
  fireEvent.click(await screen.findByRole("button", { name: previous.name }));
  await screen.findByRole("button", { name: "Original group" });
  rerender(view(1));
  await waitFor(() => expect(list).toHaveBeenCalledTimes(2));
  expect(screen.getByRole("button", { name: "Original group" })).toBeTruthy();
  rerender(view(2));
  await screen.findByRole("button", { name: "Updated group" });
  expect(screen.getByRole("heading", { name: latest.name })).toBeTruthy();
  await act(async () => finishStale([previous]));
  expect(screen.queryByRole("button", { name: "Superseded group" })).toBeNull();
  rerender(view(3));
  await screen.findByText("No joined communities.");
  expect(screen.queryByRole("button", { name: "Updated group" })).toBeNull();
  expect(dialog.open).toBe(true);
});

