test("reconciles both chats when read acknowledgements overlap during navigation", async () => {
  const first = { id: "42", name: "Fixture first chat", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [], unread: 1 };
  const second = { ...first, id: "43", name: "Fixture second chat" };
  const observers = new Map<Element, IntersectionObserverCallback>();
  class Observer {
    constructor(private callback: IntersectionObserverCallback) {}
    observe(row: Element) { observers.set(row, this.callback); }
    disconnect() {}
  }
  vi.stubGlobal("IntersectionObserver", Observer);
  const visibility = vi.spyOn(document, "visibilityState", "get").mockReturnValue("visible");
  let acknowledgeFirst!: (ok: boolean) => void;
  const firstReceipt = new Promise<boolean>((resolve) => { acknowledgeFirst = resolve; });
  const markHistoryRead = vi.fn((id: string) => id === first.id ? firstReceipt : Promise.resolve(true));
  const loadNotificationChat = vi.fn(async (id: string) => ({ ...(id === first.id ? first : second), unread: 0 }));
  const syncChatReadState = vi.fn();
  try {
    render(<TelegramPage live={{
      chats: [first, second], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0,
      error: "", findChats: async () => [], sendText: vi.fn(), markHistoryRead, loadNotificationChat, syncChatReadState,
      loadHistory: async (id) => ({ before: null, readInbox: 49, unreadCount: 1, messages: [
        { id: "50", author: "Fixture", time: "", text: `Fixture message ${id}` },
      ] }),
    }} />);
    async function reveal(id: string) {
      const row = (await screen.findByText(`Fixture message ${id}`)).closest("li")!;
      const rect = row.getBoundingClientRect();
      await act(async () => observers.get(row)!([{ target: row, isIntersecting: true, intersectionRatio: 1,
        boundingClientRect: rect, intersectionRect: rect, rootBounds: null, time: 0 }], {} as IntersectionObserver));
    }
    fireEvent.click(screen.getByRole("button", { name: /Fixture first chat/ }));
    await reveal(first.id);
    await waitFor(() => expect(markHistoryRead).toHaveBeenCalledExactlyOnceWith(first.id, "50", undefined, undefined));
    fireEvent.click(screen.getByRole("button", { name: /Fixture second chat/ }));
    await reveal(second.id);
    await waitFor(() => expect(syncChatReadState).toHaveBeenCalledExactlyOnceWith({ ...second, unread: 0 }));
    await act(async () => { acknowledgeFirst(true); await firstReceipt; });
    expect(syncChatReadState.mock.calls).toEqual([[{ ...second, unread: 0 }], [{ ...first, unread: 0 }]]);
  } finally {
    visibility.mockRestore();
    vi.unstubAllGlobals();
  }
});

