test.each([false, true])("jumps directly from the read boundary to the actual latest history (forum topic %s)", async (forum) => {
  const id = forum ? "-42" : "42";
  const chat = { id, name: "Jump boundary fixture", initials: "J", color: "#246dbd",
    subtitle: forum ? "Group" : "Direct message", messages: [], unread: 20 };
  const message = (id: string, text: string) => ({ id, text, author: "Fixture", time: "" });
  const latest = { messages: [message("90", "Latest fixture")], before: "90" };
  let finishIntermediate!: (page: { messages: ReturnType<typeof message>[]; before: null; after: string }) => void;
  const intermediate = new Promise<Parameters<typeof finishIntermediate>[0]>((resolve) => { finishIntermediate = resolve; });
  const loadLatest = vi.fn().mockRejectedValueOnce(new Error("Temporary fixture failure")).mockResolvedValueOnce(latest);
  const loadUnreadHistory = vi.fn(async (_id: string, after?: string, topic?: number) => {
    if (forum && topic !== 17) return null;
    if (after) return intermediate;
    return { messages: [message("50", "Read boundary fixture"), message("51", "First unread fixture")],
      before: "50", after: "51", openAt: "50", readInbox: 50 };
  });
  render(<TelegramPage live={{
    chats: [chat], folders: [], list: "main", selectList: vi.fn(), refresh: vi.fn(), loading: false, error: "", liveRevision: 0,
    findChats: async () => [], sendText: vi.fn(), loadUnreadHistory,
    loadHistory: forum ? async () => ({ before: null, messages: [] }) : loadLatest,
    ...forum && { loadForumTopics: async () => [{ id: 17, name: "Jump boundary topic", closed: false }], loadTopicHistory: loadLatest },
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Jump boundary fixture/ }));
  if (forum) {
    fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
    fireEvent.click(await screen.findByRole("button", { name: "Jump boundary topic" }));
  }
  const list = screen.getByRole("list", { name: forum ? "Topic messages" : "Messages" });
  await within(list).findByText("First unread fixture");
  const initialTop = list.scrollTop;
  const jumpLabel = forum ? "Jump to latest topic message" : "Jump to latest";
  fireEvent.click(screen.getByRole("button", { name: jumpLabel }));
  const retry = await screen.findByRole("button", { name: new RegExp(`Retry ${jumpLabel}`, "i") });
  expect(list.scrollTop).toBe(initialTop);
  expect(within(list).getByText("Read boundary fixture")).toBeTruthy();
  fireEvent.click(within(list).getByRole("button", { name: /Load newer/ }));
  fireEvent.click(retry);
  await within(list).findByText("Latest fixture");
  await act(async () => finishIntermediate({ messages: [message("52", "Stale intermediate fixture")], before: null, after: "52" }));
  expect(within(list).queryByText("Stale intermediate fixture")).toBeNull();
  expect(within(list).queryByText("Read boundary fixture")).toBeNull();
  expect(loadLatest.mock.calls).toEqual(forum ? [[id, 17], [id, 17]] : [[id], [id]]);
  expect(loadUnreadHistory.mock.calls.filter(([, after]) => after)).toEqual(forum ? [[id, "51", 17]] : [[id, "51"]]);
});

