test("plays only eligible tracks in the current audio album and publishes track metadata", async () => {
  const { PlaybackHistoryProvider } = await import("../src/ui/media-player.tsx");
  const { MessageAlbum } = await import("../src/ui/message-album.tsx");
  const { MessageContent } = await import("../src/ui/message-content.tsx");
  const { NotePlaybackQueueProvider } = await import("../src/ui/note-playback-queue.tsx");
  const stream = vi.fn(async (_id: string, messageId: string) => `/fixture/${messageId}`);
  const load = vi.fn(async () => new Blob());
  const session = { metadata: null as object | null, playbackState: "none", setActionHandler: vi.fn() };
  const descriptor = Object.getOwnPropertyDescriptor(navigator, "mediaSession");
  Object.defineProperty(navigator, "mediaSession", { configurable: true, value: session });
  vi.stubGlobal("MediaMetadata", class { constructor(value: object) { Object.assign(this, value); } });
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockImplementation(function (this: HTMLMediaElement) {
    fireEvent.play(this);
    return Promise.resolve();
  });
  const pause = vi.spyOn(HTMLMediaElement.prototype, "pause").mockImplementation(function (this: HTMLMediaElement) { fireEvent.pause(this); });
  const track = (id: string, title: string, albumId: string, downloadable = true) => ({
    id, author: "Fixture", time: "", text: "", albumId, document: {
      name: `${id}.mp3`, downloadable, playbackMime: "audio/mpeg" as const, audioTrack: { title, artist: "Fixture artist" },
    },
  });
  const album = [track("8", "First track", "10"), track("9", "Unavailable", "10", false), track("10", "Second track", "10")];
  const other = [track("11", "Other first track", "11"), track("12", "Other second track", "11")];
  const body = (rows: typeof album) => <MessageAlbum chatId="42" first={rows[0]!} messages={rows} caption={undefined}>
    {rows.map((message) => <li key={message.id} aria-label={message.document.audioTrack.title}>
      <MessageContent chatId="42" message={message} loadMedia={load} loadVideoStream={stream} />
    </li>)}
  </MessageAlbum>;
  try {
    const page = (rows: typeof album) => <PlaybackHistoryProvider><NotePlaybackQueueProvider messages={[]} enabled>
      <ol>{body(rows)}{body(other)}</ol>
    </NotePlaybackQueueProvider></PlaybackHistoryProvider>;
    const view = render(page(album));
    const [firstAlbum, otherAlbum] = screen.getAllByRole("list", { name: "Audio album" });
    const first = within(firstAlbum!);
    const otherRows = within(otherAlbum!);
    const starts = first.getAllByRole("button", { name: "Load audio player" });
    expect(starts).toHaveLength(2);
    fireEvent.click(starts[0]!);
    const firstAudio = await first.findByLabelText<HTMLAudioElement>("Telegram audio");
    fireEvent.play(firstAudio);
    expect(session.metadata).toMatchObject({ title: "First track", artist: "Fixture artist" });
    view.rerender(page([album[0]!, album[1]!, track("10", "Second track", "10", false)]));
    expect(first.getByLabelText("Telegram audio")).toBe(firstAudio);
    expect(first.queryByRole("button", { name: "Next track" })).toBeNull();
    view.rerender(page(album));
    expect(first.getByLabelText("Telegram audio")).toBe(firstAudio);
    fireEvent.pause(firstAudio);
    expect(stream).toHaveBeenCalledExactlyOnceWith("42", "8");
    fireEvent.play(firstAudio);
    Object.defineProperty(firstAudio, "ended", { value: true, configurable: true });
    fireEvent.ended(firstAudio);
    await waitFor(() => expect(first.queryAllByLabelText("Telegram audio")).toHaveLength(2));
    const secondAudio = first.getAllByLabelText<HTMLAudioElement>("Telegram audio")[1]!;
    await waitFor(() => expect(session.metadata).toMatchObject({ title: "Second track" }));
    expect(stream.mock.calls).toEqual([["42", "8"], ["42", "10"]]);
    expect(otherRows.queryByLabelText("Telegram audio")).toBeNull();
    Object.defineProperty(secondAudio, "ended", { value: true });
    fireEvent.ended(secondAudio);
    expect(first.getAllByRole("button", { name: "Next track" })[1]).toHaveProperty("disabled", true);
    expect(stream).toHaveBeenCalledTimes(2);
    expect(session.metadata).toBeNull();
    view.unmount();
  } finally {
    play.mockRestore();
    pause.mockRestore();
    vi.unstubAllGlobals();
    if (descriptor) Object.defineProperty(navigator, "mediaSession", descriptor);
    else Reflect.deleteProperty(navigator, "mediaSession");
  }
});

test("shuffles the current music queue and repeats tracks or the album without replacing active audio", async () => {
  const { PlaybackHistoryProvider } = await import("../src/ui/media-player.tsx");
  const { MessageAlbum } = await import("../src/ui/message-album.tsx");
  const { MessageContent } = await import("../src/ui/message-content.tsx");
  const { MusicPlaybackProvider, MusicPlayerPanel } = await import("../src/ui/music-playback.tsx");
  const load = vi.fn(async () => new Blob());
  const stream = vi.fn(async (_chatId: string, messageId: string) => `/fixture/${messageId}`);
  const tracks = ["8", "9", "10", "11"].map((id) => ({
    id, author: "Fixture", time: "", text: "", albumId: "10", document: {
      name: `${id}.mp3`, downloadable: id !== "11", playbackMime: "audio/mpeg" as const,
    },
  }));
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockImplementation(function (this: HTMLMediaElement) {
    fireEvent.play(this);
    return Promise.resolve();
  });
  const pause = vi.spyOn(HTMLMediaElement.prototype, "pause").mockImplementation(function (this: HTMLMediaElement) { fireEvent.pause(this); });
  const random = vi.spyOn(Math, "random").mockReturnValue(0);
  try {
    const view = render(<PlaybackHistoryProvider><MusicPlaybackProvider>
      <MusicPlayerPanel />
      <MessageAlbum chatId="42" first={tracks[0]!} messages={tracks} caption={undefined}>
        {tracks.map((message) => <li key={message.id}>
          <MessageContent chatId="42" message={message} loadMedia={load} loadVideoStream={stream} />
        </li>)}
      </MessageAlbum>
    </MusicPlaybackProvider></PlaybackHistoryProvider>);
    fireEvent.click(screen.getAllByRole("button", { name: "Play audio" })[0]!);
    const player = within(screen.getByRole("region", { name: "Telegram music player" }));
    async function playing(id: string) {
      await waitFor(() => expect(player.getByLabelText("Telegram audio").getAttribute("src")).toBe(`/fixture/${id}`));
      const audio = player.getByLabelText<HTMLAudioElement>("Telegram audio");
      await waitFor(() => expect(play.mock.instances).toContain(audio));
      return audio;
    }
    const first = await playing("8");
    const shuffle = player.getByRole("button", { name: "Shuffle" });
    const repeat = player.getByRole("combobox", { name: "Repeat" });
    fireEvent.click(shuffle);
    expect(shuffle.getAttribute("aria-pressed")).toBe("true");
    fireEvent.change(repeat, { target: { value: "track" } });
    expect(first.loop).toBe(true);
    expect(player.getByLabelText("Telegram audio")).toBe(first);
    expect(stream).toHaveBeenCalledExactlyOnceWith("42", "8");
    fireEvent.change(repeat, { target: { value: "album" } });
    expect(first.loop).toBe(false);
    const summary = player.getByText("Queue", { selector: "summary" });
    const details = summary.closest("details")!;
    details.open = true;
    fireEvent(details, new Event("toggle"));
    const list = within(await player.findByRole("list", { name: "Music queue" }));
    expect(list.getAllByRole("button").map((button) => button.textContent)).toEqual(["8.mp3", "10.mp3", "9.mp3"]);
    const jump = list.getByRole("button", { name: "10.mp3" });
    jump.focus();
    fireEvent.click(jump);
    await playing("10");
    expect(list.getByRole("button", { name: "10.mp3", current: true })).toBe(jump);
    expect(document.activeElement).toBe(jump);
    fireEvent.keyDown(jump, { key: "Escape" });
    expect(details.open).toBe(false);
    expect(document.activeElement).toBe(summary);
    expect(player.getByRole("combobox", { name: "Repeat" })).toBe(repeat);
    fireEvent.click(player.getByRole("button", { name: "Previous track" }));
    await playing("8");
    fireEvent.click(player.getByRole("button", { name: "Previous track" }));
    const last = await playing("9");
    Object.defineProperty(last, "ended", { value: true });
    fireEvent.ended(last);
    await playing("8");
    fireEvent.click(shuffle);
    expect(shuffle.getAttribute("aria-pressed")).toBe("false");
    fireEvent.click(player.getByRole("button", { name: "Next track" }));
    await playing("9");
    expect(stream.mock.calls.map(([, id]) => id)).toEqual(["8", "10", "8", "9", "8", "9"]);
    view.unmount();
  } finally {
    random.mockRestore();
    play.mockRestore();
    pause.mockRestore();
  }
});

