test("routes system media controls to the active note and its current queue", async () => {
  const { MediaPlayer, PlaybackHistoryProvider } = await import("../src/ui/media-player.tsx");
  const { NotePlaybackQueueProvider } = await import("../src/ui/note-playback-queue.tsx");
  const handlers = new Map<MediaSessionAction, MediaSessionActionHandler>();
  const mediaSession = { playbackState: "none", setActionHandler(action: MediaSessionAction, handler: MediaSessionActionHandler | null) {
    if (handler) handlers.set(action, handler);
    else handlers.delete(action);
  } };
  const descriptor = Object.getOwnPropertyDescriptor(navigator, "mediaSession");
  Object.defineProperty(navigator, "mediaSession", { configurable: true, value: mediaSession });
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockImplementation(function (this: HTMLMediaElement) {
    fireEvent.play(this);
    return Promise.resolve();
  });
  const pause = vi.spyOn(HTMLMediaElement.prototype, "pause").mockImplementation(function (this: HTMLMediaElement) { fireEvent.pause(this); });
  const stream = vi.fn(async (_id: string, messageId: string) => `/fixture/${messageId}`);
  const voice = { id: "8", author: "Fixture", time: "", text: "", voiceNote: true as const,
    document: { name: "fixture.ogg", downloadable: true, playbackMime: "audio/ogg" as const } };
  const page = (both: boolean) => <PlaybackHistoryProvider><NotePlaybackQueueProvider enabled messages={both ? [voice, { ...voice, id: "10" }] : [voice]}>
    <section aria-label="First note"><MediaPlayer chatId="42" messageId="8" voiceNote queuePlayback mime="audio/ogg" stream={stream} /></section>
    <section aria-label="Second note"><MediaPlayer chatId="42" messageId="10" voiceNote queuePlayback mime="audio/ogg" stream={stream} /></section>
  </NotePlaybackQueueProvider></PlaybackHistoryProvider>;
  const invoke = (action: MediaSessionAction) => act(() => handlers.get(action)!({ action }));
  try {
    const view = render(page(false));
    const first = within(screen.getByRole("region", { name: "First note" }));
    const second = within(screen.getByRole("region", { name: "Second note" }));
    expect(handlers.size).toBe(0);
    fireEvent.click(first.getByRole("button", { name: "Load audio player" }));
    const firstAudio = await first.findByLabelText<HTMLAudioElement>("Telegram audio");
    fireEvent.play(firstAudio);
    expect(mediaSession.playbackState).toBe("playing");
    expect(handlers.has("nexttrack")).toBe(false);
    invoke("pause");
    expect(pause.mock.instances).toContain(firstAudio);
    expect(mediaSession.playbackState).toBe("paused");
    invoke("play");
    expect(play.mock.instances).toContain(firstAudio);
    expect(mediaSession.playbackState).toBe("playing");
    view.rerender(page(true));
    expect(handlers.has("nexttrack")).toBe(true);
    invoke("nexttrack");
    const secondAudio = await second.findByLabelText<HTMLAudioElement>("Telegram audio");
    await waitFor(() => expect(play.mock.instances).toContain(secondAudio));
    expect(handlers.has("nexttrack")).toBe(false);
    expect(handlers.has("previoustrack")).toBe(true);
    fireEvent.pause(firstAudio);
    expect(mediaSession.playbackState).toBe("playing");
    Object.defineProperty(secondAudio, "readyState", { value: secondAudio.HAVE_METADATA });
    secondAudio.currentTime = 8;
    invoke("stop");
    expect(secondAudio.currentTime).toBe(0);
    expect(mediaSession.playbackState).toBe("none");
    expect(handlers.size).toBe(0);
    fireEvent.play(secondAudio);
    view.unmount();
    expect(handlers.size).toBe(0);
  } finally {
    play.mockRestore();
    pause.mockRestore();
    if (descriptor) Object.defineProperty(navigator, "mediaSession", descriptor);
    else Reflect.deleteProperty(navigator, "mediaSession");
  }
});

test("plays eligible audio tracks in one rich message in order", async () => {
  const { PlaybackHistoryProvider } = await import("../src/ui/media-player.tsx");
  const track = (index: number, fileId: number, downloadable = true) => ({
    kind: "document" as const, media: "audio" as const, spoiler: false, loop: false,
    content: { text: `Track ${fileId}` }, reference: { index, fileId },
    document: { name: `Track ${fileId}.ogg`, playbackMime: "audio/ogg" as const, downloadable },
  });
  const message = (id: string, blocks: Array<ReturnType<typeof track> | { kind: "paragraph"; content: { text: string } }>) => ({
    id, author: "Fixture", time: "", text: "", richMessage: { rtl: false, complete: true, blocks },
  });
  const first = track(0, 57);
  const last = track(2, 59);
  const stream = vi.fn(async (_chat: string, _message: string, attachment?: { fileId: number }) => `/fixture/${attachment?.fileId}`);
  const play = vi.spyOn(HTMLMediaElement.prototype, "play").mockResolvedValue(undefined);
  try {
    render(<PlaybackHistoryProvider>
      <MessageContent chatId="42" message={message("8", [first, { kind: "paragraph", content: { text: "Interlude" } }, track(1, 58, false), last])}
        loadMedia={vi.fn()} loadVideoStream={stream} />
      <MessageContent chatId="42" message={message("9", [track(0, 61), track(1, 62)])}
        loadMedia={vi.fn()} loadVideoStream={stream} />
    </PlaybackHistoryProvider>);
    const article = within(screen.getAllByRole("article", { name: "Rich Telegram message" })[0]!);
    const players = article.getAllByRole("button", { name: "Load audio player" });
    expect(players).toHaveLength(2);
    expect(stream).not.toHaveBeenCalled();
    fireEvent.click(players[0]!);
    const audio = await article.findByLabelText<HTMLAudioElement>("Telegram audio");
    fireEvent.play(audio);
    fireEvent.pause(audio);
    expect(stream).toHaveBeenCalledExactlyOnceWith("42", "8", first.reference);
    fireEvent.play(audio);
    Object.defineProperty(audio, "ended", { value: true });
    fireEvent.ended(audio);
    await waitFor(() => expect(stream).toHaveBeenLastCalledWith("42", "8", last.reference));
    const next = article.getAllByLabelText<HTMLAudioElement>("Telegram audio")[1]!;
    await waitFor(() => expect(play.mock.instances).toEqual([next]));
    const controls = within(next.closest(".mtg-media-player") as HTMLElement);
    expect(controls.getByRole<HTMLButtonElement>("button", { name: "Next track" }).disabled).toBe(true);
    fireEvent.click(controls.getByRole("button", { name: "Previous track" }));
    await waitFor(() => expect(play.mock.instances).toEqual([next, audio]));
    expect(stream.mock.calls).toEqual([["42", "8", first.reference], ["42", "8", last.reference]]);
  } finally { play.mockRestore(); }
});

