test("stashes a mixed album and restores its order, caption and options in a forum topic", async () => {
  const source = { id: "42", name: "Fixture album source", initials: "A", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const forum = { ...source, id: "-42", name: "Fixture album forum", subtitle: "Group" };
  const blocked = { ...forum, id: "-43", name: "Fixture photos only" };
  const topic = { id: 17, name: "Fixture album destination", closed: false };
  const sendAlbum = vi.fn();
  const sendMixedAlbum = vi.fn();
  render(<TelegramPage live={{
    chats: [source, blocked, forum], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
    findChats: async () => [], loadHistory: async () => ({ messages: [], before: null }), sendText: vi.fn(), sendDocument: vi.fn(), sendPhoto: vi.fn(),
    loadForumTopics: async () => [topic], loadTopicHistory: async () => ({ messages: [], before: null }), sendTopicText: vi.fn(),
    postingPermissions: async (id) => ({ text: true, photo: true, document: false, video: id !== blocked.id }),
    mediaComposer: () => ({ choices: async () => [], sendChoice: vi.fn(), sendVoice: vi.fn(), sendAlbum, sendMixedAlbum }),
  }} />);
  const shortcut = { key: "s", code: "KeyS", ctrlKey: true };
  const photo = new File(["fixture"], "first.jpg", { type: "image/jpeg" });
  const video = new File(["fixture"], "second.mp4", { type: "video/mp4" });
  fireEvent.click(screen.getByRole("button", { name: /Fixture album source/ }));
  fireEvent.click(await findComposerAction("Media album"));
  fireEvent.change(screen.getByLabelText("Choose album media"), { target: { files: [photo, video] } });
  fireEvent.click(screen.getByRole("button", { name: "Move video 2 up" }));
  const caption = screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Album caption" });
  fireEvent.change(caption, { target: { value: "Fixture album caption" } });
  caption.setSelectionRange(0, 7);
  fireEvent.keyDown(caption, { key: "b", code: "KeyB", metaKey: true });
  fireEvent.click(screen.getByRole("checkbox", { name: "Hide album media under a spoiler" }));
  fireEvent.click(screen.getByRole("checkbox", { name: "Send without sound" }));
  expect(fireEvent.keyDown(caption, shortcut)).toBe(false);
  expect(screen.queryByRole("list", { name: "Album media order" })).toBeNull();

  fireEvent.click(screen.getByRole("button", { name: /Fixture photos only/ }));
  fireEvent.click(await findComposerAction("Photo album"));
  fireEvent.click(screen.getByRole("button", { name: "Exchange album draft" }));
  expect(screen.getByText("This conversation cannot send the stashed album.")).toBeTruthy();

  fireEvent.click(screen.getByRole("button", { name: /Fixture album forum/ }));
  fireEvent.click(await screen.findByRole("button", { name: "Topics" }));
  fireEvent.click(await screen.findByRole("button", { name: topic.name }));
  const topicDraft = await screen.findByRole<HTMLTextAreaElement>("textbox", { name: "Write a topic message" });
  fireEvent.change(topicDraft, { target: { value: "Local topic draft" } });
  fireEvent.keyDown(topicDraft, shortcut);
  expect(topicDraft.value).toBe("Local topic draft");
  const order = within(screen.getByRole("list", { name: "Album media order" }));
  expect(order.getAllByRole("listitem").map((row) => row.querySelector("bdi")?.textContent)).toEqual([video.name, photo.name]);
  expect(screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Album caption" }).value).toBe("Fixture album caption");
  expect(screen.getByLabelText("Formatted album caption preview").querySelector(".mtg-text-bold")?.textContent).toBe("Fixture");
  expect(screen.getByRole<HTMLInputElement>("checkbox", { name: "Hide album media under a spoiler" }).checked).toBe(true);
  expect(screen.getByRole<HTMLInputElement>("checkbox", { name: "Send without sound" }).checked).toBe(true);
  expect(sendAlbum).not.toHaveBeenCalled();
  expect(sendMixedAlbum).not.toHaveBeenCalled();
});

