test.each([false, true])("retries an album with the chosen effect, online=%s", async (whenOnline) => {
  const { MediaComposer } = await import("../src/ui/media-composer.tsx");
  const photos = await import("../src/ui/prepare-photo.ts");
  const prepare = vi.spyOn(photos, "preparePhoto").mockImplementation(async (file) => file.name);
  const effect = "9007199254740997";
  const sendAlbum = vi.fn().mockResolvedValueOnce("failed").mockResolvedValueOnce("sent");
  const load = vi.fn(async () => [{ id: effect, emoji: "🔥", premium: false, available: true }]);
  try {
    const view = render(<MediaComposer voice={false} otherMedia={false} photos albumEffects={{ chatId: "42", load }}
      scheduleWhenOnline={{ chatId: "42", check: async () => true }} actions={{
      choices: async () => [], sendChoice: async () => "sent", sendVoice: async () => "sent", sendAlbum,
    }} />);
    fireEvent.click(getComposerAction("Photo album"));
    const files = ["one.jpg", "two.jpg"].map((name) => new File(["fixture"], name, { type: "image/jpeg" }));
    fireEvent.change(screen.getByLabelText("Choose album photos"), { target: { files } });
    if (whenOnline) {
      view.container.querySelector("details")!.open = true;
      fireEvent.click(await screen.findByRole("checkbox", { name: "Send media when online" }));
    }
    fireEvent.click(screen.getByRole("button", { name: "Choose album effect" }));
    fireEvent.click(await within(screen.getByRole("group", { name: "Album effects" })).findByRole("button", { name: "🔥 effect" }));
    expect(load).toHaveBeenCalledExactlyOnceWith("42");
    expect(sendAlbum).not.toHaveBeenCalled();
    const action = whenOnline ? "Schedule album" : "Send album";
    const send = screen.getByRole("button", { name: action });
    fireEvent.click(send);
    await waitFor(() => expect(send).toHaveProperty("disabled", false));
    expect(screen.getByRole("button", { name: "Change album effect 🔥" })).toBeTruthy();
    fireEvent.click(send);
    await waitFor(() => expect(screen.queryByRole("button", { name: action })).toBeNull());
    if (whenOnline) await screen.findByText("Scheduled.");
    expect(sendAlbum.mock.calls).toEqual(Array.from({ length: 2 }, () => ["", ["one.jpg", "two.jpg"], {
      effect, ...(whenOnline && { whenOnline: true }),
    }]));
  } finally {
    prepare.mockRestore();
  }
});

