test("removes queued translations for messages that leave view without cancelling started requests", async () => {
  const { createTranslationQueue } = await import("../src/ui/message-translation.tsx");
  const resolved: (() => void)[] = [];
  const translate = vi.fn(() => new Promise<{ text: string }>((resolve) => {
    resolved.push(() => resolve({ text: "Translated fixture" }));
  }));
  const schedule = createTranslationQueue(translate, "42", "es");
  const completed = vi.fn();
  const first = schedule("1", completed);
  schedule("2", completed);
  schedule("3", completed);
  const leftView = schedule("4", completed);
  schedule("5", completed);
  await waitFor(() => expect(translate).toHaveBeenCalledTimes(3));
  expect(first(true)).toBe(false);
  expect(leftView(true)).toBe(true);
  resolved[0]!();
  await waitFor(() => expect(translate).toHaveBeenCalledWith("42", "5", "es"));
  expect(translate).not.toHaveBeenCalledWith("42", "4", "es");
  for (const finish of resolved) finish();
  await waitFor(() => expect(completed).toHaveBeenCalledTimes(4));
});

test("translates only visible eligible messages when chat translation is enabled", async () => {
  const { createAccountDrafts } = await import("../src/ui/local-drafts.ts");
  const draftStorage = createAccountDrafts();
  const observers = new Map<Element, IntersectionObserverCallback>();
  class Observer {
    observed?: Element;
    constructor(private callback: IntersectionObserverCallback) {}
    observe(node: Element) { this.observed = node; observers.set(node, this.callback); }
    disconnect() { if (this.observed) observers.delete(this.observed); }
  }
  vi.stubGlobal("IntersectionObserver", Observer);
  const translateMessage = vi.fn(async () => ({ text: "Translated fixture" }) as { text: string } | null).mockResolvedValueOnce(null);
  try {
    render(<TelegramPage draftStorage={draftStorage} live={{
      chats: [
        { id: "42", name: "Fixture chat", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] },
        { id: "43", name: "Another chat", initials: "A", color: "#246dbd", subtitle: "Direct message", messages: [] },
      ],
      folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, error: "", liveRevision: 0,
      findChats: async () => [], sendText: vi.fn(), translateMessage,
      loadHistory: async () => ({ before: null, messages: [
        { id: "8", time: "", author: "Fixture", text: "Earlier fixture", canTranslate: true },
        { id: "9", time: "", author: "Fixture", text: "Visible fixture", canTranslate: true },
        { id: "10", time: "", author: "Fixture", text: "Unavailable fixture" },
      ] }),
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Fixture chat/ }));
    const row = (await screen.findByText("Visible fixture")).closest("li")!;
    fireEvent.click(openFixtureChatDetails().getByRole("button", { name: "Translate chat" }));
    fireEvent.change(screen.getByRole("combobox", { name: "Chat language" }), { target: { value: "es" } });
    fireEvent.click(screen.getByRole("button", { name: "Done" }));
    expect(translateMessage).not.toHaveBeenCalled();
    expect(observers.has(screen.getByText("Unavailable fixture").closest("li")!)).toBe(false);
    act(() => observers.get(row)!([{ isIntersecting: true } as IntersectionObserverEntry], {} as IntersectionObserver));
    const retry = await screen.findByRole("button", { name: "Retry translation" });
    expect(translateMessage).toHaveBeenCalledExactlyOnceWith("42", "9", "es");
    expect(screen.queryByText("Translated fixture")).toBeNull();
    fireEvent.click(retry);
    expect(await screen.findByText("Translated fixture")).toBeTruthy();
    expect(translateMessage.mock.calls).toEqual([["42", "9", "es"], ["42", "9", "es"]]);
    fireEvent.click(screen.getByRole("button", { name: /Another chat/ }));
    fireEvent.click(openFixtureChatDetails().getByRole("button", { name: "Translate chat" }));
    fireEvent.change(screen.getByRole("combobox", { name: "Chat language" }), { target: { value: "de" } });
    fireEvent.click(screen.getByRole("button", { name: "Done" }));
    fireEvent.click(screen.getByRole("button", { name: /Fixture chat/ }));
    openFixtureChatDetails();
    expect(screen.getByRole<HTMLSelectElement>("combobox", { name: "Chat language" }).value).toBe("es");
    fireEvent.click(screen.getByRole("button", { name: "Show original messages" }));
    expect(screen.queryByText("Translated fixture")).toBeNull();
    expect(await screen.findByText("Visible fixture")).toBeTruthy();
    expect(draftStorage.translation.getSnapshot()).toEqual({
      "42": { language: "es", enabled: false }, "43": { language: "de", enabled: true },
    });
    expect(createAccountDrafts().translation.getSnapshot()).toEqual({});
    fireEvent.click(screen.getByRole("button", { name: "Translate chat" }));
    expect(screen.getByRole<HTMLSelectElement>("combobox", { name: "Chat language" }).value).toBe("es");
  } finally {
    vi.unstubAllGlobals();
  }
});

