test("generates a profile link on request and removes its copy and QR controls after expiry", async () => {
  const url = "https://t.me/contact/Synthetic_Profile";
  const createTemporaryLink = vi.fn(async () => ({ url, expiresIn: 2 }));
  render(<TelegramProfile actions={{ save: vi.fn(), check: vi.fn(), createTemporaryLink, load: async () => ({
    accountId: "42", first: "Fixture", last: "", bio: "", bioLimit: 70, bioEditable: true, username: "", birthdate: null,
  }) }} />);
  const details = screen.getByText("Profile").closest("details")!;
  details.open = true;
  fireEvent(details, new Event("toggle"));
  const generate = await screen.findByRole("button", { name: "Generate temporary profile link" });
  expect(createTemporaryLink).not.toHaveBeenCalled();
  vi.useFakeTimers();
  try {
    await act(async () => { fireEvent.click(generate); });
    expect(createTemporaryLink).toHaveBeenCalledTimes(1);
    expect(screen.getByText("Expires", { exact: false }).querySelector("time")).toBeTruthy();
    expect(screen.getByRole("button", { name: "Copy temporary profile link" })).toBeTruthy();
    const qr = screen.getByLabelText("QR code for temporary profile link").closest("details")!;
    qr.open = true;
    fireEvent(qr, new Event("toggle"));
    expect(screen.getByRole("img", { name: "Temporary Telegram profile link QR code" })).toBeTruthy();
    await act(async () => { await vi.advanceTimersByTimeAsync(2000); });
    expect(screen.getByText("This profile link has expired.")).toBeTruthy();
    expect(screen.queryByRole("button", { name: "Copy temporary profile link" })).toBeNull();
    expect(screen.queryByRole("img", { name: "Temporary Telegram profile link QR code" })).toBeNull();
  } finally {
    vi.useRealTimers();
  }
});

