test("renders a venue map link and ends live sharing as its deadline passes", () => {
  vi.useFakeTimers();
  try {
    const now = 1710000000000;
    vi.setSystemTime(now);
    const message = { id: "9", author: "Fixture", text: "Venue", time: "" };
    const point = { latitude: 10, longitude: -20 };
    const view = render(<MessageContent chatId="42" message={{ ...message, location: {
      ...point, canOpenMap: true, place: { title: "Fixture place", address: "Test address" },
    } }} />);
    expect(screen.getByText("Fixture place")).toBeTruthy();
    expect(screen.getByText("Test address")).toBeTruthy();
    const link = screen.getByRole("link", { name: "Open map" });
    expect(link.getAttribute("href")).toBe("https://www.openstreetmap.org/?mlat=10&mlon=-20#map=16/10/-20");
    expect(link.getAttribute("rel")).toContain("noreferrer");

    view.rerender(<MessageContent chatId="42" message={{ ...message, location: {
      ...point, canOpenMap: false, liveUntil: now / 1000 + 5,
    } }} />);
    expect(screen.queryByRole("link", { name: "Open map" })).toBeNull();
    expect(screen.getByText(/Sharing until/).querySelector("time")?.dateTime).toBe(new Date(now + 5000).toISOString());
    act(() => vi.advanceTimersByTime(5000));
    expect(screen.getByText("Live sharing ended")).toBeTruthy();
  } finally {
    vi.useRealTimers();
  }
});

test("plays, pauses, and seeks focused audio with the keyboard", async () => {
  const { MediaPlayer } = await import("../src/ui/media-player.tsx");
  render(<MediaPlayer chatId="42" messageId="10" mime="audio/mpeg" voiceNote load={async () => new Blob()} />);
  fireEvent.click(screen.getByRole("button", { name: "Load audio player" }));
  const audio = await screen.findByLabelText<HTMLAudioElement>("Telegram audio");
  const play = vi.spyOn(audio, "play").mockResolvedValue(undefined);
  const pause = vi.spyOn(audio, "pause").mockImplementation(() => {});
  Object.defineProperties(audio, { readyState: { value: 1 }, duration: { value: 60 } });
  audio.focus();
  expect(fireEvent.keyDown(audio, { key: " " })).toBe(false);
  expect(play).toHaveBeenCalledTimes(1);
  fireEvent.keyDown(audio, { key: " ", repeat: true });
  expect(play).toHaveBeenCalledTimes(1);
  Object.defineProperty(audio, "paused", { value: false });
  fireEvent.keyDown(audio, { key: " " });
  expect(pause).toHaveBeenCalledTimes(1);
  audio.currentTime = 58;
  fireEvent.keyDown(audio, { key: "ArrowRight" });
  expect(audio.currentTime).toBe(60);
  fireEvent.keyDown(audio, { key: "ArrowLeft" });
  expect(audio.currentTime).toBe(55);
});

