test("holds Space to boost focused video playback without changing the chosen rate", async () => {
  const { MediaPlayer } = await import("../src/ui/media-player.tsx");
  render(<MediaPlayer chatId="42" messageId="9" mime="video/mp4" stream={async () => "/media/fixture"} />);
  fireEvent.click(screen.getByRole("button", { name: "Load video player" }));
  const video = await screen.findByLabelText<HTMLVideoElement>("Telegram video");
  const speed = screen.getByRole<HTMLSelectElement>("combobox", { name: "Playback speed" });
  fireEvent.change(speed, { target: { value: "1.25" } });
  Object.defineProperty(video, "paused", { value: false, configurable: true });
  const pause = vi.spyOn(video, "pause").mockImplementation(() => {});
  const space = { key: " ", code: "Space" };
  vi.useFakeTimers();
  try {
    expect(fireEvent.keyDown(video, space)).toBe(false);
    expect(pause).not.toHaveBeenCalled();
    fireEvent.keyUp(video, space);
    expect(pause).toHaveBeenCalledOnce();

    fireEvent.keyDown(video, space);
    fireEvent.keyDown(video, { ...space, repeat: true });
    act(() => vi.advanceTimersByTime(320));
    expect(video.playbackRate).toBe(2);
    fireEvent.rateChange(video);
    expect(speed.value).toBe("1.25");
    expect(video.defaultPlaybackRate).toBe(1.25);
    fireEvent.keyUp(video, space);
    expect(video.playbackRate).toBe(1.25);
    expect(pause).toHaveBeenCalledOnce();

    fireEvent.keyDown(video, space);
    act(() => vi.advanceTimersByTime(320));
    fireEvent.blur(window);
    expect(video.playbackRate).toBe(1.25);
    fireEvent.keyUp(video, space);
    expect(pause).toHaveBeenCalledOnce();

    fireEvent.keyDown(video, space);
    act(() => vi.advanceTimersByTime(320));
    fireEvent.pause(video);
    expect(video.playbackRate).toBe(1.25);
    fireEvent.keyUp(video, space);
    expect(pause).toHaveBeenCalledOnce();
  } finally {
    vi.useRealTimers();
  }
});

test("steps a paused video using its observed presentation cadence", async () => {
  const { MediaPlayer } = await import("../src/ui/media-player.tsx");
  let frame!: VideoFrameRequestCallback;
  const prototype = HTMLVideoElement.prototype;
  const requestDescriptor = Object.getOwnPropertyDescriptor(prototype, "requestVideoFrameCallback");
  const cancelDescriptor = Object.getOwnPropertyDescriptor(prototype, "cancelVideoFrameCallback");
  const request = vi.fn((callback: VideoFrameRequestCallback) => {
    frame = callback;
    return request.mock.calls.length;
  });
  const cancel = vi.fn();
  Object.defineProperties(prototype, {
    requestVideoFrameCallback: { configurable: true, value: request },
    cancelVideoFrameCallback: { configurable: true, value: cancel },
  });
  const page = render(<MediaPlayer chatId="42" messageId="9" mime="video/mp4" stream={async () => "/media/fixture"} />);
  try {
    fireEvent.click(screen.getByRole("button", { name: "Load video player" }));
    const video = await screen.findByLabelText<HTMLVideoElement>("Telegram video");
    await waitFor(() => expect(request).toHaveBeenCalledTimes(1));
    Object.defineProperties(video, { readyState: { value: video.HAVE_METADATA }, duration: { value: 12 } });
    video.currentTime = 4;
    fireEvent.keyDown(video, { key: "." });
    expect(video.currentTime).toBeCloseTo(4 + 1 / 30, 6);
    Object.defineProperty(video, "paused", { value: false, configurable: true });
    expect(fireEvent.keyDown(video, { key: "," })).toBe(true);
    frame(0, { mediaTime: 4.04, presentedFrames: 10 } as VideoFrameCallbackMetadata);
    frame(40, { mediaTime: 4.08, presentedFrames: 11 } as VideoFrameCallbackMetadata);
    Object.defineProperty(video, "paused", { value: true, configurable: true });
    video.currentTime = 4.085;
    expect(fireEvent.keyDown(video, { key: "." })).toBe(false);
    expect(video.currentTime).toBeCloseTo(4.125, 6);
    fireEvent.keyDown(video, { key: "," });
    expect(video.currentTime).toBeCloseTo(4.085, 6);
  } finally {
    page.unmount();
    if (requestDescriptor) Object.defineProperty(prototype, "requestVideoFrameCallback", requestDescriptor);
    else Reflect.deleteProperty(prototype, "requestVideoFrameCallback");
    if (cancelDescriptor) Object.defineProperty(prototype, "cancelVideoFrameCallback", cancelDescriptor);
    else Reflect.deleteProperty(prototype, "cancelVideoFrameCallback");
  }
  expect(cancel).toHaveBeenCalledWith(3);
});

