test("releases the channel inbox microphone on discard and sends only after review", async () => {
  const { ChannelInboxNote } = await import("../src/ui/channel-inbox-note.tsx");
  const mediaDevices = Object.getOwnPropertyDescriptor(navigator, "mediaDevices");
  const stopTrack = vi.fn();
  const getUserMedia = vi.fn(async () => ({ getTracks: () => [{ stop: stopTrack }] }));
  class Recorder {
    static isTypeSupported() { return true; }
    state = "inactive";
    onstop?: () => void;
    ondataavailable?: (event: { data: Blob }) => void;
    start() { this.state = "recording"; }
    stop() {
      this.state = "inactive";
      this.ondataavailable?.({ data: new Blob(["voice"]) });
      this.onstop?.();
    }
  }
  const send = vi.fn(async () => ({ state: "sent" as const, message: { id: "13", author: "You", text: "Voice", time: "" } }));
  const close = vi.fn();
  vi.stubGlobal("MediaRecorder", Recorder);
  Object.defineProperty(navigator, "mediaDevices", { configurable: true, value: { getUserMedia } });
  try {
    const whileRecording = render(<ChannelInboxNote kind="voice" reply={null} disabled={false} close={close} send={send} />);
    expect(getUserMedia).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("button", { name: "Record voice" }));
    await screen.findByRole("button", { name: "Stop recording" });
    whileRecording.unmount();
    expect(stopTrack).toHaveBeenCalledOnce();
    expect(send).not.toHaveBeenCalled();

    const review = render(<ChannelInboxNote kind="voice" reply={null} disabled={false} close={close} send={send} />);
    fireEvent.click(screen.getByRole("button", { name: "Record voice" }));
    fireEvent.click(await screen.findByRole("button", { name: "Stop recording" }));
    expect(stopTrack).toHaveBeenCalledTimes(2);
    expect(send).not.toHaveBeenCalled();
    fireEvent.click(screen.getByRole("button", { name: "Send voice note" }));
    await waitFor(() => expect(close).toHaveBeenCalledOnce());
    expect(getUserMedia.mock.calls).toEqual([[{ audio: true }], [{ audio: true }]]);
    expect(send).toHaveBeenCalledExactlyOnceWith({ kind: "voice", base64: "dm9pY2U=", duration: 1, format: "ogg", trim: undefined });
    review.unmount();
  } finally {
    if (mediaDevices) Object.defineProperty(navigator, "mediaDevices", mediaDevices);
    else Reflect.deleteProperty(navigator, "mediaDevices");
    vi.unstubAllGlobals();
  }
});

