test("previews a hovered video frame and commits a drag only when released", async () => {
  const { VideoSeekPreview } = await import("../src/ui/video-seek-preview.tsx");
  const seek = vi.fn();
  const load = vi.spyOn(HTMLMediaElement.prototype, "load").mockImplementation(() => {});
  try {
    const view = render(<VideoSeekPreview source="/fixture/video" duration={100} position={10} seek={seek} />);
    const slider = screen.getByRole<HTMLInputElement>("slider", { name: "Video seek preview" });
    vi.spyOn(slider, "getBoundingClientRect").mockReturnValue(new DOMRect(10, 0, 100, 20));
    const pointer = (type: string, pointerId: number, clientX = 0) => {
      const event = new MouseEvent(type, { bubbles: true, clientX });
      Object.defineProperties(event, { pointerId: { value: pointerId },
        pointerType: { value: "mouse" }, isPrimary: { value: true } });
      fireEvent(slider, event);
    };
    const preview = view.container.querySelector("video")!;
    expect(preview.getAttribute("src")).toBeNull();
    pointer("pointermove", 7, 65);
    expect(await screen.findByText("0:55")).toBeTruthy();
    await waitFor(() => expect(preview.getAttribute("src")).toBe("/fixture/video"));
    Object.defineProperty(preview, "duration", { value: 100 });
    Object.defineProperty(preview, "readyState", { value: preview.HAVE_CURRENT_DATA });
    fireEvent.loadedMetadata(preview);
    expect(preview.currentTime).toBe(55);
    expect(preview.getAttribute("data-frame-ready")).toBe("false");
    fireEvent.seeked(preview);
    expect(preview.getAttribute("data-frame-ready")).toBe("true");
    expect(seek).not.toHaveBeenCalled();
    pointer("pointerdown", 7, 50);
    pointer("pointermove", 7, 85);
    expect(seek).not.toHaveBeenCalled();
    pointer("pointercancel", 7);
    expect(slider.value).toBe("10");
    expect(seek).not.toHaveBeenCalled();
    expect(preview.getAttribute("src")).toBeNull();
    pointer("pointerdown", 8, 40);
    pointer("pointermove", 8, 90);
    pointer("pointerup", 8, 90);
    expect(seek).toHaveBeenCalledExactlyOnceWith(80);
    fireEvent.input(slider, { target: { value: "25" } });
    expect(seek).toHaveBeenLastCalledWith(25);
  } finally { load.mockRestore(); }
});

