test.each(["chat", "forum topic"])("sends an oversized %s draft as an explicit UTF-8 file reply", async (mode) => {
  const { ForumTopics } = await import("../src/ui/forum-topics.tsx");
  const chatId = "42";
  const topic = { id: 17, name: "Long draft topic", closed: false };
  const parent = { id: "12", text: "Synthetic reply parent", author: "Fixture", time: "" };
  const history = async () => ({ messages: [parent], before: null });
  const sendText = vi.fn(async () => ({ state: "failed" as const }));
  const sendDocument = vi.fn().mockResolvedValueOnce({ state: "failed" })
    .mockResolvedValueOnce({ state: "sent", message: { id: "23", text: "Document sent", time: "", author: "You" } });
  if (mode === "forum topic") {
    render(<ForumTopics chatId={chatId} topics={[topic]} initialTopic={topic} loadForumTopics={async () => [topic]}
      loadTopicHistory={history} sendTopicText={sendText} sendDocument={sendDocument}
      loadPhoto={undefined} saveDocument={undefined} close={() => {}} />);
  } else {
    render(<TelegramPage live={{
      chats: [{ id: chatId, name: "Long draft fixture", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] }],
      folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      findChats: async () => [], sendText, loadHistory: history, sendDocument,
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Long draft fixture/ }));
  }
  const row = (await screen.findByText(parent.text)).closest("li")!;
  fireEvent.click(within(row).getByRole("button", { name: mode === "chat" ? "Reply to message" : "Reply" }));
  expect(screen.getByRole("button", { name: "Cancel reply" })).toBeTruthy();
  const field = screen.getByRole<HTMLTextAreaElement>("textbox", { name: mode === "chat" ? "Write a message" : "Write a topic message" });
  expect(field.hasAttribute("maxlength")).toBe(false);
  const draft = "  " + "Пример 🙂\n".repeat(500) + "  ";
  fireEvent.change(field, { target: { value: draft } });
  fireEvent.submit(field.form!);
  expect(sendText).not.toHaveBeenCalled();
  expect(sendDocument).not.toHaveBeenCalled();
  const send = screen.getByRole("button", { name: "Send as text file" });
  fireEvent.click(send);
  await waitFor(() => expect(sendDocument).toHaveBeenCalledOnce());
  const [id, file, caption, , , destination, reply] = sendDocument.mock.calls[0]!;
  expect([id, file.name, caption, destination, reply]).toEqual([
    chatId, "message.txt", "", mode === "chat" ? undefined : { id: topic.id, name: topic.name }, parent.id,
  ]);
  const contents = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsText(file);
  });
  expect(contents).toEqual(draft);
  await screen.findByText("Telegram rejected the message. Your draft is still here.");
  expect(field.value).toBe(draft);
  fireEvent.click(send);
  await waitFor(() => expect(field.value).toBe(""));
  expect(sendDocument).toHaveBeenCalledTimes(2);
  expect(sendText).not.toHaveBeenCalled();
});

test.each(["chat", "forum", "inbox"])("splits a long %s draft and keeps only messages without confirmation", async (mode) => {
  const { ForumTopics } = await import("../src/ui/forum-topics.tsx");
  const { ChannelDirectMessages } = await import("../src/ui/channel-direct-messages.tsx");
  const topic = { id: 17, name: "Fixture topic", closed: false };
  const message = { id: "100", text: "Fixture sent", time: "", author: "You" };
  const send = vi.fn().mockResolvedValueOnce({ state: "sent", message }).mockResolvedValueOnce({ state: "unknown" });
  const history = async () => ({ messages: [], before: null });
  let inputName: string;
  let sendName: string;
  if (mode === "inbox") {
    render(<ChannelDirectMessages id="-42" channelName="Fixture channel" open={vi.fn()}
      load={async () => ({ id: "-43", name: "Fixture inbox", initials: "FI", color: "#246dbd", subtitle: "Channel inbox", messages: [] })}
      inboxActions={{ loadTopics: async () => ({ topics: [{ id: "17", name: "Fixture correspondent", unread: 0, markedUnread: false }], next: null }),
        loadHistory: history, sendText: send }} />);
    fireEvent.click(await screen.findByRole("button", { name: "Open channel inbox" }));
    fireEvent.click(await screen.findByRole("button", { name: "Fixture correspondent" }));
    await screen.findByText("No messages in this conversation");
    inputName = "Write a channel reply";
    sendName = "Send channel reply";
  } else if (mode === "forum") {
    render(<ForumTopics chatId="-42" topics={[topic]} initialTopic={topic} loadForumTopics={async () => [topic]}
      loadTopicHistory={history} sendTopicText={send} loadPhoto={undefined} saveDocument={undefined} close={() => {}} />);
    inputName = "Write a topic message";
    sendName = "Send to topic";
  } else {
    render(<TelegramPage live={{
      chats: [{ id: "-42", name: "Split fixture", initials: "SF", color: "#246dbd", subtitle: "Direct message", messages: [] }],
      folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      findChats: async () => [], sendText: send, loadHistory: history,
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Split fixture/ }));
    inputName = "Write a message";
    sendName = "Send message";
  }
  const field = screen.getByRole<HTMLTextAreaElement>("textbox", { name: inputName });
  const first = "a".repeat(4095);
  const remaining = "🙂" + "b".repeat(4100);
  const text = first + remaining;
  expect(fireEvent.paste(field, { clipboardData: { files: [], getData: (type: string) => type === "text/html" ? `<strong>${text}</strong>` : text } })).toBe(false);
  expect(field.value).toBe(text);
  fireEvent.submit(field.form!);
  expect(send).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Send as multiple messages" }));
  await waitFor(() => expect(field.value).toBe(remaining));
  const textIndex = mode === "inbox" ? 3 : mode === "forum" ? 2 : 1;
  expect(send.mock.calls.map((args) => args[textIndex])).toEqual([first, remaining.slice(0, 4096)]);
  const styles = (args: unknown[]) => mode === "forum" ? args[4] : (args[mode === "inbox" ? 5 : 3] as { styles?: unknown }).styles;
  expect(send.mock.calls.map(styles)).toEqual([first.length, 4096].map((length) => [{ offset: 0, length, style: "bold" }]));
  expect(screen.getByRole<HTMLButtonElement>("button", { name: "Send as multiple messages" }).disabled).toBe(true);
  expect(screen.getByRole<HTMLButtonElement>("button", { name: sendName }).disabled).toBe(true);
  expect(send).toHaveBeenCalledTimes(2);
  send.mockResolvedValueOnce({ state: "sent", message: { ...message, id: "101" } })
    .mockResolvedValueOnce({ state: "sent", message: { ...message, id: "102" } });
  fireEvent.click(screen.getByRole("button", { name: /^Allow retry/ }));
  fireEvent.click(screen.getByRole("button", { name: "Send as multiple messages" }));
  await waitFor(() => expect(field.value).toBe(""));
  expect(send.mock.calls.slice(2).map((args) => args[textIndex])).toEqual([remaining.slice(0, 4096), remaining.slice(4096)]);
});

test.each(["messages", "file"])("blocks a duplicate long chat send as %s across remounts", async (mode) => {
  const { createAccountDrafts } = await import("../src/ui/local-drafts.ts");
  const account = createAccountDrafts();
  const sent = { state: "sent", message: { id: "100", text: "Fixture accepted", time: "", author: "You" } };
  let reportUnknown!: (result: { state: "unknown" }) => void;
  const pending = new Promise<{ state: "unknown" }>((resolve) => { reportUnknown = resolve; });
  const first = "a".repeat(4096);
  const rest = "б".repeat(4100);
  const source = first + rest;
  const sendText = vi.fn().mockResolvedValueOnce(sent).mockReturnValueOnce(pending);
  const sendDocument = vi.fn().mockReturnValueOnce(pending);
  const live = {
    chats: [{ id: "42", name: "Long draft fixture", initials: "LD", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main" as const, selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    findChats: async () => [], sendText, sendDocument, loadHistory: async () => ({ messages: [], before: null }),
  };
  const view = (key: string) => <TelegramPage key={key} draftStorage={account} live={live} />;
  const { rerender } = render(view("first"));
  const openChat = () => fireEvent.click(screen.getByRole("button", { name: /Long draft fixture/ }));
  const draft = () => screen.getByRole<HTMLTextAreaElement>("textbox", { name: "Write a message" });
  const split = () => screen.getByRole<HTMLButtonElement>("button", { name: "Send as multiple messages" });
  const file = () => screen.getByRole<HTMLButtonElement>("button", { name: "Send as text file" });
  openChat();
  fireEvent.change(draft(), { target: { value: source } });
  fireEvent.click(mode === "messages" ? split() : file());
  const sends = mode === "messages" ? sendText : sendDocument;
  const dispatched = mode === "messages" ? 2 : 1;
  await waitFor(() => expect(sends).toHaveBeenCalledTimes(dispatched));

  rerender(view("reopened"));
  openChat();
  expect(draft().disabled).toBe(true);
  expect(split().disabled && file().disabled).toBe(true);
  fireEvent.submit(draft().form!);
  expect(sends).toHaveBeenCalledTimes(dispatched);

  await act(async () => reportUnknown({ state: "unknown" }));
  expect(draft().value).toBe(mode === "messages" ? rest : source);
  expect(split().disabled && file().disabled).toBe(true);
  rerender(view("reopened again"));
  openChat();
  expect(screen.getByText(/Telegram did not confirm delivery/)).toBeTruthy();
  expect(split().disabled && file().disabled).toBe(true);
  fireEvent.click(screen.getByRole("button", { name: /^Allow retry/ }));
  expect(split().disabled || file().disabled).toBe(false);
  expect(sends).toHaveBeenCalledTimes(dispatched);
});

