test.each(["before sending", "after upload failure"])("keeps the original video and caption when switching to a document %s", async (stage) => {
  const sendDocument = vi.fn().mockResolvedValue({ state: "sent", message: { id: "23", text: "File fixture", time: "", author: "You" } });
  if (stage === "after upload failure") sendDocument.mockResolvedValueOnce({ state: "failed", uploadRejection: "video_preparation_failed" });
  render(<TelegramPage live={{
    chats: [{ id: "42", name: "Video fallback fixture", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    findChats: async () => [], sendText: async () => ({ state: "failed" }),
    loadHistory: async () => ({ messages: [], before: null }), sendDocument,
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Video fallback fixture/ }));
  const file = new File(["fixture"], "original.mov", { type: "video/quicktime" });
  fireEvent.change(screen.getByLabelText("Choose video"), { target: { files: [file] } });
  fireEvent.change(screen.getByRole("textbox", { name: "Write an attachment caption" }), { target: { value: "Keep this caption" } });
  fireEvent.click(screen.getByRole("checkbox", { name: "Original video quality" }));
  fireEvent.click(screen.getByRole("checkbox", { name: "Hide video under a spoiler" }));
  if (stage === "after upload failure") {
    fireEvent.click(screen.getByRole("button", { name: "Send message" }));
    fireEvent.click(await screen.findByRole("button", { name: "Attach original as document" }));
    expect(sendDocument).toHaveBeenCalledTimes(1);
  } else {
    fireEvent.click(screen.getByRole("button", { name: "Send original as file" }));
    expect(sendDocument).not.toHaveBeenCalled();
  }
  expect(screen.queryByRole("checkbox", { name: "Hide video under a spoiler" })).toBeNull();
  expect(screen.queryByRole("checkbox", { name: "Original video quality" })).toBeNull();
  fireEvent.click(screen.getByRole("button", { name: "Send message" }));
  await within(screen.getByRole("list", { name: "Messages" })).findByText("File fixture");
  const original = [file, "Keep this caption", undefined, undefined];
  expect(sendDocument.mock.calls.map((args) => [args[1], args[2], args[7], args[8]])).toEqual(stage === "after upload failure"
    ? [[file, "Keep this caption", true, { originalVideo: true, spoiler: true }], original] : [original]);
});

