test("only offers copying selected text within the selection bounds", async () => {
  const { contextSelection } = await import("../src/ui/object-context-menu.tsx");
  const { container } = render(<span>Selected fixture</span>);
  const range = document.createRange();
  range.selectNodeContents(container.firstElementChild!.firstChild!);
  Object.defineProperty(range, "getClientRects", {
    value: () => [{ left: 10, right: 60, top: 20, bottom: 40 }],
  });
  const selection = document.getSelection()!;
  selection.removeAllRanges();
  selection.addRange(range);
  try {
    expect(contextSelection(container, { x: 20, y: 30 })).toBe("Selected fixture");
    expect(contextSelection(container, { x: 20, y: 60 })).toBeUndefined();
  } finally {
    selection.removeAllRanges();
  }
});

