test("reviews a pasted game link and forum destination before sending", async () => {
  const url = "https://t.me/fixturebot?game=FixtureGame";
  const bot = { id: "90", name: "Fixture Game Bot", initials: "G", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const forum = { id: "-42", name: "Fixture game forum", initials: "F", color: "#246dbd", subtitle: "Group", messages: [], forum: true as const };
  const topic = { id: 17, name: "Game night" };
  const resolve = vi.fn(async () => ({ chat: bot, username: "fixturebot", shortName: "FixtureGame" }));
  const send = vi.fn(async () => "sent" as const);
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    render(<TelegramPage live={{ chats: [], folders: [], list: "main", selectList: () => {}, refresh: () => {},
      loading: false, liveRevision: 0, error: "", loadHistory: async () => ({ messages: [], before: null }),
      findChats: async () => [], sendText: async () => ({ state: "failed" }), gameLinks: {
        resolve, send, find: async () => [forum], topics: async () => ({ topics: [topic], next: null }),
      },
    }} />);
    fireEvent.change(screen.getByRole("searchbox", { name: "Search Telegram chats" }), { target: { value: url } });
    const choose = await screen.findByRole("button", { name: "Choose a chat for the game" });
    expect(resolve).toHaveBeenCalledExactlyOnceWith(url);
    fireEvent.click(choose);
    const picker = within(screen.getByRole("dialog", { name: "Choose a chat for the game" }));
    fireEvent.click(picker.getByRole("button", { name: "Show recent chats" }));
    fireEvent.click(await picker.findByRole("button", { name: /Fixture game forum/ }));
    fireEvent.click(picker.getByRole("button", { name: "Show topics" }));
    fireEvent.click(await picker.findByRole("button", { name: "Game night" }));
    const confirmSend = await screen.findByRole("button", { name: "Send game" });
    expect(screen.queryByRole("dialog", { name: "Choose a chat for the game" })).toBeNull();
    expect(send).not.toHaveBeenCalled();
    fireEvent.click(confirmSend);
    await screen.findByText("Game sent.");
    expect(send).toHaveBeenCalledExactlyOnceWith(url, "90", { id: forum.id, name: forum.name, kind: "Group", topic });
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

