test("a sandboxed game can open forwarding review while BB controls the destination and send", async () => {
  const button = { kind: "callback" as const, label: "Start fixture game", row: 0, column: 0, revision: "a".repeat(64) };
  const press = vi.fn(async () => ({ state: "answered" as const, text: "", alert: false, gameUrl: "https://example.net/game" }));
  const forwardOptions = vi.fn(async () => true);
  const forwardMessage = vi.fn(async () => "sent" as const);
  const recipient = { id: "49", name: "Fixture destination", initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] };
  const gesture = { isActive: false };
  const activation = Object.getOwnPropertyDescriptor(navigator, "userActivation");
  Object.defineProperty(navigator, "userActivation", { configurable: true, value: gesture });
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    render(<PressInlineBotButton.Provider value={press}>
      <MessageContent chatId="42" message={{ id: "9", author: "Fixture", time: "", text: "Instructions", gameTitle: "Fixture game",
        inlineBotKeyboard: [[button]] }} forwardActions={{ forwardOptions, forwardMessage, recipients: [recipient], searchRecipients: async () => [] }} />
    </PressInlineBotButton.Provider>);
    fireEvent.click(screen.getByRole("button", { name: "Start fixture game" }));
    fireEvent.click(await screen.findByRole("button", { name: "Play game from example.net" }));
    const viewer = within(screen.getByRole("dialog", { name: "Telegram game" }));
    const frame = viewer.getByTitle<HTMLIFrameElement>("Game from example.net");
    const emit = (eventType: string, source = frame.contentWindow, origin = "null") => fireEvent(window, new MessageEvent("message", {
      source, origin, data: JSON.stringify({ eventType, eventData: { chatId: "99", messageId: "91", destination: "49" } }),
    }));
    emit("share_game");
    gesture.isActive = true;
    emit("share_game");
    expect(forwardOptions).not.toHaveBeenCalled();
    frame.focus();
    emit("share_game", window);
    emit("share_game", frame.contentWindow, "https://example.net");
    expect(forwardOptions).not.toHaveBeenCalled();
    emit("share_score");
    expect(viewer.getByText("Sharing a score is unavailable in BB.")).toBeTruthy();
    emit("share_game");
    emit("share_game");
    const review = within(await viewer.findByRole("dialog", { name: "Share game" }));
    expect(forwardOptions).toHaveBeenCalledExactlyOnceWith("42", "9");
    const form = await review.findByLabelText("Forward to");
    expect((form as HTMLSelectElement).value).toBe("");
    expect(forwardMessage).not.toHaveBeenCalled();
    fireEvent.change(form, { target: { value: "49" } });
    expect(forwardMessage).not.toHaveBeenCalled();
    fireEvent.click(review.getByRole("button", { name: "Forward" }));
    await review.findByText("Game forwarded.");
    expect(forwardMessage).toHaveBeenCalledExactlyOnceWith("42", "9", { id: "49", name: recipient.name, kind: "Direct message" });
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (activation) Object.defineProperty(navigator, "userActivation", activation);
    else Reflect.deleteProperty(navigator, "userActivation");
  }
});

