test.each(["button", "callback"] as const)("reviews a Telegram link from a bot %s before navigating inside BB", async (source) => {
  const native = "tg://resolve?domain=FixtureChannel&post=9";
  const canonical = "https://t.me/fixturechannel/9";
  const press = vi.fn(async () => ({ state: "answered" as const, text: "", alert: false, url: native }));
  const follow = vi.fn().mockResolvedValueOnce(false).mockResolvedValueOnce(true);
  const confirm = vi.spyOn(window, "confirm").mockReturnValueOnce(false).mockReturnValue(true);
  const open = vi.spyOn(window, "open").mockImplementation(() => null);
  try {
    render(<OpenTelegramMessageLink.Provider value={follow}><PressInlineBotButton.Provider value={press}>
      <InlineBotKeyboard chatId="42" messageId="9" rows={[[source === "button" ? { kind: "url", label: "Telegram post", url: native }
        : { kind: "callback", label: "Get post", row: 0, column: 0, revision: "a".repeat(64) }]]} />
    </PressInlineBotButton.Provider></OpenTelegramMessageLink.Provider>);
    if (source === "callback") fireEvent.click(screen.getByRole("button", { name: "Get post" }));
    const button = await screen.findByRole("button", { name: source === "button" ? "Telegram post" : "Open bot link" });
    expect(follow).not.toHaveBeenCalled();
    fireEvent.click(button);
    expect(confirm).toHaveBeenCalledExactlyOnceWith(expect.stringContaining(canonical));
    expect(follow).not.toHaveBeenCalled();
    fireEvent.click(button);
    expect(await screen.findByText("Telegram link unavailable.")).toBeTruthy();
    fireEvent.click(button);
    await waitFor(() => expect(screen.queryByText("Telegram link unavailable.")).toBeNull());
    expect(follow.mock.calls).toEqual([[canonical, expect.any(AbortSignal)], [canonical, expect.any(AbortSignal)]]);
    expect(open).not.toHaveBeenCalled();
  } finally {
    confirm.mockRestore();
    open.mockRestore();
  }
});

