test("checks a Mini App inline destination before returning the query to its forum topic", async () => {
  const forum = { id: "-52", name: "Fixture forum", initials: "FF", color: "#246dbd", subtitle: "Group", messages: [], forum: true as const };
  const topic = { id: 17, name: "Fixture topic", closed: false };
  const inlineChats = vi.fn(async () => [forum]);
  const inlineTopics = vi.fn(async () => ({ topics: [{ id: topic.id, name: topic.name }], next: null }));
  const inlineDestination = vi.fn().mockResolvedValueOnce(null).mockResolvedValueOnce({ chat: forum, topic });
  const useOtherChatQuery = vi.fn(() => true);
  const close = vi.fn(async () => true);
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    function Fixture() {
      const [opened, setOpened] = useState(true);
      return opened && <MiniAppDialog target={{ label: "Fixture app" }} launch={async () => ({
        url: "https://fixture.example.com/app", session: "fixture-session",
      })} close={() => setOpened(false)} useCurrentChatQuery={() => false} useOtherChatQuery={useOtherChatQuery} />;
    }
    render(<MiniAppSessionActions.Provider value={{ close, writeAccess: async () => "unavailable",
      inlineChats, inlineTopics, inlineDestination }}><Fixture /></MiniAppSessionActions.Provider>);
    const app = screen.getByRole("dialog", { name: "Telegram Mini App" });
    fireEvent.click(within(app).getByRole("button", { name: "Open Mini App" }));
    const frame = await within(app).findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    fireEvent(window, new MessageEvent("message", { origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_switch_inline_query", eventData: { query: "from the app", chat_types: ["groups"] } }),
    }));
    expect(inlineChats).not.toHaveBeenCalled();
    fireEvent.click(within(app).getByRole("button", { name: "Show recent chats" }));
    fireEvent.click(await within(app).findByRole("button", { name: "Fixture forum Group" }));
    fireEvent.click(within(app).getByRole("button", { name: "Show topics" }));
    const choice = await within(app).findByRole("button", { name: topic.name });
    expect(inlineTopics).toHaveBeenCalledExactlyOnceWith("fixture-session", ["groups"], "-52", "", undefined);
    fireEvent.click(choice);
    expect(await within(app).findByText("Could not put this query in the selected destination.")).toBeTruthy();
    expect(useOtherChatQuery).not.toHaveBeenCalled();
    fireEvent.click(choice);
    await waitFor(() => expect(useOtherChatQuery).toHaveBeenCalledExactlyOnceWith(forum, "from the app", topic));
    expect(screen.queryByRole("dialog", { name: "Telegram Mini App" })).toBeNull();
    expect(close).toHaveBeenCalledExactlyOnceWith("fixture-session");
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
  }
});

test("queries an inline bot and sends a selected result through separate user actions", async () => {
  const search = vi.fn(async () => ({ results: [{ token: "fixture", title: "Fixture result", kind: "Article", description: "", hasPreview: true as const }], next: null, miniApp: { label: "Open fixture app", token: "fixture-app" } }));
  const launchMiniApp = vi.fn(async () => ({ url: "https://fixture.example.com/app", session: "fixture-session" }));
  const inlineChats = vi.fn(async () => [{ id: "43", name: "Fixture group", initials: "FG", color: "#246dbd", subtitle: "Group", messages: [] }]);
  const preview = vi.fn(async () => ({ mime: "image/jpeg" as const, base64: "Fixture" }));
  const send = vi.fn(async () => ({ state: "sent" as const, message: { id: "9", author: "You", time: "", text: "Sent fixture article", viaBot: "FixtureBot" } }));
  const sendText = vi.fn(async () => ({ state: "failed" as const }));
  render(<MiniAppSessionActions.Provider value={{ close: async () => true, writeAccess: async () => "unavailable", inlineChats,
    inlineDestination: async () => null }}><TelegramPage live={{
    chats: [{ id: "42", name: "Fixture inline chat", initials: "FI", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory: async () => ({ before: null, messages: [{ id: "8", author: "Fixture bot", time: "", text: "Fixture keyboard",
      inlineBotKeyboard: [[{ kind: "switchInline", label: "Search here", bot: "FixtureBot", query: "preset" }]],
    }] }), findChats: async () => [], sendText,
    inlineBotActions: { search, preview, send, launchMiniApp },
  }} /></MiniAppSessionActions.Provider>);
  fireEvent.click(screen.getByRole("button", { name: /Fixture inline chat/ }));
  const composer = await screen.findByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement;
  fireEvent.click(await screen.findByRole("button", { name: "Search here" }));
  expect(composer.value).toBe("@FixtureBot preset");
  fireEvent.change(composer, { target: { value: "@FixtureBot query" } });
  expect(search).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole("button", { name: "Search @FixtureBot" }));
  let result = await screen.findByRole("button", { name: /Fixture result/ });
  expect(search).toHaveBeenCalledExactlyOnceWith("42", "FixtureBot", "query", undefined);
  expect(send).not.toHaveBeenCalled();
  await waitFor(() => expect(result.querySelector("img")?.getAttribute("src")).toBe("data:image/jpeg;base64,Fixture"));
  expect(preview).toHaveBeenCalledExactlyOnceWith("42", "fixture");
  expect(launchMiniApp).not.toHaveBeenCalled();
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  Object.defineProperty(prototype, "showModal", { configurable: true, value(this: HTMLDialogElement) { this.open = true; } });
  try {
    fireEvent.click(screen.getByRole("button", { name: "Open fixture app" }));
    expect(launchMiniApp).not.toHaveBeenCalled();
    const app = screen.getByRole("dialog", { name: "Telegram Mini App" });
    fireEvent.click(within(app).getByRole("button", { name: "Open Mini App" }));
    const frame = await within(app).findByTitle<HTMLIFrameElement>("Telegram Mini App content");
    expect(launchMiniApp).toHaveBeenCalledExactlyOnceWith("42", "fixture-app");
    const requestQuery = (chat_types: string[]) => fireEvent(window, new MessageEvent("message", {
      origin: "null", source: frame.contentWindow,
      data: JSON.stringify({ eventType: "web_app_switch_inline_query", eventData: { query: "from the app", chat_types } }),
    }));
    requestQuery(["groups"]);
    expect(inlineChats).not.toHaveBeenCalled();
    fireEvent.click(within(app).getByRole("button", { name: "Show recent chats" }));
    expect(await within(app).findByRole("button", { name: "Fixture group Group" })).toBeTruthy();
    expect(inlineChats).toHaveBeenCalledExactlyOnceWith("fixture-session", ["groups"], "");
    fireEvent.click(within(app).getByRole("button", { name: "Cancel inline query" }));
    requestQuery([]);
    expect(composer.value).toBe("@FixtureBot query");
    fireEvent.click(within(app).getByRole("button", { name: "Cancel inline query" }));
    expect(composer.value).toBe("@FixtureBot query");
    requestQuery([]);
    fireEvent.click(within(app).getByRole("button", { name: "Use inline query" }));
    expect(composer.value).toBe("@FixtureBot from the app");
    expect(screen.queryByRole("dialog", { name: "Telegram Mini App" })).toBeNull();
    expect(send).not.toHaveBeenCalled();
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
  }
  fireEvent.click(screen.getByRole("button", { name: "Search @FixtureBot" }));
  result = await screen.findByRole("button", { name: /Fixture result/ });
  expect(search).toHaveBeenLastCalledWith("42", "FixtureBot", "from the app", undefined);
  fireEvent.click(result);
  await within(screen.getByRole("list", { name: "Messages" })).findByText("Sent fixture article");
  expect(send).toHaveBeenCalledExactlyOnceWith("42", "fixture", undefined, undefined);
  expect(sendText).not.toHaveBeenCalled();
  expect(composer.value).toBe("");
  fireEvent.change(composer, { target: { value: "new query" } });
  fireEvent.click(screen.getByRole("button", { name: "@FixtureBot" }));
  expect(composer.value).toBe("@FixtureBot new query");
  expect(search).toHaveBeenCalledTimes(2);
  expect(send).toHaveBeenCalledTimes(1);
});

