test("keeps topic activity isolated and removes cancelled or expired indicators", () => {
  let send!: Parameters<SubscribeToActivity>[0];
  const subscribe: SubscribeToActivity = (listener) => { send = listener; return () => {}; };
  const view = render(<ChatActivityIndicator chatId="-7" topicId={17} subscribe={subscribe} />);
  vi.useFakeTimers();
  try {
    const event = { chatId: "-7", topicId: 17, sender: { id: "9", kind: "user" as const } };
    act(() => send({ ...event, topicId: 18, activity: "typing" }));
    expect(screen.queryByRole("status")).toBeNull();
    act(() => send({ ...event, activity: "voice" }));
    expect(screen.getByRole("status").textContent).toBe("Recording a voice message…");
    act(() => send({ ...event, activity: "uploading", progress: 42 }));
    expect(screen.getByRole("status").textContent).toBe("Uploading… 42%");
    act(() => send({ ...event, activity: "cancel" }));
    expect(screen.queryByRole("status")).toBeNull();
    act(() => send({ ...event, activity: "typing" }));
    expect(screen.getByRole("status").textContent).toBe("Typing…");
    act(() => { vi.advanceTimersByTime(6000); });
    expect(screen.queryByRole("status")).toBeNull();
  } finally {
    view.unmount();
    vi.useRealTimers();
  }
});

test("publishes typing only on edits, limits refreshes and cancels on inactivity or chat change", async () => {
  vi.useFakeTimers();
  const send = vi.fn(async () => true);
  const hook = renderHook(({ id, topic }: { id: string; topic?: number }) => useTypingActivity(id, send, topic),
    { initialProps: { id: "42", topic: 17 } as { id: string; topic?: number } });
  try {
    expect(send).not.toHaveBeenCalled();
    await act(async () => { hook.result.current.changed("a"); hook.result.current.changed("ab"); });
    expect(send.mock.calls).toEqual([["42", true, 17]]);
    await act(async () => { vi.advanceTimersByTime(4000); hook.result.current.changed("abc"); });
    expect(send.mock.calls).toEqual([["42", true, 17], ["42", true, 17]]);
    await act(async () => { vi.advanceTimersByTime(5000); });
    expect(send).toHaveBeenLastCalledWith("42", false, 17);
    await act(async () => { hook.result.current.changed("abcd"); });
    await act(async () => { hook.rerender({ id: "43" }); });
    expect(send.mock.calls.slice(-2)).toEqual([["42", true, 17], ["42", false, 17]]);
  } finally {
    hook.unmount();
    vi.useRealTimers();
  }
});

test("refreshes recording activity and cancels after an in-flight renewal", async () => {
  vi.useFakeTimers();
  let resolvePending!: (accepted: boolean) => void;
  const pending = new Promise<boolean>((resolve) => { resolvePending = resolve; });
  const send = vi.fn().mockResolvedValueOnce(true).mockReturnValueOnce(pending).mockResolvedValue(true);
  const stop = announceRecording(send, "voice");
  try {
    await vi.advanceTimersByTimeAsync(0);
    expect(send.mock.calls).toEqual([["voice"]]);
    await vi.advanceTimersByTimeAsync(8000);
    expect(send.mock.calls).toEqual([["voice"], ["voice"]]);
    stop();
    stop();
    expect(send).toHaveBeenCalledTimes(2);
    resolvePending(true);
    await vi.advanceTimersByTimeAsync(8000);
    expect(send.mock.calls).toEqual([["voice"], ["voice"], ["cancel"]]);
  } finally {
    stop();
    vi.useRealTimers();
  }
});

