test("keeps a realtime presence update over an older response and refreshes on expiry", async () => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));
  type Presence = import("../src/core/contract.ts").UserPresence;
  let resolveSnapshot!: (presence: Presence) => void;
  const snapshot = new Promise<Presence>((resolve) => { resolveSnapshot = resolve; });
  const load = vi.fn().mockReturnValueOnce(snapshot).mockResolvedValueOnce({ state: "week" });
  let notice!: Parameters<SubscribeToPresence>[0];
  const subscribe: SubscribeToPresence = (listener) => { notice = listener; return () => {}; };
  const view = render(<PeerPresence id="42" load={load} subscribe={subscribe} />);
  try {
    const expiry = Date.now() / 1000 + 1;
    act(() => notice({ chatId: "43", presence: { state: "online", expires: expiry } }));
    expect(screen.queryByText("Online")).toBeNull();
    act(() => notice({ chatId: "42", presence: { state: "online", expires: expiry } }));
    await act(async () => resolveSnapshot({ state: "month" }));
    expect(screen.getByText("Online")).toBeTruthy();
    await act(async () => { await vi.advanceTimersByTimeAsync(1000); });
    expect(screen.getByText("Last seen within a week")).toBeTruthy();
    expect(load).toHaveBeenCalledTimes(2);
  } finally {
    view.unmount();
    vi.useRealTimers();
  }
});

