test.each(["wheel", "keyboard"])("prepends album files without remounting or duplicates via %s", async (gesture) => {
  const chat = { id: "42", name: "Fixture album history", initials: "F", color: "#246dbd", subtitle: "Group", messages: [] };
  const file = { author: "Fixture", time: "", text: "", albumId: "400",
    document: { name: "Fixture.txt", downloadable: false } };
  const visible = { ...file, id: "20" };
  const loadHistory = vi.fn()
    .mockResolvedValueOnce({ messages: [visible], before: "20" })
    .mockResolvedValueOnce({ messages: [{ ...file, id: "10" }, visible], before: null });
  render(<TelegramPage live={{
    chats: [chat], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
    loadHistory, findChats: async () => [], sendText: async () => ({ state: "failed" }),
  }} />);
  fireEvent.click(screen.getByRole("button", { name: /Fixture album history/ }));
  const album = await screen.findByRole("list", { name: "Media album" });
  const [visibleRow] = within(album).getAllByRole("listitem");
  const list = screen.getByRole("list", { name: "Messages" });
  fireEvent.wheel(list, { deltaY: -100, ctrlKey: true });
  fireEvent.wheel(list, { deltaX: 200, deltaY: -10 });
  expect(loadHistory).toHaveBeenCalledTimes(1);
  if (gesture === "keyboard") {
    fireEvent.keyDown(within(list).getByRole("button", { name: "Load earlier messages" }), { key: "PageUp" });
    expect(loadHistory).toHaveBeenCalledTimes(1);
    list.focus();
    fireEvent.keyDown(list, { key: "PageUp" });
  } else fireEvent.wheel(list, { deltaY: -100 });
  await waitFor(() => expect(within(album).getAllByRole("listitem")).toHaveLength(2));
  const rows = within(album).getAllByRole("listitem");
  expect(rows[1]).toBe(visibleRow);
  expect(rows.map((row) => row.dataset.messageId)).toEqual(["10", "20"]);
  expect(within(album).getAllByText("Fixture.txt")).toHaveLength(2);
  expect(loadHistory.mock.calls).toEqual([["42"], ["42", "20"]]);
});

