test("keeps the visible saved message in place when media above it grows", async () => {
  let resize!: ResizeObserverCallback;
  vi.stubGlobal("ResizeObserver", class {
    constructor(callback: ResizeObserverCallback) { resize = callback; }
    observe() {}
    disconnect() {}
  });
  try {
    const first = { id: "20", text: "Saved media fixture", author: "Fixture", time: "" };
    const second = { ...first, id: "10", text: "Visible saved fixture" };
    const history = vi.fn().mockResolvedValue({ messages: [first, second], before: "10" });
    render(<SavedSources chatId="42" close={() => {}} media={{}} actions={{
      history, list: async () => ({ sources: [{ id: "42", title: "Saved media", pinned: false }], next: null }),
    }} />);
    fireEvent.click(await screen.findByRole("button", { name: "Saved media" }));
    const row = (await screen.findByText(second.text)).closest("li")!;
    const panel = screen.getByRole("region", { name: "Saved Messages by chat" });
    let offset = 400;
    let height = 620;
    Object.defineProperties(panel, { scrollHeight: { get: () => height }, clientHeight: { value: 200 } });
    vi.spyOn(row, "getBoundingClientRect").mockImplementation(() => new DOMRect(0, offset - panel.scrollTop, 100, 100));
    panel.scrollTop = 250;
    fireEvent.scroll(panel);
    offset += 180;
    height += 80;
    act(() => resize([], {} as ResizeObserver));
    expect(panel.scrollTop).toBe(430);
    expect(row.getBoundingClientRect().top).toBe(150);
    fireEvent.scroll(panel);
    expect(history).toHaveBeenCalledOnce();
  } finally {
    vi.unstubAllGlobals();
  }
});

test.each(["forum topic", "saved source"])("keeps the visible row in place after removing an earlier row from %s", async (mode) => {
  const early = { id: "10", text: "Removed fixture", author: "Fixture", time: "" };
  const visible = { ...early, id: "20", text: "Visible position fixture" };
  const topic = { id: 17, name: "Deletion fixture topic", closed: false };
  const load = vi.fn(async () => ({ messages: [early, visible], before: null }));
  const sourceActions = { history: load, list: async () => ({ sources: [{ id: "42", title: "Deletion fixture source", pinned: false }], next: null }) };
  const { ForumTopics } = await import("../src/ui/forum-topics.tsx");
  const renderHistory = (deletedIds?: ReadonlySet<string>) => mode === "forum topic"
    ? <ForumTopics chatId="-42" topics={[topic]} initialTopic={topic} loadForumTopics={async () => [topic]}
        loadTopicHistory={load} loadPhoto={undefined} saveDocument={undefined} deletedIds={deletedIds} close={() => {}} />
    : <SavedSources chatId="42" close={() => {}} actions={sourceActions} media={{}} deletedIds={deletedIds} />;
  const { rerender } = render(renderHistory());
  if (mode === "saved source") fireEvent.click(await screen.findByRole("button", { name: "Deletion fixture source" }));
  const visibleRow = (await screen.findByText(visible.text)).closest("li")!;
  const list = mode === "forum topic" ? screen.getByRole("list", { name: "Topic messages" })
    : screen.getByRole("region", { name: "Saved Messages by chat" });
  const hasEarlier = () => list.querySelector('[data-message-id="10"]') !== null;
  panelLayout(list, hasEarlier);
  vi.spyOn(visibleRow, "getBoundingClientRect").mockImplementation(() =>
    new DOMRect(0, 210 + (hasEarlier() ? 80 : 0) - list.scrollTop, 100, 80));
  list.scrollTop = 250;
  fireEvent.scroll(list);
  expect(visibleRow.getBoundingClientRect().top).toBe(40);
  rerender(renderHistory(new Set(["10"])));
  expect(screen.queryByText(early.text)).toBeNull();
  expect(screen.getByText(visible.text).closest("li")).toBe(visibleRow);
  expect(list.scrollTop).toBe(170);
  expect(visibleRow.getBoundingClientRect().top).toBe(40);
  expect(load).toHaveBeenCalledTimes(1);

  function panelLayout(list: HTMLElement, earlierExists: () => boolean) {
    Object.defineProperties(list, { scrollHeight: { get: () => earlierExists() ? 700 : 620 }, clientHeight: { value: 200 } });
  }
});

test.each([false, true])("updates an open saved source without stitching a gap (%s)", async (gap) => {
  const first = { id: "20", text: "Already visible note", author: "Fixture", time: "" };
  const newer = { ...first, id: "40", text: "New saved note" };
  const history = vi.fn().mockResolvedValueOnce({ messages: [first], before: "20" })
    .mockResolvedValueOnce({ messages: gap ? [newer] : [newer, first], before: gap ? "40" : "20" });
  const actions = { history, list: async () => ({ sources: [{ id: "42", title: "Live saved source", pinned: false }], next: null }) };
  const renderSource = (liveRevision: number) => <SavedSources chatId="42" liveRevision={liveRevision} close={() => {}} media={{}} actions={actions} />;
  const { rerender } = render(renderSource(0));
  fireEvent.click(await screen.findByRole("button", { name: "Live saved source" }));
  const row = (await screen.findByText(first.text)).closest("li")!;
  const panel = screen.getByRole("region", { name: "Saved Messages by chat" });
  const newerExists = () => !!panel.querySelector('[data-message-id="40"]');
  const layoutShift = () => newerExists() ? 80 : within(panel).queryByRole("button", { name: "Jump to latest saved messages" }) ? 35 : 0;
  Object.defineProperties(panel, { scrollHeight: { get: () => 700 + layoutShift() }, clientHeight: { value: 200 } });
  vi.spyOn(row, "getBoundingClientRect").mockImplementation(() =>
    new DOMRect(0, 290 + layoutShift() - panel.scrollTop, 100, 80));
  panel.scrollTop = 250;
  fireEvent.scroll(panel);
  rerender(renderSource(1));
  if (gap) {
    const jump = await screen.findByRole("button", { name: "Jump to latest saved messages" });
    expect(screen.queryByText(newer.text)).toBeNull();
    expect(panel.scrollTop).toBe(285);
    expect(row.getBoundingClientRect().top).toBe(40);
    fireEvent.click(jump);
    expect(screen.queryByText(first.text)).toBeNull();
    expect(panel.scrollTop).toBe(0);
  } else {
    await screen.findByText(newer.text);
    expect(screen.getByText(first.text).closest("li")).toBe(row);
    expect(panel.scrollTop).toBe(330);
    expect(row.getBoundingClientRect().top).toBe(40);
  }
  expect(screen.getByText(newer.text)).toBeTruthy();
  expect(history.mock.calls.map(([id, before]) => [id, before])).toEqual([["42", undefined], ["42", undefined]]);
});

test("keeps the visible saved row and its loaded content when an overlapping page arrives", async () => {
  const first = { id: "20", text: "Current saved fixture", author: "Fixture", time: "" };
  const earlier = { ...first, id: "10", text: "Earlier saved fixture" };
  let finish!: (page: { messages: (typeof first)[]; before: string | null }) => void;
  const pending = new Promise<{ messages: (typeof first)[]; before: string | null }>((resolve) => { finish = resolve; });
  const history = vi.fn().mockResolvedValueOnce({ messages: [first], before: "20" }).mockReturnValueOnce(pending);
  render(<SavedSources chatId="42" close={() => {}} media={{}} actions={{
    history, list: async () => ({ sources: [{ id: "42", title: "Saved source fixture", pinned: false }], next: null }),
  }} />);
  fireEvent.click(await screen.findByRole("button", { name: "Saved source fixture" }));
  const row = (await screen.findByText(first.text)).closest("li")!;
  const panel = screen.getByRole("region", { name: "Saved Messages by chat" });
  const appended = () => panel.querySelector('[data-message-id="10"]') !== null;
  Object.defineProperties(panel, { scrollHeight: { get: () => appended() ? 850 : 700 }, clientHeight: { value: 200 } });
  vi.spyOn(row, "getBoundingClientRect").mockImplementation(() => new DOMRect(0,
    500 + (appended() ? 70 : 0) - panel.scrollTop, 100, 100));
  panel.scrollTop = 450;
  fireEvent.scroll(panel);
  await waitFor(() => expect(history).toHaveBeenCalledTimes(2));
  await act(async () => finish({ messages: [{ ...first, text: "Stale overlap fixture" }, earlier], before: "10" }));
  expect(screen.getByText(first.text).closest("li")).toBe(row);
  expect(screen.queryByText("Stale overlap fixture")).toBeNull();
  expect(screen.getByText(earlier.text)).toBeTruthy();
  expect(panel.scrollTop).toBe(520);
  expect(row.getBoundingClientRect().top).toBe(50);
  fireEvent.scroll(panel);
  expect(history).toHaveBeenCalledTimes(2);
});

