test.each(["Group", "Direct message"])("opens a wallpaper link in a %s and reviews the exact private chat before applying", async (subtitle) => {
  const origin = { id: subtitle === "Group" ? "-42" : "42", name: "Wallpaper source", initials: "W",
    color: "#246dbd", subtitle, messages: [] };
  const other = { ...origin, id: "43", name: "Wallpaper destination", subtitle: "Direct message" };
  const destination = subtitle === "Group" ? other : origin;
  const revision = "1".repeat(64);
  const updatedRevision = "2".repeat(64);
  const previewLink = vi.fn(async () => ({ revision, fill: { kind: "solid" as const, color: "#123456" } }));
  const load = vi.fn().mockResolvedValueOnce({ revision: null }).mockResolvedValue({ revision: updatedRevision });
  const saveLink = vi.fn().mockResolvedValueOnce("changed").mockResolvedValue("saved");
  const prototype = HTMLDialogElement.prototype;
  const showModal = Object.getOwnPropertyDescriptor(prototype, "showModal");
  const close = Object.getOwnPropertyDescriptor(prototype, "close");
  Object.defineProperties(prototype, {
    showModal: { configurable: true, value(this: HTMLDialogElement) { this.open = true; } },
    close: { configurable: true, value(this: HTMLDialogElement) { this.open = false; this.dispatchEvent(new Event("close")); } },
  });
  try {
    render(<TelegramPage live={{
      chats: [origin, other], folders: [], list: "main", selectList: () => {}, refresh: () => {}, loading: false, liveRevision: 0, error: "",
      loadHistory: async (id) => ({ before: null, messages: id === origin.id ? [{
        id: "7", author: "Fixture", time: "", text: "Open wallpaper",
        links: [{ offset: 0, length: 14, url: "tg://bg?color=123456" }],
      }] : [] }),
      findChats: async () => [other], sendText: vi.fn(), chatBackgroundActions: { load, previewLink, saveLink, save: vi.fn() },
    }} />);
    fireEvent.click(screen.getByRole("button", { name: /Wallpaper source/ }));
    const link = await screen.findByRole("link", { name: "Open wallpaper" });
    expect(link.getAttribute("href")).toBe("https://t.me/bg/123456");
    fireEvent.click(link);
    if (subtitle === "Group") {
      const picker = within(await screen.findByRole("dialog", { name: "Choose a private chat for the wallpaper" }));
      fireEvent.click(picker.getByRole("button", { name: "Show recent chats" }));
      expect(picker.queryByRole("button", { name: /Wallpaper source/ })).toBeNull();
      fireEvent.click(await picker.findByRole("button", { name: /Wallpaper destination/ }));
    } else {
      expect(screen.queryByRole("dialog", { name: "Choose a private chat for the wallpaper" })).toBeNull();
    }
    const dialog = within(await screen.findByRole("dialog", { name: "Telegram wallpaper" }));
    expect(dialog.getByText(destination.name)).toBeTruthy();
    expect(await dialog.findByRole("img", { name: "Telegram color wallpaper preview" })).toBeTruthy();
    expect(previewLink).toHaveBeenCalledExactlyOnceWith(destination.id, "https://t.me/bg/123456");
    expect(saveLink).not.toHaveBeenCalled();
    fireEvent.click(dialog.getByRole("button", { name: "Apply wallpaper for me" }));
    await dialog.findByRole("alert");
    expect(dialog.queryByRole("button", { name: "Apply wallpaper for me" })).toBeNull();
    fireEvent.click(dialog.getByRole("button", { name: "Reload wallpaper preview" }));
    fireEvent.click(await dialog.findByRole("button", { name: "Apply wallpaper for me" }));
    await dialog.findByText("Chat background saved.");
    expect(saveLink.mock.calls).toEqual([
      [destination.id, null, "https://t.me/bg/123456", revision],
      [destination.id, updatedRevision, "https://t.me/bg/123456", revision],
    ]);
    const done = dialog.getByRole("button", { name: "Done" });
    expect(document.activeElement).toBe(done);
    fireEvent.click(done);
    expect(screen.queryByRole("dialog", { name: "Telegram wallpaper" })).toBeNull();
    expect(screen.getByRole("heading", { name: "Wallpaper source" })).toBeTruthy();
  } finally {
    if (showModal) Object.defineProperty(prototype, "showModal", showModal);
    else Reflect.deleteProperty(prototype, "showModal");
    if (close) Object.defineProperty(prototype, "close", close);
    else Reflect.deleteProperty(prototype, "close");
  }
});

