test("opens device review from a Telegram sign-in notice and removes it when confirmed", async () => {
  const app = await loadPluginApp(() => import("../app.tsx"));
  const slot = app.navPanels.find(({ id }) => id === "telegram")!;
  const id = "-9007199254741022";
  const revision = "a".repeat(64);
  let pending = false;
  const sessionRpc = vi.fn((input: unknown) => {
    const { method } = input as { method: string };
    switch (method) {
      case "chatPage": return { chats: [], nextOffset: null };
      case "folderLayout": return { folders: [] };
      case "pendingDeviceSignIns": return pending ? 1 : 0;
      case "activeDevices": return [{ id, device: "Fixture device", application: "Fixture", platform: "",
        activeAt: 0, current: false, ...(pending && { unconfirmed: { signedInAt: 0, location: "", revision } }) }];
      case "confirmDevice": pending = false; return "confirmed";
      default: return null;
    }
  });
  const view = renderSlot(slot, { subPath: "" }, { rpc: {
    status: () => ({ state: "ready", connectionId: "00000000-0000-4000-8000-000000000001" }),
    sessionRpc,
  } });
  await view.findByRole("button", { name: "Telegram settings" });
  const settings = view.container.querySelector<HTMLDialogElement>('dialog[aria-label="Telegram settings"]')!;
  settings.showModal = () => { settings.open = true; };
  expect(view.queryByRole("button", { name: "Review devices" })).toBeNull();
  pending = true;
  await view.emitRealtime(deviceSignInsChangedChannel, {});
  await view.emitRealtime(messageNotificationChannel, { connectionId: "00000000-0000-4000-8000-000000000001",
    event: { key: "1:1", chatId: "42", messageId: "20" } });
  expect(view.getByRole("complementary", { name: "Telegram notification" })).toBeTruthy();
  fireEvent.click(await view.findByRole("button", { name: "Dismiss sign-in notice" }));
  expect(view.getByRole("complementary", { name: "Telegram notification" })).toBeTruthy();
  expect(view.queryByRole("button", { name: "Review devices" })).toBeNull();
  await view.emitRealtime(deviceSignInsChangedChannel, {});
  fireEvent.click(await view.findByRole("button", { name: "Review devices" }));
  const dialog = view.getByRole("dialog", { name: "Telegram settings" });
  const location = within(dialog);
  const review = await location.findByRole("button", { name: "Review sign-in" });
  expect(location.getByRole("region", { name: "Devices" })).toBeTruthy();
  expect(location.queryByRole("region", { name: "Media cache" })).toBeNull();
  fireEvent.click(review);
  fireEvent.click(location.getByRole("button", { name: "Confirm sign-in" }));
  await location.findByText("Telegram session confirmed.");
  expect(sessionRpc.mock.calls.map(([call]) => call as { method: string }).filter(({ method }) => method === "confirmDevice"))
    .toEqual([expect.objectContaining({ payload: { id, revision } })]);
  await view.emitRealtime(deviceSignInsChangedChannel, {});
  await waitFor(() => expect(view.queryByRole("button", { name: "Review devices" })).toBeNull());
});

test.each([false, true])("opens the reviewed shortcut from the composer (changed in Telegram: %s)", async (changed) => {
  const app = await loadPluginApp(() => import("../app.tsx"));
  const slot = app.navPanels.find(({ id }) => id === "telegram")!;
  const connectionId = "00000000-0000-4000-8000-000000000001";
  const sessionRpc = vi.fn(({ method, payload }: { method: string; payload?: unknown }) => {
    switch (method) {
      case "chatPage": return { chats: [{ id: "42", name: "Fixture peer", initials: "F", color: "#246dbd",
        subtitle: "Direct message", messages: [] }], nextOffset: null };
      case "folderLayout": return { folders: [] };
      case "history": return { messages: [], before: null };
      case "postingPermissions": return { text: true };
      case "peerPresence": return { state: "unavailable" };
      case "quickReplies": return [{ id: 2, name: "other", messageCount: 1 },
        { id: 7, name: changed && payload === null ? "renamed" : "hours", messageCount: 1 }];
      case "quickReplyMessages": return [{ id: 9, text: "Fixture shortcut message", editRevision: "a".repeat(64) }];
      default: return null;
    }
  });
  const view = renderSlot(slot, { subPath: "" }, { rpc: {
    status: () => ({ state: "ready", connectionId }),
    sessionRpc: (input) => sessionRpc(input as { method: string; payload?: unknown }),
  } });
  await view.findByRole("button", { name: "Telegram settings" });
  const settings = view.container.querySelector<HTMLDialogElement>('dialog[aria-label="Telegram settings"]')!;
  settings.showModal = () => { settings.open = true; };
  settings.close = () => { settings.open = false; fireEvent(settings, new Event("close")); };
  fireEvent.click(await view.findByRole("button", { name: /Fixture peer/ }));
  const draft = view.getByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement;
  fireEvent.change(draft, { target: { value: "/hou" } });
  fireEvent.click(await view.findByRole("button", { name: "Edit /hours" }));
  const dialog = within(view.getByRole("dialog", { name: "Telegram settings" }));
  expect(dialog.getByRole("region", { name: "Telegram Business" })).toBeTruthy();
  if (changed) {
    await dialog.findByText("This shortcut changed in Telegram. Select a shortcut from the current list.");
    expect(dialog.getByRole("button", { name: "Show messages /renamed" })).toBeTruthy();
    expect(sessionRpc.mock.calls.some(([call]) => call.method === "quickReplyMessages")).toBe(false);
  } else {
    expect(await dialog.findByText("Fixture shortcut message")).toBeTruthy();
    expect(dialog.getByRole("button", { name: "Edit message 1" })).toBeTruthy();
    expect(dialog.getByRole("button", { name: "Show messages /other" })).toBeTruthy();
    expect(document.activeElement?.textContent).toBe("/hours");
    expect(sessionRpc.mock.calls.filter(([call]) => call.method === "quickReplyMessages")).toEqual([
      [{ connectionId, method: "quickReplyMessages", payload: { id: 7 } }],
    ]);
  }
  expect(sessionRpc.mock.calls.some(([call]) => call.method === "sendQuickReply" || call.method === "editQuickReplyText")).toBe(false);
  fireEvent.click(dialog.getByRole("button", { name: "Done" }));
  expect(draft.value).toBe("/hou");
  fireEvent.click(view.getByRole("button", { name: "Telegram settings" }));
  expect(view.navigateCalls).toContainEqual({ method: "toPluginPanel", path: "telegram", options: { subPath: "settings" } });
  expect(settings.open).toBe(false);
});

test.each([true, false])("omits an absent forum topic when jumping to a date through BB (scoped: %s)", async (scoped) => {
  const app = await loadPluginApp(() => import("../app.tsx"));
  const slot = app.navPanels.find(({ id }) => id === "telegram")!;
  const connectionId = "00000000-0000-4000-8000-000000000001";
  const chatPage = () => ({ chats: [{ id: "42", name: "Date fixture chat", initials: "D", color: "#246dbd", subtitle: "Direct message", messages: [] }], nextOffset: null });
  const history = () => ({ messages: [{ id: "29", text: "Recent fixture", author: "Fixture", time: "",
    timestamp: new Date(2026, 2, 30, 9).getTime() / 1000 }], before: null });
  const messageAtDate = vi.fn((payload: unknown) => Object.hasOwn(payload as object, "topicId") ? null : "27");
  const messageContext = () => [{ id: "27", text: "Date-selected fixture", author: "Fixture", time: "" }];
  const folderLayout = () => ({ folders: [] });
  const peerPresence = () => ({ state: "unavailable" });
  const view = renderSlot(slot, { subPath: "" }, { rpc: {
    status: () => ({ state: "ready", ...(scoped && { connectionId }) }), chatPage, history, unreadHistory: () => null,
    messageAtDate, messageContext, folderLayout, peerPresence,
    sessionRpc: (input) => {
      const call = input as { method: string; payload: unknown; connectionId: string };
      expect(call.connectionId).toBe(connectionId);
      if (call.method === "chatPage") return chatPage();
      if (call.method === "history") return history();
      if (call.method === "folderLayout") return folderLayout();
      if (call.method === "peerPresence") return peerPresence();
      if (call.method === "messageAtDate") return messageAtDate(call.payload);
      if (call.method === "messageContext") return messageContext();
      return null;
    },
  } });
  fireEvent.click(await view.findByRole("button", { name: /Date fixture chat/ }));
  fireEvent.click(await view.findByRole("button", { name: /^Jump to date from/ }));
  fireEvent.change(view.getByLabelText("Jump to date"), { target: { value: "2026-03-29" } });
  fireEvent.click(view.getByRole("button", { name: "Go to date" }));
  await view.findByText("Date-selected fixture");
  expect(messageAtDate).toHaveBeenCalledExactlyOnceWith({ id: "42", date: new Date(2026, 2, 30).getTime() / 1000 - 1 });
});

test("restores an account’s formatted draft without showing it in another account’s chat", async () => {
  const app = await loadPluginApp(() => import("../app.tsx"));
  const slot = app.navPanels.find(({ id }) => id === "telegram")!;
  let connectionId = "00000000-0000-4000-8000-000000000001";
  const personal = "00000000-0000-4000-8000-000000000004";
  let draftScope = personal;
  let name = "First connection";
  let accountLabel = "Personal fixture";
  const list = () => ({ chats: [{ id: "42", name, initials: "F", color: "#246dbd", subtitle: "Direct message", messages: [] }],
    nextOffset: null });
  const sessionRpc = vi.fn(({ method }: { method: string }) => {
    if (method === "chatPage") return list();
    if (method === "folderLayout") return { folders: [] };
    if (method === "history") return { messages: [], before: null };
    if (method === "peerPresence") return { state: "unavailable" };
    return null;
  });
  const { getByRole, findByRole, queryByRole, getByText, queryByText, getByLabelText } = renderSlot(slot, { subPath: "" }, { rpc: {
    status: () => ({ state: "ready", connectionId, accountLabel, draftScope }),
    sessionRpc: (input) => sessionRpc(input as { method: string }),
  } });
  fireEvent.click(await findByRole("button", { name: /First connection/ }));
  const first = (getByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement);
  expect(getByText("Personal fixture")).toBeTruthy();
  fireEvent.change(first, { target: { value: "First connection draft" } });
  first.setSelectionRange(0, 5);
  fireEvent.keyDown(first, { code: "KeyB", metaKey: true });
  expect(getByLabelText("Formatted message preview").querySelector(".mtg-text-bold")?.textContent).toBe("First");
  await waitFor(() => expect(sessionRpc).toHaveBeenCalledWith({ connectionId, method: "history", payload: { id: "42" } }));
  connectionId = "00000000-0000-4000-8000-000000000002";
  draftScope = "00000000-0000-4000-8000-000000000005";
  name = "Second connection";
  accountLabel = "Work fixture";
  const second = await findByRole("button", { name: /Second connection/ }, { timeout: 3500 });
  expect(sessionRpc).toHaveBeenCalledWith({ connectionId, method: "chatPage", payload: { list: "main", offset: 0 } });
  expect(queryByRole("heading", { name: "First connection" })).toBeNull();
  fireEvent.click(second);
  expect(queryByText("Personal fixture")).toBeNull();
  expect(getByText("Work fixture")).toBeTruthy();
  expect((getByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement).value).toBe("");
  fireEvent.change(getByRole("textbox", { name: "Write a message" }), { target: { value: "Work fixture draft" } });

  connectionId = "00000000-0000-4000-8000-000000000003";
  draftScope = personal;
  name = "First connection";
  accountLabel = "Personal fixture";
  fireEvent.click(await findByRole("button", { name: /First connection/ }, { timeout: 3500 }));
  expect((getByRole("textbox", { name: "Write a message" }) as HTMLTextAreaElement).value).toBe("First connection draft");
  expect(getByLabelText("Formatted message preview").querySelector(".mtg-text-bold")?.textContent).toBe("First");
}, 10_000);

