  const panel = within(screen.getByRole("region", { name: "Forum topics" }));
  const first = panel.getByRole("button", { name: /First fixture topic.*2/ });
  const second = panel.getByRole("button", { name: /Second fixture topic/ });
  const last = panel.getByRole("button", { name: "Third fixture topic" });
