  fireEvent.click(screen.getByRole("button", { name: "Remove last option" }));
  expect(screen.getByRole<HTMLButtonElement>("button", { name: "Remove last option" }).disabled).toBe(true);
  fireEvent.change(screen.getByRole("textbox", { name: "Question" }), { target: { value: "Fixture question" } });
  fireEvent.change(screen.getByRole("textbox", { name: "Option 1" }), { target: { value: "Only answer" } });
  fireEvent.click(screen.getByText("Links for answer options"));
